        .OrderBy(moby => moby.TrueIndex)
        .ToArray();
    if (dreamWallLanterns.Length != 2 || dreamWallLanterns.Any(moby =>
        moby.Type != 0x20 || moby.State != 0x00 || moby.SourceByte4F != 0x00 ||
        moby.Flag4A != 0x10 || moby.Flag4B != 0xFF || moby.YawByte != 0x00 ||
