    Dictionary<(string LevelKey, int TrueIndex), int> bossPhaseRewardClasses = new()
    {
        [("toasty", 53)] = 0x55,
        [("doctorshemp", 70)] = 0x56,
        [("doctorshemp", 71)] = 0x55,
        [("blowhard", 73)] = 0x56,
        [("blowhard", 74)] = 0x56
