    Dictionary<(string LevelKey, int TrueIndex), string> bossPhaseRewardLabels = new()
    {
        [("toasty", 53)] = "Toasty phase-reward Blue gem marker",
        [("doctorshemp", 70)] = "Doctor Shemp phase-reward Yellow gem marker",
