    UniversalNativeChestCloneExportReport cloneReport = await ReportUniversalNativeChestCloneExports(report);

    if (report.Levels.Count(level => level.Key.Strategy == "universal-lightweight") != report.Levels.Count)
        throw new InvalidOperationException("Universal chest strategy expected every level to support lightweight keys.");

    CrossLevelChestLevelStrategy stoneHill = report.Levels.First(level => string.Equals(level.LevelKey, "stonehill", StringComparison.OrdinalIgnoreCase));
    if (stoneHill.KeyChest.Strategy != "native-clone" || stoneHill.KeyChest.FirstNativeTrueIndex < 0)
        throw new InvalidOperationException("Stone Hill should use its native Key Chest donor path instead of cross-level package import.");
    if (stoneHill.SpringChest.Strategy == "native-clone")
        throw new InvalidOperationException("Stone Hill should not claim native Spring Chest cloning; it has no native 0x0149 source records.");

    int nativeKeyChests = report.Levels.Count(level => level.KeyChest.Strategy == "native-clone");
    int nativeSpringChests = report.Levels.Count(level => level.SpringChest.Strategy == "native-clone");
    int nativeFireworkChests = report.Levels.Count(level => level.FireworkChest.Strategy == "native-clone");
    int nativeMultiGemChests = report.Levels.Count(level => level.MultiGemChest.Strategy == "native-clone");
    int packageWork = report.Levels.Count(level =>
        level.KeyChest.Strategy.Contains("package", StringComparison.OrdinalIgnoreCase) ||
        level.SpringChest.Strategy.Contains("package", StringComparison.OrdinalIgnoreCase) ||
        level.FireworkChest.Strategy.Contains("package", StringComparison.OrdinalIgnoreCase) ||
        level.MultiGemChest.Strategy.Contains("package", StringComparison.OrdinalIgnoreCase));
    if (report.Levels.Any(level =>
        !string.Equals(level.FireworkChest.ActorIdHex, "0x0138", StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(level.MultiGemChest.ActorIdHex, "0x0186", StringComparison.OrdinalIgnoreCase)))
    {
        throw new InvalidOperationException("Universal chest strategy did not retain the Firework Chest and 3x Flame Chest actor identities.");
    }
    if (!cloneReport.Rows.Any(row =>
        string.Equals(row.LevelKey, "stonehill", StringComparison.OrdinalIgnoreCase) &&
        string.Equals(row.ActorIdHex, "0x00AE", StringComparison.OrdinalIgnoreCase) &&
        string.Equals(row.Status, "proved", StringComparison.OrdinalIgnoreCase)))
    {
        throw new InvalidOperationException("Native chest clone proof did not prove Stone Hill's native Key Chest donor path.");
    }

    int blockedCloneProofs = cloneReport.Rows.Count(row => !string.Equals(row.Status, "proved", StringComparison.OrdinalIgnoreCase));
    Console.WriteLine($"Universal chest strategy: native key-chest clone levels={nativeKeyChests}, native spring-chest clone levels={nativeSpringChests}, native firework-chest clone levels={nativeFireworkChests}, native 3x-flame-chest clone levels={nativeMultiGemChests}, package-work levels={packageWork}, blocked clone proofs={blockedCloneProofs}, report={markdownPath}");
}

async Task ReportUniversalChestPackageRecipePlanner()
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine("Universal chest package planner: source disc not found; skipping.");
        return;
    }

    CrossLevelChestPackageRecipePlanReport report = CrossLevelChestPackageRecipePlanner.Build(workspace, catalog, sourceImage);
    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke");
    Directory.CreateDirectory(outDir);
    string jsonPath = Path.Combine(outDir, "universal-chest-package-recipe-planner.json");
    string markdownPath = Path.Combine(outDir, "universal-chest-package-recipe-planner.md");
    await CrossLevelChestPackageRecipePlanner.WriteAsync(report, jsonPath, markdownPath);

    int plannedKeyChests = report.Rows.Count(row => row.CanPlan && string.Equals(row.Family, "lockedChest", StringComparison.OrdinalIgnoreCase));
    int plannedSpringChests = report.Rows.Count(row => row.CanPlan && string.Equals(row.Family, "springChest", StringComparison.OrdinalIgnoreCase));
    int neededKeyChests = report.Rows.Count(row => string.Equals(row.CurrentStrategy, "needs-package-recipe", StringComparison.OrdinalIgnoreCase) && string.Equals(row.Family, "lockedChest", StringComparison.OrdinalIgnoreCase));
    int neededSpringChests = report.Rows.Count(row => string.Equals(row.CurrentStrategy, "needs-package-recipe", StringComparison.OrdinalIgnoreCase) && string.Equals(row.Family, "springChest", StringComparison.OrdinalIgnoreCase));
    int plannedNeededKeyChests = report.Rows.Count(row => row.CanPlan && string.Equals(row.CurrentStrategy, "needs-package-recipe", StringComparison.OrdinalIgnoreCase) && string.Equals(row.Family, "lockedChest", StringComparison.OrdinalIgnoreCase));
    int plannedNeededSpringChests = report.Rows.Count(row => row.CanPlan && string.Equals(row.CurrentStrategy, "needs-package-recipe", StringComparison.OrdinalIgnoreCase) && string.Equals(row.Family, "springChest", StringComparison.OrdinalIgnoreCase));
    if (neededKeyChests == 0 || neededSpringChests == 0)
        throw new InvalidOperationException("Universal chest package planner did not retain the levels that still need native package work.");
    if (plannedSpringChests == 0)
        throw new InvalidOperationException("Universal Spring Chest package planner should retain at least one structurally safe actor-subfile-local candidate.");
    if (plannedNeededKeyChests > neededKeyChests || plannedNeededSpringChests > neededSpringChests)
        throw new InvalidOperationException("Universal chest package planner should not plan more recipes than levels that need package recipes.");
    if (report.Rows.Any(row => row.CanPlan &&
        (string.IsNullOrWhiteSpace(row.TargetPackageStartHex) ||
         string.IsNullOrWhiteSpace(row.RootSlotHex) ||
         !row.Notes.Any(note => note.Contains("zero-run search was limited to this range", StringComparison.OrdinalIgnoreCase)))))
    {
        throw new InvalidOperationException("Universal chest package planner emitted a candidate without actor/model-subfile and ordered-root safety evidence.");
    }

    CrossLevelChestPackageRecipePlanRow[] artisansRows = report.Rows
        .Where(row => string.Equals(LevelCatalog.NormalizeKey(row.LevelKey), "artisans", StringComparison.OrdinalIgnoreCase))
        .ToArray();
    if (artisansRows.Length != 2 ||
        artisansRows.Any(row => row.CanPlan) ||
        artisansRows.Any(row => !row.Notes.Any(note => note.Contains("No actor/model-subfile-local zero run", StringComparison.OrdinalIgnoreCase))))
    {
        throw new InvalidOperationException("Artisans must remain unplannable until a package route fits inside its actor/model subfile without breaking root order.");
    }

    Console.WriteLine($"Universal chest package planner: key-chest plans={plannedKeyChests} ({plannedNeededKeyChests}/{neededKeyChests} missing), spring-chest plans={plannedSpringChests} ({plannedNeededSpringChests}/{neededSpringChests} missing), report={markdownPath}");
}

async Task<UniversalNativeChestCloneExportReport> ReportUniversalNativeChestCloneExports(CrossLevelChestStrategyReport strategyReport)
{
    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke", "native-chest-clone-edits");
    Directory.CreateDirectory(outDir);
    SourceDiscLayout layout = DetectSourceDiscLayout(sourceImage);
    using FileStream stream = File.OpenRead(sourceImage);

    List<UniversalNativeChestCloneExportRow> rows = [];
    foreach (CrossLevelChestLevelStrategy strategyLevel in strategyReport.Levels.OrderBy(level => level.LevelName, StringComparer.OrdinalIgnoreCase))
    {
        LevelDefinition? level = catalog.FindByKey(strategyLevel.LevelKey);
        if (level?.HasSourceTable != true)
            continue;

        List<Moby> edits = [];
        int nextIndex = 0;
        int nextTrueIndex = level.SourceRecordCount;

        if (strategyLevel.KeyChest.Strategy == "native-clone")
        {
            Moby keyChest = CreateNativeChestCloneMoby(stream, layout, level, strategyLevel.KeyChest, nextIndex++, nextTrueIndex++, "Native Key Chest");
            Moby key = CreateUniversalKeyMoby(
                level,
                nextIndex++,
                nextTrueIndex++,
                strategyLevel.KeyChest.DisplayName,
                new Vector3f(keyChest.Position.X - 160, keyChest.Position.Y, keyChest.Position.Z));
            edits.Add(key);
            edits.Add(keyChest);
        }

        if (strategyLevel.SpringChest.Strategy == "native-clone")
            edits.Add(CreateNativeChestCloneMoby(stream, layout, level, strategyLevel.SpringChest, nextIndex++, nextTrueIndex++, "Native Spring Chest"));

        if (edits.Count == 0)
            continue;

        string editPath = Path.Combine(outDir, $"{strategyLevel.LevelKey}-native-chest-clones.json");
        await MobyEditStore.SaveAsync(editPath, edits, $"{strategyLevel.LevelName} native chest clone proof");
        MobySourcePatchPlan plan;
        try
        {
            plan = MobySourcePatchExporter.BuildPlan(
                sourceImage,
                DiscImageLocator.FindCueForImage(sourceImage),
                Path.Combine(workspace.RootPath, "_local", "objects", "native-chest-clone-proofs", $"{strategyLevel.LevelKey}.bin"),
                Path.Combine(workspace.RootPath, "_local", "objects", "native-chest-clone-proofs", $"{strategyLevel.LevelKey}.cue"),
                level,
                editPath);
        }
        catch (Exception ex) when (ex is InvalidOperationException or IOException or JsonException)
        {
            rows.Add(new UniversalNativeChestCloneExportRow(
                LevelKey: strategyLevel.LevelKey,
                LevelName: strategyLevel.LevelName,
                ObjectName: "Native chest clone proof",
                ActorIdHex: "",
                TrueIndex: -1,
                PatchCount: 0,
                HasSpecialClone: false,
                EditPath: editPath,
                Status: "blocked",
                Notes: ex.Message));
            continue;
        }

        if (plan.SkippedEdits.Count != 0)
            throw new InvalidOperationException($"{strategyLevel.LevelName} native chest clone proof skipped edit(s): {string.Join("; ", plan.SkippedEdits)}");
        if (plan.PackageImportPreviews.Count != 0 || plan.Patches.Any(patch => patch.Kind.Contains("actor-package", StringComparison.OrdinalIgnoreCase)))
            throw new InvalidOperationException($"{strategyLevel.LevelName} native chest clone proof should not use actor-package imports.");

        bool hasSourceCountPatch = plan.Patches.Any(patch => string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase));

        foreach (Moby edit in edits)
        {
            MobySourcePatch? append = plan.Patches.FirstOrDefault(patch =>
                string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase) &&
                string.Equals(patch.MobyLabel, edit.Label, StringComparison.OrdinalIgnoreCase));
            MobySourcePatch? autoSlot = plan.Patches.FirstOrDefault(patch =>
                string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase) &&
                string.Equals(patch.MobyLabel, edit.Label, StringComparison.OrdinalIgnoreCase));
            MobySourcePatch? recordPatch = append ?? autoSlot;
            if (recordPatch == null)
                throw new InvalidOperationException($"{strategyLevel.LevelName} native clone proof did not export {edit.Label} through append or auto-slot reuse.");

            byte[] after = ParseHexPreview(recordPatch.AfterHexPreview);
            int actorId = after[0x36] | (after[0x37] << 8);
            if (edit.SourceByte36 != after[0x36] || edit.SourceByte37 != after[0x37])
                throw new InvalidOperationException($"{strategyLevel.LevelName} native clone proof wrote the wrong actor bytes for {edit.Label}.");

            bool reusedSourceSlot = autoSlot != null;
            string rowStatus = reusedSourceSlot || hasSourceCountPatch ? "proved" : "candidate-no-count-field";
            string rowNotes = reusedSourceSlot
                ? $"Reused source slot T{autoSlot!.TrueIndex}; no new source row was appended."
                : hasSourceCountPatch
                ? ""
                : string.Join(" ", plan.Notes.Where(note => note.Contains("bytes before the source moby table", StringComparison.OrdinalIgnoreCase)));
            bool shouldHaveSpecialClone = !reusedSourceSlot && edit.Type == 0x20 && edit.SpecialDataPointer != 0;
            bool hasSpecialClone = plan.Patches.Any(patch =>
                string.Equals(patch.Kind, "moby-special-data-clone", StringComparison.OrdinalIgnoreCase) &&
                string.Equals(patch.MobyLabel, edit.Label, StringComparison.OrdinalIgnoreCase));
            if (shouldHaveSpecialClone && !hasSpecialClone)
                throw new InvalidOperationException($"{strategyLevel.LevelName} native clone proof did not clone special data for {edit.Label}.");

            rows.Add(new UniversalNativeChestCloneExportRow(
                LevelKey: strategyLevel.LevelKey,
                LevelName: strategyLevel.LevelName,
                ObjectName: edit.Label,
                ActorIdHex: $"0x{actorId:X4}",
                TrueIndex: recordPatch.TrueIndex,
                PatchCount: plan.PatchCount,
                HasSpecialClone: hasSpecialClone,
                EditPath: editPath,
                Status: rowStatus,
                Notes: rowNotes));
        }
    }

    int keyChestProofs = rows.Count(row => row.Status == "proved" && string.Equals(row.ActorIdHex, "0x00AE", StringComparison.OrdinalIgnoreCase));
    int springChestProofs = rows.Count(row => row.Status == "proved" && string.Equals(row.ActorIdHex, "0x0149", StringComparison.OrdinalIgnoreCase));
    UniversalNativeChestCloneExportReport report = new(DateTimeOffset.Now, keyChestProofs, springChestProofs, rows);
    string jsonPath = Path.Combine(workspace.RootPath, "_local", "smoke", "universal-native-chest-clone-export.json");
    string markdownPath = Path.Combine(workspace.RootPath, "_local", "smoke", "universal-native-chest-clone-export.md");
    await File.WriteAllTextAsync(jsonPath, JsonSerializer.Serialize(report, new JsonSerializerOptions { WriteIndented = true }));
    await File.WriteAllTextAsync(markdownPath, BuildUniversalNativeChestCloneExportMarkdown(report));
    int blocked = rows.Count(row => row.Status == "blocked");
    int candidateNoCount = rows.Count(row => row.Status == "candidate-no-count-field");
    Console.WriteLine($"Universal native chest clone export: key-chest proofs={keyChestProofs}, spring-chest proofs={springChestProofs}, blocked={blocked}, count-field candidates={candidateNoCount}, report={markdownPath}");
    return report;
}

Moby CreateUniversalKeyMoby(LevelDefinition level, int index, int trueIndex, string companionName, Vector3f position)
{
    return new Moby
    {
        Index = index,
        TrueIndex = trueIndex,
        LegacyIndex = MobyLoader.GetLegacyAliasIndex(trueIndex),
        Position = position,
        OriginalPosition = position,
        Type = 0x18,
        OriginalType = 0x18,
        State = 0,
        OriginalState = 0,
        SourceByte36 = 0xAD,
        OriginalSourceByte36 = 0xAD,
        SourceByte37 = 0x00,
        SourceByte4F = 0x02,
        OriginalSourceByte4F = 0x02,
        Flag4A = 0x40,
        Flag4B = 0xFF,
        OriginalFlag4B = 0xFF,
        Color = GemValue.Yellow.Color,
        Label = $"Universal Key for {companionName}",
        OriginalLabel = $"Universal Key for {companionName}",
        PatchStatus = "supported-lightweight-object",
        PatchLead = $"Universal key paired with a native {companionName} clone in {level.DisplayName}.",
        CrossLevelTemplateId = "common.key.peacekeepers.t78",
        CrossLevelFamily = "key",
        CrossLevelSourceLevelKey = "PeaceKeepers",
        CrossLevelSourceLevelName = "Peace Keepers",
        CrossLevelSourceTrueIndex = 78,
        CrossLevelRequiredExporterFeature = "DirectSourceRecordAppend",
        CrossLevelRecipeId = "smoke.recipe.pin.v1",
        IsAdded = true
    };
}

Moby CreateNativeChestCloneMoby(FileStream stream, SourceDiscLayout layout, LevelDefinition level, ChestObjectStrategy strategy, int index, int trueIndex, string label)
{
    if (strategy.FirstNativeTrueIndex < 0)
        throw new InvalidOperationException($"{level.DisplayName} has no native donor for {strategy.DisplayName}.");

    long tableWadOffset = ParseFlexibleLong(level.SourceTableWadOffset);
    byte[] record = ReadSourceWadBytes(stream, layout, tableWadOffset + ((long)strategy.FirstNativeTrueIndex * 0x58), 0x58);
    Vector3f donorPosition = new(
        BitConverter.ToInt32(record, 0x0C) / 16f,
        BitConverter.ToInt32(record, 0x10) / 16f,
        BitConverter.ToInt32(record, 0x14) / 16f);
    Vector3f position = new(donorPosition.X + 128 + (index * 32), donorPosition.Y, donorPosition.Z);
    int actorId = record[0x36] | (record[0x37] << 8);
    uint specialOffset = BitConverter.ToUInt32(record, 0);
    return new Moby
    {
        Index = index,
        TrueIndex = trueIndex,
        LegacyIndex = MobyLoader.GetLegacyAliasIndex(trueIndex),
        Position = position,
        OriginalPosition = position,
        Type = record[0x50],
        OriginalType = record[0x50],
        State = record[0x51],
        OriginalState = record[0x51],
        YawByte = record[0x46],
        OriginalYawByte = record[0x46],
        SourceByte36 = record[0x36],
        OriginalSourceByte36 = record[0x36],
        SourceByte37 = record[0x37],
        OriginalSourceByte37 = record[0x37],
        SourceByte4F = record[0x4F],
        OriginalSourceByte4F = record[0x4F],
        Flag4A = record[0x52],
        OriginalFlag4A = record[0x52],
        Flag4B = record[0x53],
        OriginalFlag4B = record[0x53],
        SpecialDataPointer = specialOffset,
        Color = Moby.ColorForType(record[0x50]),
        Label = $"{level.DisplayName} {label}",
        OriginalLabel = $"{level.DisplayName} {label}",
        CandidateKind = $"{strategy.DisplayName} native clone",
        Confidence = "native-clone-proof",
        Evidence = $"Cloned from {level.DisplayName} T{strategy.FirstNativeTrueIndex}, actor 0x{actorId:X4}.",
        PatchStatus = "native-clone",
        PatchLead = $"Same-level clone from {level.DisplayName} {strategy.DisplayName} donor T{strategy.FirstNativeTrueIndex}; no actor-package import expected.",
        IsAdded = true
    };
}

string BuildUniversalNativeChestCloneExportMarkdown(UniversalNativeChestCloneExportReport report)
{
    StringBuilder builder = new();
    builder.AppendLine("# Universal Native Chest Clone Export");
    builder.AppendLine();
    builder.AppendLine("This proves the levels where Key Chests or Spring Chests can be added by cloning native same-level donors, without actor-package imports.");
    builder.AppendLine();
    builder.AppendLine($"Key Chest proofs: {report.KeyChestProofs}");
    builder.AppendLine($"Spring Chest proofs: {report.SpringChestProofs}");
    builder.AppendLine();
    builder.AppendLine("| Level | Object | Actor | New T | Special cloned | Status | Notes | Edit manifest |");
    builder.AppendLine("|---|---|---|---:|---|---|---|---|");
    foreach (UniversalNativeChestCloneExportRow row in report.Rows.OrderBy(row => row.LevelName, StringComparer.OrdinalIgnoreCase).ThenBy(row => row.ObjectName, StringComparer.OrdinalIgnoreCase))
        builder.AppendLine($"| {MarkdownCell(row.LevelName)} | {MarkdownCell(row.ObjectName)} | `{row.ActorIdHex}` | {row.TrueIndex} | {row.HasSpecialClone} | {MarkdownCell(row.Status)} | {MarkdownCell(row.Notes)} | `{row.EditPath}` |");
    return builder.ToString();
}

string BuildUniversalChestCompatibilityMarkdown(IReadOnlyList<CrossLevelObjectImportRow> rows, int levelCount)
{
    StringBuilder builder = new();
    builder.AppendLine("# Universal Chest Compatibility");
    builder.AppendLine();
    builder.AppendLine("This report tracks public beta cross-level Keys and Key Chests. Spring Chests are kept in the dedicated diagnostic report until their behavior is proven in-game.");
    builder.AppendLine();
    builder.AppendLine($"Levels covered: {levelCount}");
    builder.AppendLine();
    builder.AppendLine("| Object | Supported | Needs RAM | Missing package | Missing signature | Recipe mapped |");
    builder.AppendLine("|---|---:|---:|---:|---:|---:|");
    foreach (IGrouping<string, CrossLevelObjectImportRow> group in rows.GroupBy(row => row.DisplayName).OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase))
    {
        int supported = CountStatus(group, "supported-lightweight-object");
        int needsRam = CountStatus(group, "needs-target-ram-capture");
        int missingPackage = CountStatus(group, "blocked-missing-target-actor-package");
        int missingSignature = CountStatus(group, "blocked-missing-template-signature");
        int recipeMapped = group.Count(row => !string.IsNullOrWhiteSpace(row.RecipeId));
        builder.AppendLine($"| {MarkdownCell(group.Key)} | {supported} | {needsRam} | {missingPackage} | {missingSignature} | {recipeMapped} |");
    }

    builder.AppendLine();
    builder.AppendLine("| Level | Key | Key Chest | Next Action |");
    builder.AppendLine("|---|---|---|---|");
    foreach (IGrouping<string, CrossLevelObjectImportRow> levelGroup in rows.GroupBy(row => row.TargetLevelName).OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase))
    {
        CrossLevelObjectImportRow? key = levelGroup.FirstOrDefault(row => string.Equals(row.Family, "key", StringComparison.OrdinalIgnoreCase));
        CrossLevelObjectImportRow? lockedChest = levelGroup.FirstOrDefault(row => string.Equals(row.Family, "lockedChest", StringComparison.OrdinalIgnoreCase));
        string nextAction = PickUniversalChestNextAction(lockedChest, springChest: null);
        builder.AppendLine($"| {MarkdownCell(levelGroup.Key)} | {MarkdownCell(StatusWithRecipe(key))} | {MarkdownCell(StatusWithRecipe(lockedChest))} | {MarkdownCell(nextAction)} |");
    }

    return builder.ToString();
}

int UniversalChestSort(string family)
{
    return family switch
    {
        "key" => 0,
        "lockedChest" => 1,
        "springChest" => 2,
        _ => 9
    };
}

int CountStatus(IEnumerable<CrossLevelObjectImportRow> rows, string status)
{
    return rows.Count(row => string.Equals(row.SupportStatus, status, StringComparison.OrdinalIgnoreCase));
}

string StatusWithRecipe(CrossLevelObjectImportRow? row)
{
    if (row == null)
        return "missing";
    if (string.IsNullOrWhiteSpace(row.RecipeId))
        return row.SupportStatus;
    return $"{row.SupportStatus}; {row.RecipeId}";
}

string PickUniversalChestNextAction(CrossLevelObjectImportRow? lockedChest, CrossLevelObjectImportRow? springChest)
{
    if (lockedChest?.SupportStatus == "needs-target-ram-capture" || springChest?.SupportStatus == "needs-target-ram-capture")
        return "Capture before-clean RAM for actor pointer table.";
    if (lockedChest != null && string.IsNullOrWhiteSpace(lockedChest.RecipeId) && lockedChest.SupportStatus.Contains("actor-package", StringComparison.OrdinalIgnoreCase))
        return "Map Key Chest package import recipe.";
    if (springChest != null && string.IsNullOrWhiteSpace(springChest.RecipeId) && springChest.SupportStatus.Contains("actor-package", StringComparison.OrdinalIgnoreCase))
        return "Map Spring Chest package import recipe.";
    if (lockedChest != null && !string.IsNullOrWhiteSpace(lockedChest.RecipeId) && !string.Equals(lockedChest.RecipeStatus, "verified-image-write", StringComparison.OrdinalIgnoreCase))
        return "Run guarded Key Chest candidate test.";
    if (springChest != null && !string.IsNullOrWhiteSpace(springChest.RecipeId) && !string.Equals(springChest.RecipeStatus, "verified-image-write", StringComparison.OrdinalIgnoreCase))
        return "Run guarded Spring Chest candidate test.";
    if (lockedChest != null && string.IsNullOrWhiteSpace(lockedChest.RecipeId) && lockedChest.SupportStatus.Contains("template-signature", StringComparison.OrdinalIgnoreCase))
        return "Identify this level's native Key Chest signature/special-data.";
    if (springChest != null && string.IsNullOrWhiteSpace(springChest.RecipeId) && springChest.SupportStatus.Contains("template-signature", StringComparison.OrdinalIgnoreCase))
        return "Identify this level's native Spring Chest signature/special-data.";
    return "Ready or already native-supported.";
}

string MarkdownCell(string value)
{
    return (value ?? "").Replace("|", "\\|", StringComparison.Ordinal).Replace("\n", " ", StringComparison.Ordinal);
}

void ReportCrossLevelEditorTemplateReadiness()
{
    string templatePath = workspace.ResolveFile("spyro-object-templates.json");
    if (!File.Exists(templatePath))
        throw new FileNotFoundException("Missing cross-level object template catalog.", templatePath);

    using FileStream stream = File.OpenRead(templatePath);
    using JsonDocument document = JsonDocument.Parse(stream);
    JsonElement[] allTemplates = document.RootElement.GetProperty("templates")
        .EnumerateArray()
        .ToArray();
    JsonElement[] templates = allTemplates
        .Where(template => ReadJsonBool(template, "showInAddList"))
        .ToArray();

    JsonElement key = FindTemplate(templates, "common.key.peacekeepers.t78");
    JsonElement springChest = FindTemplate(allTemplates, CurrentStoneHillSpringTemplateId);
    JsonElement keyChest = FindTemplate(templates, "common.locked_chest.peacekeepers.t79");
    JsonElement greenWizard = FindTemplate(templates, "enemy.green_wizard.wizardpeak.t6");
    JsonElement gnastySpringChest = FindTemplate(templates, GnastyLootSpringTemplateId);
    JsonElement fireworkChest = FindTemplate(templates, GnastyLootFireworkTemplateId);
    JsonElement multiGemChest = FindTemplate(templates, GnastyLootMultiGemChestTemplateId);
    if (templates.Any(template => string.Equals(ReadJsonString(template, "id"), CurrentStoneHillSpringTemplateId, StringComparison.OrdinalIgnoreCase)))
        throw new InvalidOperationException("Editor Add Object templates should hide cross-level Spring Chest until it passes in-game.");

    LevelDefinition artisans = catalog.FindByKey("artisans") ?? throw new InvalidOperationException("Artisans level missing.");
    LevelDefinition toasty = catalog.FindByKey("toasty") ?? throw new InvalidOperationException("Toasty level missing.");
    LevelDefinition blowhard = catalog.FindByKey("blowhard") ?? throw new InvalidOperationException("Blowhard level missing.");
    LevelDefinition magicCrafters = catalog.FindByKey("magiccrafters") ?? throw new InvalidOperationException("Magic Crafters level missing.");
    LevelDefinition wizardPeak = catalog.FindByKey("wizardpeak") ?? throw new InvalidOperationException("Wizard Peak level missing.");
    LevelDefinition? stoneHillLevel = catalog.FindByKey("stonehill") ?? throw new InvalidOperationException("Stone Hill level missing.");

    CrossLevelTemplateLevelStatus artisansKey = ResolveTemplateStatus(artisans, key);
    CrossLevelTemplateLevelStatus artisansKeyChest = ResolveTemplateStatus(artisans, keyChest);
    CrossLevelTemplateLevelStatus stoneHillSpring = ResolveTemplateStatus(stoneHillLevel, springChest);
    CrossLevelTemplateLevelStatus artisansSpring = ResolveTemplateStatus(artisans, springChest);
    CrossLevelTemplateLevelStatus toastyWizard = ResolveTemplateStatus(toasty, greenWizard);
    CrossLevelTemplateLevelStatus blowhardWizard = ResolveTemplateStatus(blowhard, greenWizard);
    CrossLevelTemplateLevelStatus magicCraftersWizard = ResolveTemplateStatus(magicCrafters, greenWizard);
    CrossLevelTemplateLevelStatus wizardPeakWizard = ResolveTemplateStatus(wizardPeak, greenWizard);
    CrossLevelTemplateLevelStatus stoneHillWizard = ResolveTemplateStatus(stoneHillLevel, greenWizard);
    CrossLevelTemplateLevelStatus stoneHillGnastySpring = ResolveTemplateStatus(stoneHillLevel, gnastySpringChest);
    CrossLevelTemplateLevelStatus stoneHillFirework = ResolveTemplateStatus(stoneHillLevel, fireworkChest);
    CrossLevelTemplateLevelStatus stoneHillMultiGemChest = ResolveTemplateStatus(stoneHillLevel, multiGemChest);
    bool hasSourceDiscForCandidateChecks = File.Exists(sourceImage);

    if (!ArtisansNativeLockedChestRuntimeBundleComposer.IsAvailable ||
        !artisansKey.Ready ||
        !artisansKey.Placeable ||
        !artisansKey.TrueAddPlaceable ||
        !string.Equals(artisansKey.ShortLabel, "ready here", StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(artisansKey.RecipeId, ArtisansNativeLockedChestRuntimeBundleCompatibility.RecipeId, StringComparison.Ordinal) ||
        !artisansKeyChest.Ready ||
        !artisansKeyChest.Placeable ||
        !artisansKeyChest.TrueAddPlaceable ||
        !string.Equals(artisansKeyChest.ShortLabel, "ready here", StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(artisansKeyChest.RecipeId, ArtisansNativeLockedChestRuntimeBundleCompatibility.RecipeId, StringComparison.Ordinal))
    {
        throw new InvalidOperationException("Editor readiness should expose both halves of the runtime-proven one-pair Artisans native Key + Locked Chest V2 bundle to normal Create BIN.");
    }
    if (catalog.Levels.Count != 35)
        throw new InvalidOperationException($"Cross-level Key/Locked Chest readiness smoke expected all 35 catalog levels, found {catalog.Levels.Count}.");
    foreach (LevelDefinition level in catalog.Levels)
    {
        CrossLevelTemplateLevelStatus keyStatus = ResolveTemplateStatus(level, key);
        CrossLevelTemplateLevelStatus chestStatus = ResolveTemplateStatus(level, keyChest);
        if (keyStatus != chestStatus)
            throw new InvalidOperationException($"Key + Locked Chest must share one atomic readiness state in {level.DisplayName}.");

        string normalizedLevelKey = LevelCatalog.NormalizeKey(level.Key);
        bool isFlight = normalizedLevelKey is "sunnyflight" or "nightflight" or "crystalflight" or "wildflight" or "icyflight";
        SpecialChestBundleProfile? profile = SpecialChestBundleProfileRegistry.Find(
            SpecialChestFamily.LockedChest,
            normalizedLevelKey,
            SpecialChestBundleProfileRegistry.CleanUsaImageSha256);
        if (isFlight)
        {
            if (profile != null || keyStatus.Ready || keyStatus.Placeable || keyStatus.TrueAddPlaceable ||
                !string.Equals(keyStatus.ShortLabel, "blocked in flights", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException($"Key + Locked Chest must remain blocked in flight stage {level.DisplayName}.");
            }
            continue;
        }

        if (profile == null)
            throw new InvalidOperationException($"Missing checked Key + Locked Chest profile for {level.DisplayName}.");
        (bool ready, bool placeable, bool trueAddPlaceable, string shortLabel) = profile.Availability switch
        {
            SpecialChestBundleAvailability.NormalCreateBinReady => (true, true, true, "ready here"),
            SpecialChestBundleAvailability.CandidatePlanOnly => (false, true, true, "test CUE only"),
            SpecialChestBundleAvailability.NativeClosurePresent => (false, true, true, "test CUE only"),
            _ => (false, false, false, "blocked here")
        };
        if (keyStatus.Ready != ready ||
            keyStatus.Placeable != placeable ||
            keyStatus.TrueAddPlaceable != trueAddPlaceable ||
            !string.Equals(keyStatus.ShortLabel, shortLabel, StringComparison.OrdinalIgnoreCase) ||
            !string.Equals(keyStatus.RecipeId, profile.RecipeId, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                $"Key + Locked Chest readiness does not match checked profile {profile.Id} in {level.DisplayName}.");
        }
    }

    (int Keys, int Chests, bool Pair, bool StandaloneKey, bool ChestForExistingKey)[] addPolicyCases =
    [
        (0, 0, true, true, false),
        (1, 0, false, false, true),
        (0, 1, false, true, false),
        (1, 1, false, false, false),
        (2, 0, false, false, false),
        (0, 2, false, true, false),
        (2, 1, false, false, false)
    ];
    foreach ((int keys, int chests, bool pair, bool standaloneKey, bool chestForExistingKey) in addPolicyCases)
    {
        LockedChestRuntimeBundleAddPolicy policy = LockedChestRuntimeBundleAddPolicy.Resolve(keys, chests);
        if (policy.OfferPair != pair ||
            policy.OfferStandaloneKey != standaloneKey ||
            policy.OfferLockedChestForExistingKey != chestForExistingKey ||
            policy.AllowLockedChestTemplate != (pair || chestForExistingKey))
        {
            throw new InvalidOperationException(
                $"Key + Locked Chest release Add Object policy changed for {keys} Key(s)/{chests} Locked Chest(s): {policy}.");
        }
    }

    CrossLevelActorPackageRecipe historicalFailedArtisansRecipe = CrossLevelActorPackageRecipeCatalog.All.Single(recipe =>
        string.Equals(recipe.Id, "artisans.peacekeepers.lockedChest.package.safeGapActorId.v4", StringComparison.OrdinalIgnoreCase));
    if (!historicalFailedArtisansRecipe.Status.StartsWith("in-game-blocked", StringComparison.OrdinalIgnoreCase))
        throw new InvalidOperationException("The failed Artisans actor-root slot-swap v4 recipe must remain blocked historical evidence after V2 promotion.");

    if (hasSourceDiscForCandidateChecks)
    {
        if (!artisansKey.Ready)
            throw new InvalidOperationException("The Artisans Key must remain ready as part of its runtime-proven atomic bundle.");
        if (stoneHillSpring.Ready ||
            stoneHillSpring.Placeable ||
            stoneHillSpring.TrueAddPlaceable ||
            !string.Equals(stoneHillSpring.ShortLabel, "blocked here", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("Editor readiness should block Spring Chest in Stone Hill after the latest in-game failure.");
        }
        if (artisansSpring.Ready ||
            artisansSpring.Placeable ||
            artisansSpring.TrueAddPlaceable ||
            !string.Equals(artisansSpring.ShortLabel, "blocked here", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("Editor readiness should block the Artisans Spring Chest root replacement that would corrupt the Life Statue actor.");
        }
        if (toastyWizard.Ready ||
            toastyWizard.Placeable ||
            !string.Equals(toastyWizard.ShortLabel, "blocked here", StringComparison.OrdinalIgnoreCase) ||
            !string.Equals(toastyWizard.RecipeId, GreenWizardRuntimeBundleCompatibility.ToastyV11RecipeId, StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("Editor readiness should keep the runtime-proven Toasty v11 Wizard blocked until its standalone exporter is composed into the editor.");
        }
        if (!blowhardWizard.Ready ||
            !blowhardWizard.Placeable ||
            blowhardWizard.TrueAddPlaceable ||
            !string.Equals(blowhardWizard.ShortLabel, "ready here", StringComparison.OrdinalIgnoreCase) ||
            !string.Equals(blowhardWizard.RecipeId, BlowhardGreenWizardResidentSwapExporter.RecipeId, StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("Editor readiness should expose runtime-proven Blowhard Green Wizard Replace to normal Create BIN while keeping true Add unavailable.");
        }
        if (!magicCraftersWizard.Ready ||
            !magicCraftersWizard.Placeable ||
            magicCraftersWizard.TrueAddPlaceable ||
            !string.Equals(magicCraftersWizard.ShortLabel, "ready here", StringComparison.OrdinalIgnoreCase) ||
            !string.Equals(magicCraftersWizard.RecipeId, MagicCraftersGreenWizardResidentSwapExporter.RecipeId, StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("Editor readiness should expose the exact runtime-proven Magic Crafters T107-to-T27 Green Wizard Replace route to normal Create BIN while keeping true Add unavailable.");
        }
        if (!wizardPeakWizard.Ready ||
            !wizardPeakWizard.Placeable ||
            wizardPeakWizard.TrueAddPlaceable ||
            !string.Equals(wizardPeakWizard.ShortLabel, "ready here", StringComparison.OrdinalIgnoreCase) ||
            !string.Equals(wizardPeakWizard.RecipeId, WizardPeakGreenWizardNativeSwapExporter.RecipeId, StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("Editor readiness should expose the exact runtime-proven Wizard Peak native T6-to-T24 route to normal Create BIN while keeping true Add unavailable.");
        }
        if (stoneHillWizard.Ready ||
            stoneHillWizard.Placeable ||
            !string.Equals(stoneHillWizard.ShortLabel, "preview here", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("Editor readiness should guard Green Wizard in unmapped levels like Stone Hill.");
        }
    }
    else
    {
        Console.WriteLine("Cross-level editor readiness: source disc not found; guarded candidate recipe assertions skipped for tester package.");
    }
    if (!CrossLevelEditorTemplateSupport.CanTransform(MobyVisualKind.Actor, "enemyTransform") ||
        CrossLevelEditorTemplateSupport.CanTransform(MobyVisualKind.Chest, "enemyTransform") ||
        CrossLevelEditorTemplateSupport.CanTransform(MobyVisualKind.Actor, "lockedChest") ||
        !CrossLevelEditorTemplateSupport.CanTransform(MobyVisualKind.Chest, "lockedChest") ||
        !CrossLevelEditorTemplateSupport.CanTransform(MobyVisualKind.Chest, "springChest") ||
        !CrossLevelEditorTemplateSupport.CanTransform(MobyVisualKind.Chest, "fireworkChest") ||
        !CrossLevelEditorTemplateSupport.CanTransform(MobyVisualKind.Chest, "multiGemChest"))
    {
        throw new InvalidOperationException("Editor transform filtering should keep enemy transforms on actors and chest transforms on chests.");
    }
    if (stoneHillGnastySpring.Ready ||
        stoneHillGnastySpring.Placeable ||
        !string.Equals(stoneHillGnastySpring.ShortLabel, "blocked here", StringComparison.OrdinalIgnoreCase) ||
        stoneHillFirework.Ready ||
        stoneHillFirework.Placeable ||
        !string.Equals(stoneHillFirework.ShortLabel, "blocked here", StringComparison.OrdinalIgnoreCase) ||
        stoneHillMultiGemChest.Ready ||
        stoneHillMultiGemChest.Placeable ||
        !string.Equals(stoneHillMultiGemChest.ShortLabel, "blocked here", StringComparison.OrdinalIgnoreCase))
    {
        throw new InvalidOperationException("Spring, Firework, and 3x Flame chests must remain blocked in Stone Hill until their dependency bundles pass runtime proof.");
    }

    JsonElement[] gnastyChestCandidates = [gnastySpringChest, fireworkChest, multiGemChest];
    foreach (LevelDefinition level in catalog.Levels.Where(level => level.HasSourceTable))
    {
        foreach (JsonElement template in gnastyChestCandidates)
        {
            CrossLevelTemplateLevelStatus status = ResolveTemplateStatus(level, template);
            if (!SpecialChestEditorTemplateGate.TryMapFamily(
                    ReadJsonString(template, "family"),
                    out SpecialChestFamily family))
            {
                throw new InvalidOperationException($"Special-chest template {ReadJsonString(template, "id")} did not map to a registry family.");
            }
            string normalizedLevelKey = LevelCatalog.NormalizeKey(level.Key);
            bool isFlight = normalizedLevelKey is "sunnyflight" or "nightflight" or "crystalflight" or "wildflight" or "icyflight";
            SpecialChestBundleProfile? profile = SpecialChestBundleProfileRegistry.Find(
                family,
                normalizedLevelKey,
                SpecialChestBundleProfileRegistry.CleanUsaImageSha256);
            if (isFlight)
            {
                if (profile != null || status.Ready || status.Placeable || status.TrueAddPlaceable ||
                    !string.Equals(status.ShortLabel, "blocked in flights", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException($"Special-chest template {ReadJsonString(template, "id")} is not blocked in flight stage {level.DisplayName}.");
                }
                continue;
            }

            if (profile == null)
                throw new InvalidOperationException($"Missing checked {family} profile for {level.DisplayName}.");
            (bool ready, bool placeable, bool trueAddPlaceable, string shortLabel) = profile.Availability switch
            {
                SpecialChestBundleAvailability.NormalCreateBinReady => (true, true, true, "ready here"),
                SpecialChestBundleAvailability.CandidatePlanOnly => (false, true, true, "test CUE only"),
                SpecialChestBundleAvailability.NativeClosurePresent => (false, true, true, "test CUE only"),
                _ => (false, false, false, "blocked here")
            };
            if (status.Ready != ready ||
                status.Placeable != placeable ||
                status.TrueAddPlaceable != trueAddPlaceable ||
                !string.Equals(status.ShortLabel, shortLabel, StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(status.RecipeId, profile.RecipeId, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"Special-chest template {ReadJsonString(template, "id")} does not match checked profile {profile.Id} in {level.DisplayName}.");
            }
        }
    }

    Console.WriteLine("Cross-level editor readiness: Blowhard, exact Magic Crafters T107-to-T27, and exact Wizard Peak T6-to-T24 v3 Green Wizard routes are runtime-proven; T10 v1/v2 remain blocked, Toasty v11 waits for editor composition, and true Wizard Add/unmapped levels stay blocked.");

    JsonElement FindTemplate(IEnumerable<JsonElement> templates, string id)
    {
        foreach (JsonElement template in templates)
        {
            if (string.Equals(ReadJsonString(template, "id"), id, StringComparison.OrdinalIgnoreCase))
                return template;
        }

        throw new InvalidOperationException($"Missing cross-level editor template {id}.");
    }

    CrossLevelTemplateLevelStatus ResolveTemplateStatus(LevelDefinition level, JsonElement template)
    {
        return CrossLevelEditorTemplateSupport.ResolveLevelStatus(
            level,
            ReadJsonString(template, "sourceLevelKey"),
            ReadJsonString(template, "family"),
            ReadJsonString(template, "addSupportStatus"),
            workspace.RootPath);
    }
}

async Task ReportSpringChestDependencyAudit()
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine("Spring Chest dependency audit: source disc not found; skipping.");
        return;
    }

    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke");
    Directory.CreateDirectory(outDir);
    CrossLevelSpringChestDependencyReport report = CrossLevelSpringChestDependencyAnalyzer.Build(workspace, catalog, sourceImage);
    string jsonPath = Path.Combine(outDir, "spring-chest-dependency-audit.json");
    string markdownPath = Path.Combine(outDir, "spring-chest-dependency-audit.md");
    await CrossLevelSpringChestDependencyAnalyzer.WriteAsync(report, jsonPath, markdownPath);

    SpringChestLevelDependencySummary? stoneHillSummary = report.Levels.FirstOrDefault(level =>
        string.Equals(level.LevelKey, "stonehill", StringComparison.OrdinalIgnoreCase));
    SpringChestLevelDependencySummary[] nativeSummaries = report.Levels
        .Where(level => !string.Equals(level.LevelKey, "stonehill", StringComparison.OrdinalIgnoreCase))
        .ToArray();
    if (stoneHillSummary == null || stoneHillSummary.SpringChestRecordCount != 0 || stoneHillSummary.ActorId0149RecordCount != 0)
        throw new InvalidOperationException("Stone Hill should have no native spring chest records while the import remains guarded.");
    if (nativeSummaries.Length < 3 || nativeSummaries.Any(level => level.SpringChestRecordCount == 0 || level.ActorId0149RecordCount == 0))
        throw new InvalidOperationException("Spring Chest dependency audit did not find native spring chest examples in Town Square, Peace Keepers, and Dry Canyon.");
    if (nativeSummaries.Any(level => level.DistinctSourceSpecialDataHashes.Count == 0 || level.DistinctRuntimeSpecialDataPointers.Count == 0))
        throw new InvalidOperationException("Native spring chest examples should carry source special data and runtime special-data pointers.");

    Console.WriteLine($"Spring Chest dependency audit: native examples={nativeSummaries.Sum(level => level.SpringChestRecordCount)}, Stone Hill native records=0, report={markdownPath}");
}

async Task ReportSpringChestInteractionDiagnostic()
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine("Spring Chest interaction diagnostic: source disc not found; skipping.");
        return;
    }

    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke");
    Directory.CreateDirectory(outDir);
    SpringChestInteractionDiagnosticReport report = SpringChestInteractionDiagnostic.Build(workspace, catalog, sourceImage);
    string jsonPath = Path.Combine(outDir, "spring-chest-interaction-diagnostic.json");
    string markdownPath = Path.Combine(outDir, "spring-chest-interaction-diagnostic.md");
    await SpringChestInteractionDiagnostic.WriteAsync(report, jsonPath, markdownPath);

    if (report.LatestCandidate.BehaviorCorrect == true)
        throw new InvalidOperationException("The guarded Stone Hill Spring Chest candidate should not be marked behavior-correct until it works in-game.");
    if (report.NativeClusters.Count == 0)
        throw new InvalidOperationException("Spring Chest interaction diagnostic did not find native Spring Chest clusters to compare.");

    int comparedPairs = report.RamPairDiagnostics.Count(pair => string.Equals(pair.Status, "compared", StringComparison.OrdinalIgnoreCase));
    Console.WriteLine($"Spring Chest interaction diagnostic: native clusters={report.NativeClusters.Count}, RAM pairs compared={comparedPairs}, report={markdownPath}");
}

bool ReadJsonBool(JsonElement element, string name, bool fallback = false)
{
    if (!element.TryGetProperty(name, out JsonElement property))
        return fallback;

    return property.ValueKind switch
    {
        JsonValueKind.True => true,
        JsonValueKind.False => false,
        JsonValueKind.String => bool.TryParse(property.GetString(), out bool value) ? value : fallback,
        _ => fallback
    };
}

bool HasConflictingObservedMetadata(JsonElement item, Moby moby)
{
    int type = ReadJsonInt32(item, "typeHex", -1);
    if (type >= 0 && type != moby.Type)
        return true;

    int sourceByte36 = ReadJsonInt32(item, "sourceByte36Hex", -1);
    if (sourceByte36 >= 0 && sourceByte36 != moby.SourceByte36)
        return true;

    int sourceByte4F = ReadJsonInt32(item, "sourceByte4FHex", -1);
    if (sourceByte4F >= 0 && sourceByte4F != moby.SourceByte4F)
        return true;

    int flag4B = ReadJsonInt32(item, "flag4BHex", -1);
    return flag4B >= 0 && flag4B != moby.Flag4B;
}

string LevelKeyFromObservationFile(string path)
{
    string name = Path.GetFileName(path);
    foreach (string suffix in new[] { "-moby-user-overrides.json", "-live-validation-overrides.json" })
    {
        if (name.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
            return name[..^suffix.Length];
    }

    return "";
}

IEnumerable<string> EnumerateObservationFiles()
{
    foreach (string searchRoot in new[] { workspace.RootPath, Path.Combine(workspace.RootPath, "support") }.Where(Directory.Exists))
    {
        foreach (string path in Directory.GetFiles(searchRoot, "*-moby-user-overrides.json"))
            yield return path;
        foreach (string path in Directory.GetFiles(searchRoot, "*-live-validation-overrides.json"))
            yield return path;
    }
}

IdentityFingerprintParts ParseIdentityFingerprint(string fingerprint)
{
    if (!MobyIdentityFingerprint.TryParse(fingerprint, out MobyIdentityFingerprintParts parts))
        return new IdentityFingerprintParts("", "", "", "", "", "", "");

    return new IdentityFingerprintParts(
        $"0x{parts.RenderRadius:X2}",
        $"0x{parts.NativeClass & 0xFF:X2}",
        parts.HasFullNativeClass ? $"0x{parts.NativeClass >> 8:X2}" : "",
        parts.HasFullNativeClass ? $"0x{parts.NativeClass:X4}" : "",
        $"0x{parts.UpdateDistance:X2}",
        $"0x{parts.DropClass:X2}",
        $"0x{parts.SpecularMetalType:X2}");
}

bool FingerprintMatchesParts(
    string fingerprint,
    int nativeClass,
    int renderRadius,
    int updateDistance,
    int dropClass,
    int specularMetalType)
{
    return MobyIdentityFingerprint.TryParse(fingerprint, out MobyIdentityFingerprintParts parts) &&
        parts.HasFullNativeClass &&
        parts.NativeClass == (nativeClass & 0xFFFF) &&
        parts.RenderRadius == (renderRadius & 0xFF) &&
        parts.UpdateDistance == (updateDistance & 0xFF) &&
        parts.DropClass == (dropClass & 0xFF) &&
        parts.SpecularMetalType == (specularMetalType & 0xFF);
}

List<(LevelDefinition Level, Moby Moby)> SelectBatchSamples(
    PrecisionIdentityGroup group,
    IReadOnlyList<(LevelDefinition Level, Moby Moby)> allMobys)
{
    return allMobys
        .Where(item => string.Equals(IdentityFingerprint(item.Moby), group.Key, StringComparison.OrdinalIgnoreCase))
        .GroupBy(item => item.Level.Key, StringComparer.OrdinalIgnoreCase)
        .OrderByDescending(levelGroup => levelGroup.Count())
        .ThenBy(levelGroup => levelGroup.First().Level.DisplayName)
        .FirstOrDefault()?
        .OrderBy(item => item.Moby.TrueIndex)
        .Take(4)
        .ToList() ?? new List<(LevelDefinition Level, Moby Moby)>();
}

bool CanWriteIdentityEditBatch(string lane, IReadOnlyList<(LevelDefinition Level, Moby Moby)> samples)
{
    return !string.Equals(lane, "control/helper", StringComparison.OrdinalIgnoreCase) &&
        samples.Count > 0 &&
        samples.All(sample => sample.Moby.TrueIndex >= 0) &&
        samples.Select(sample => sample.Level.Key).Distinct(StringComparer.OrdinalIgnoreCase).Count() == 1;
}

bool CanWriteControlClusterIdentityEditBatch(string lane, IReadOnlyList<(LevelDefinition Level, Moby Moby)> samples)
{
    return string.Equals(lane, "control/helper", StringComparison.OrdinalIgnoreCase) &&
        samples.Count > 0 &&
        samples.All(sample => sample.Moby.TrueIndex >= 0) &&
        samples.Select(sample => sample.Level.Key).Distinct(StringComparer.OrdinalIgnoreCase).Count() == 1;
}

async Task<string?> WriteControlClusterIdentityEditBatch(
    string batchDir,
    int batchNumber,
    PrecisionIdentityGroup group,
    IReadOnlyList<(LevelDefinition Level, Moby Moby)> samples,
    IReadOnlyList<(LevelDefinition Level, Moby Moby)> allMobys)
{
    (LevelDefinition level, Moby target) = samples[0];
    string fingerprint = group.Key;
    List<Moby> anchors = allMobys
        .Where(item => string.Equals(item.Level.Key, level.Key, StringComparison.OrdinalIgnoreCase))
        .Where(item => item.Moby.TrueIndex != target.TrueIndex)
        .Where(item => !string.Equals(IdentityFingerprint(item.Moby), fingerprint, StringComparison.OrdinalIgnoreCase))
        .Where(item => IsExactIdentity(item.Moby))
        .Where(item => item.Moby.VisualKind is not MobyVisualKind.Control and not MobyVisualKind.Unknown)
        .Select(item => new
        {
            item.Moby,
            Distance = Math.Sqrt(DistanceSquared(item.Moby.OriginalPosition, target.OriginalPosition))
        })
        .Where(item => item.Distance <= 896)
        .OrderBy(item => item.Distance)
        .ThenBy(item => item.Moby.TrueIndex)
        .Take(3)
        .Select(item => item.Moby)
        .ToList();

    if (anchors.Count == 0)
        return null;

    Vector3f delta = new(384, 0, 96);
    List<Moby> edited = new() { target };
    edited.AddRange(anchors);
    List<(Moby Moby, Vector3f Position, string Label)> restore = edited
        .Select(moby => (moby, moby.Position, moby.Label))
        .ToList();

    try
    {
        target.Position = OffsetPosition(target.OriginalPosition, delta);
        target.Label = $"Control cluster {batchNumber}: {group.PreferredLabelForLevel(level.Key)}";
        for (int i = 0; i < anchors.Count; i++)
        {
            Moby anchor = anchors[i];
            anchor.Position = OffsetPosition(anchor.OriginalPosition, delta);
            anchor.Label = $"Cluster {batchNumber} anchor {i + 1}: {anchor.DisplayLabel}";
        }

        string editManifest = Path.Combine(batchDir, $"{level.Key}-identity-batch-{batchNumber:00}-control-cluster-native-edits.json");
        await MobyEditStore.SaveAsync(editManifest, edited, $"{level.DisplayName} control identity cluster {batchNumber}");
        return editManifest;
    }
    finally
    {
        foreach ((Moby moby, Vector3f position, string label) in restore)
        {
            moby.Position = position;
            moby.Label = label;
        }
    }
}

Vector3f OffsetPosition(Vector3f position, Vector3f delta)
{
    return new Vector3f(position.X + delta.X, position.Y + delta.Y, position.Z + delta.Z);
}

string IdentityFingerprint(Moby moby)
{
    return MobyIdentityFingerprint.BuildV2(moby);
}

string IdentityTestLane(PrecisionIdentityGroup group)
{
    string text = $"{group.Label} {group.Kind} {group.Key}".ToLowerInvariant();
    if (text.Contains("flight target") || text.Contains("flight object"))
        return "flight/special object";
    if (text.Contains("nonvisual") || text.Contains("control") || text.Contains("helper"))
        return "control/helper";
    if (text.Contains("actor") || text.Contains("enemy") || text.Contains("container") || text.Contains("drop53=0x10") || text.Contains("drop53=0x54") || text.Contains("drop53=0x55") || text.Contains("drop53=0x56"))
        return "actor or interactive object";
    if (text.Contains("scenery") || text.Contains("prop") || text.Contains("drop53=0xff"))
        return "visual scenery/prop";
    return "unknown visual candidate";
}

string IdentityTestRecipe(PrecisionIdentityGroup group, string lane)
{
    PrecisionIdentitySample first = group.Samples.FirstOrDefault() ?? new PrecisionIdentitySample("", "", -1, 0, 0, 0);
    return IdentityTestRecipeForSample(lane, first);
}

string IdentityTestRecipeForSample(string lane, PrecisionIdentitySample first)
{
    string target = first.TrueIndex >= 0 ? $"{first.LevelName} T{first.TrueIndex}" : "one sample";
    return lane switch
    {
        "visual scenery/prop" => $"Move {target} and one nearby same-fingerprint sample to a clear flat spot; if the same model appears twice, promote the fingerprint to that prop name.",
        "actor or interactive object" => $"Move {target} to a safe test row; watch model, movement, attack/pickup/chest behavior, and reward drop before naming it.",
        "control/helper" => $"Do not name from solo movement alone. Move {target} only with its nearest visible cluster and compare camera, portal, rescue, or trigger behavior.",
        "flight/special object" => $"Test {target} in its flight/special level and observe whether it is a gate, plane/train piece, timer number, arch, or route marker.",
        _ => $"Move {target} to a visible test row and capture one screenshot plus before/after note."
    };
}

bool IsExactIdentity(Moby moby)
{
    string text = $"{moby.Label} {moby.CandidateKind} {moby.Confidence} {moby.Evidence}";
    string lower = text.ToLowerInvariant();
    if (text.Contains("?", StringComparison.Ordinal) ||
        lower.Contains("unknown") ||
        lower.Contains("placeholder") ||
        lower.Contains(" candidate") ||
        lower.Contains("helper/system") ||
        lower.Contains("helper or engine"))
        return false;

    return moby.Confidence.Contains("byte-pattern", StringComparison.OrdinalIgnoreCase) ||
        moby.Confidence.Contains("user", StringComparison.OrdinalIgnoreCase) ||
        moby.Confidence.Contains("live", StringComparison.OrdinalIgnoreCase) ||
        moby.Confidence.Contains("observed", StringComparison.OrdinalIgnoreCase) ||
        moby.Confidence.Contains("validated", StringComparison.OrdinalIgnoreCase);
}

bool IsQuestionableIdentity(Moby moby)
{
    if (IsExactIdentity(moby))
        return false;

    string text = $"{moby.Label} {moby.CandidateKind} {moby.Confidence} {moby.Evidence}".ToLowerInvariant();
    return text.Contains("?") ||
        text.Contains("unknown") ||
        text.Contains("placeholder") ||
        text.Contains("helper/system") ||
        text.Contains("helper or engine") ||
        text.Contains(" candidate") ||
        text.Contains("needs live validation") ||
        text.Contains("needs per-level confirmation") ||
        text.Contains("exact model") ||
        text.Contains("until live-tested") ||
        text.Contains("visible object not confirmed") ||
        text.Contains("actor, container, or interactive object");
}

string EscapeMarkdown(string value)
{
    return value
        .Replace("|", "\\|", StringComparison.Ordinal)
        .Replace("\r", " ", StringComparison.Ordinal)
        .Replace("\n", " ", StringComparison.Ordinal);
}

void ReportSyntheticChestContentLink(string levelKey, List<Moby> mobys)
{
    Moby? chest = mobys.FirstOrDefault(moby => moby.IsChest);
    if (chest == null)
        return;

    int trueIndex = mobys.Max(moby => moby.TrueIndex) + 1;
    Moby added = new()
    {
        Index = mobys.Max(moby => moby.Index) + 1,
        TrueIndex = trueIndex,
        LegacyIndex = MobyLoader.GetLegacyAliasIndex(trueIndex),
        Position = chest.Position,
        OriginalPosition = chest.Position,
        Type = 0,
        OriginalType = 0,
        State = 0,
        OriginalState = 0,
        SourceByte36 = 0,
        OriginalSourceByte36 = 0,
        SourceByte37 = 0,
        SourceByte4F = 0,
        OriginalSourceByte4F = 0,
        Flag4A = 0xFF,
        Flag4B = GemValue.Purple.IdByte,
        OriginalFlag4B = GemValue.Purple.IdByte,
        Color = GemValue.Purple.Color,
        Label = $"Locked chest content: {GemValue.Purple.DisplayName}",
        OriginalLabel = $"Locked chest content: {GemValue.Purple.DisplayName}",
        IsAdded = true
    };
    mobys.Add(added);
    int repaired = MobyRelationshipRepair.RepairChestContentLinks(levelKey, mobys);
    bool linked = chest.Links.Any(link =>
        string.Equals(link.Kind, "chest contents", StringComparison.OrdinalIgnoreCase) &&
        link.TrueIndexes.Contains(added.TrueIndex));
    added.IsRemoved = true;
    MobyRelationshipRepair.RepairChestContentLinks(levelKey, mobys);
    bool removedLinked = chest.Links.Any(link =>
        string.Equals(link.Kind, "chest contents", StringComparison.OrdinalIgnoreCase) &&
        link.TrueIndexes.Contains(added.TrueIndex));
    Console.WriteLine($"{levelKey} synthetic chest content: repaired {repaired} link(s), added T{added.TrueIndex} linked={linked}, removedLinked={removedLinked}");
}

async Task ReportLinkedCompanionCloneRoundTrip()
{
    Vector3f rootPosition = new(128, 256, 64);
    Vector3f helperPosition = new(160, 256, 64);
    Moby root = new()
    {
        Index = 1,
        TrueIndex = 1,
        LegacyIndex = 1,
        Position = rootPosition,
        OriginalPosition = rootPosition,
        Type = 0x20,
        OriginalType = 0x20,
        State = 0,
        OriginalState = 0,
        SourceByte36 = 0xFA,
        OriginalSourceByte36 = 0xFA,
        SourceByte37 = 0,
        OriginalSourceByte37 = 0,
        SourceByte4F = 0,
        OriginalSourceByte4F = 0,
        Flag4A = 0x10,
        OriginalFlag4A = 0x10,
        Flag4B = 0xFF,
        OriginalFlag4B = 0xFF,
        Color = Moby.ColorForType(0x20),
        Label = "Dragon",
        OriginalLabel = "Dragon"
    };
    Moby helper = new()
    {
        Index = 2,
        TrueIndex = 2,
        LegacyIndex = 2,
        Position = helperPosition,
        OriginalPosition = helperPosition,
        Type = 0x00,
        OriginalType = 0x00,
        State = 0,
        OriginalState = 0,
        SourceByte36 = 0x6E,
        OriginalSourceByte36 = 0x6E,
        SourceByte37 = 0,
        OriginalSourceByte37 = 0,
        SourceByte4F = 0,
        OriginalSourceByte4F = 0,
        Flag4A = 0x10,
        OriginalFlag4A = 0x10,
        Flag4B = 0xFF,
        OriginalFlag4B = 0xFF,
        Color = Moby.ColorForType(0x00),
        Label = "Dragon rescue control marker",
        OriginalLabel = "Dragon rescue control marker",
        CandidateKind = "dragon rescue control/helper"
    };
    MobyLink sourceLink = new()
    {
        Key = "smoke:dragon-scene:1:2",
        Name = "Dragon scene T1/T2",
        Kind = "dragon scene",
        LinkedMove = true,
        Confidence = "smoke",
        Reason = "Synthetic dragon helper companion link.",
        TrueIndexes = [1, 2]
    };
    root.Links.Add(sourceLink);
    helper.Links.Add(sourceLink);
    IReadOnlyList<Moby> companions = MobyCompanionClonePlanner.GetCompanionDonors(root, [root, helper]);
    if (companions.Count != 1 || companions[0].TrueIndex != helper.TrueIndex)
        throw new InvalidOperationException("Linked companion planner did not identify the synthetic helper donor.");

    Moby clonedRoot = CopyAsAddedMoby(root, 100, 100, "Copy of Dragon", 5);
    clonedRoot.PatchStatus = "native-clone";
    clonedRoot.PatchLead = "Smoke root clone with linked companion.";
    clonedRoot.SourceCloneLevelKey = "smoke";
    clonedRoot.SourceCloneLevelName = "Smoke";
    clonedRoot.SourceCloneTrueIndex = root.TrueIndex;
    Moby clonedHelper = CopyAsAddedMoby(helper, 101, 101, "Linked companion for Copy of Dragon: Dragon rescue control marker", 5);
    clonedHelper.PatchStatus = "native-clone";
    clonedHelper.PatchLead = "Linked companion cloned with Copy of Dragon from same-level donor T2; source root was T1.";
    clonedHelper.Confidence = "same-level-linked-companion-clone";
    clonedHelper.SourceCloneLevelKey = "smoke";
    clonedHelper.SourceCloneLevelName = "Smoke";
    clonedHelper.SourceCloneTrueIndex = helper.TrueIndex;
    MobyLink clonedLink = new()
    {
        Key = "native-editor:companion:1:100:0",
        Name = "Copied Dragon scene T1/T2",
        Kind = "dragon scene",
        LinkedMove = true,
        Confidence = "native-editor-companion",
        Reason = "Copied from source link smoke:dragon-scene:1:2.",
        TrueIndexes = [100, 101]
    };
    clonedRoot.Links.Add(clonedLink);
    clonedHelper.Links.Add(clonedLink);

    string path = Path.Combine(workspace.RootPath, "_local", "smoke", "linked-companion-clone-roundtrip-native-edits.json");
    await MobyEditStore.SaveAsync(path, [clonedRoot, clonedHelper], "Linked companion clone smoke");
    List<Moby> loaded = [root, helper];
    int applied = MobyEditStore.Load(path, loaded);
    Moby loadedRoot = loaded.First(moby => moby.TrueIndex == clonedRoot.TrueIndex);
    HashSet<int> moved = MobyLinkTraversal.GetLinkedMoveMobys(loadedRoot, loaded)
        .Select(moby => moby.TrueIndex)
        .ToHashSet();
    if (applied != 2 || !moved.SetEquals(new[] { clonedRoot.TrueIndex, clonedHelper.TrueIndex }))
        throw new InvalidOperationException($"Linked companion clone roundtrip failed: applied={applied}, moved={string.Join(",", moved.Order())}.");

    Console.WriteLine($"Linked companion clone roundtrip: saved/reloaded T{clonedRoot.TrueIndex}->T{clonedHelper.TrueIndex}");
}

async Task ReportArtisansPortalEntryCompanionCloneRoundTrip()
{
    string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", "artisans-mobys.json");
    if (!File.Exists(mobyPath))
        return;

    List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
    MobyMetadataEnricher.Apply(workspace, "artisans", sourceMobys);
    (int RootTrueIndex, int[] CompanionTrueIndexes, string ProofLabel)[] cases =
    [
        (144, [157], "Stone Hill portal name"),
        (145, [158], "east portal name"),
        (146, [159, 160], "multi-entry portal name"),
        (147, [155], "south portal name")
    ];

    string smokeRoot = Path.Combine(workspace.RootPath, "_local", "smoke", "portal-entry-companion-clone-roundtrip");
    Directory.CreateDirectory(smokeRoot);
    List<Moby> addedMobys = new();
    List<object> summaries = new();
    List<string> summaryRows = new();
    int nextIndex = sourceMobys.Max(moby => moby.Index) + 100;
    int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 100;

    foreach ((int rootTrueIndex, int[] companionTrueIndexes, string proofLabel) in cases)
    {
        Moby sourceRoot = sourceMobys.First(moby => moby.TrueIndex == rootTrueIndex);
        HashSet<int> expectedSourceCompanions = companionTrueIndexes.ToHashSet();
        IReadOnlyList<Moby> donorCompanions = MobyCompanionClonePlanner.GetCompanionDonors(sourceRoot, sourceMobys);
        HashSet<int> donorTrueIndexes = donorCompanions.Select(moby => moby.TrueIndex).ToHashSet();
        if (!expectedSourceCompanions.IsSubsetOf(donorTrueIndexes))
            throw new InvalidOperationException($"Artisans {proofLabel} T{rootTrueIndex} companion donors were {string.Join(",", donorTrueIndexes.Order())}, expected at least {string.Join(",", expectedSourceCompanions.Order())}.");

        int rootCloneIndex = nextIndex++;
        int rootCloneTrueIndex = nextTrueIndex++;
        Moby clonedRoot = CopyAsAddedMoby(sourceRoot, rootCloneIndex, rootCloneTrueIndex, $"Portal smoke copy of {sourceRoot.DisplayLabel}", rootCloneIndex - sourceRoot.Index);
        clonedRoot.PatchStatus = "native-clone";
        clonedRoot.PatchLead = $"Smoke app-style same-level portal entry clone with linked trigger/control companions from Artisans T{rootTrueIndex}.";
        clonedRoot.SourceCloneLevelKey = "artisans";
        clonedRoot.SourceCloneLevelName = "Artisans";
        clonedRoot.SourceCloneTrueIndex = sourceRoot.TrueIndex;
        addedMobys.Add(clonedRoot);

        int companionCount = MobyCompanionCloneBuilder.AddLinkedCompanionClones(
            sourceRoot,
            clonedRoot,
            sourceMobys,
            addedMobys,
            ref nextIndex,
            ref nextTrueIndex,
            "artisans",
            "Artisans");
        if (companionCount != donorTrueIndexes.Count)
            throw new InvalidOperationException($"Artisans {proofLabel} T{rootTrueIndex} cloned {companionCount} companion(s), expected {donorTrueIndexes.Count}.");

        List<Moby> clonedCompanions = addedMobys
            .Where(moby => donorTrueIndexes.Contains(moby.SourceCloneTrueIndex))
            .OrderBy(moby => moby.SourceCloneTrueIndex)
            .ToList();
        if (clonedCompanions.Count != donorTrueIndexes.Count)
            throw new InvalidOperationException($"Artisans {proofLabel} T{rootTrueIndex} did not create every expected companion clone.");

        foreach (Moby companionClone in clonedCompanions)
        {
            Moby donor = sourceMobys.First(moby => moby.TrueIndex == companionClone.SourceCloneTrueIndex);
            Vector3f expectedPosition = new(
                clonedRoot.Position.X + donor.Position.X - sourceRoot.Position.X,
                clonedRoot.Position.Y + donor.Position.Y - sourceRoot.Position.Y,
                clonedRoot.Position.Z + donor.Position.Z - sourceRoot.Position.Z);
            if (companionClone.Position != expectedPosition)
                throw new InvalidOperationException($"Artisans {proofLabel} companion T{donor.TrueIndex} clone position was {companionClone.Position}, expected {expectedPosition}.");
        }

        HashSet<int> expectedCloneMoveGroup = clonedCompanions
            .Select(moby => moby.TrueIndex)
            .Append(clonedRoot.TrueIndex)
            .ToHashSet();
        HashSet<int> clonedMoveGroup = MobyLinkTraversal.GetLinkedMoveMobys(clonedRoot, addedMobys)
            .Select(moby => moby.TrueIndex)
            .ToHashSet();
        if (!clonedMoveGroup.SetEquals(expectedCloneMoveGroup))
            throw new InvalidOperationException($"Artisans {proofLabel} T{rootTrueIndex} cloned move group was {string.Join(",", clonedMoveGroup.Order())}, expected {string.Join(",", expectedCloneMoveGroup.Order())}.");

        summaries.Add(new
        {
            proofLabel,
            sourceRoot = new { sourceRoot.TrueIndex, sourceRoot.DisplayLabel, VisualKind = sourceRoot.VisualKind.ToString() },
            sourceCompanions = donorCompanions.Select(moby => new { moby.TrueIndex, moby.DisplayLabel, VisualKind = moby.VisualKind.ToString() }).ToList(),
            clonedRoot = new { clonedRoot.TrueIndex, clonedRoot.DisplayLabel, clonedRoot.SourceCloneTrueIndex },
            clonedCompanions = clonedCompanions.Select(moby => new { moby.TrueIndex, moby.DisplayLabel, moby.SourceCloneTrueIndex, VisualKind = moby.VisualKind.ToString() }).ToList(),
            clonedMoveGroup = clonedMoveGroup.Order().ToList()
        });
        summaryRows.Add($"| {EscapeMarkdown(proofLabel)} | T{sourceRoot.TrueIndex} {EscapeMarkdown(sourceRoot.DisplayLabel)} | {EscapeMarkdown(string.Join(", ", donorCompanions.Select(moby => $"T{moby.TrueIndex} {moby.DisplayLabel}")))} | T{clonedRoot.TrueIndex} | {EscapeMarkdown(string.Join(", ", clonedCompanions.Select(moby => $"T{moby.TrueIndex} from T{moby.SourceCloneTrueIndex}")))} | {EscapeMarkdown(string.Join(", ", clonedMoveGroup.Order().Select(trueIndex => $"T{trueIndex}")))} |");
    }

    string editPath = Path.Combine(smokeRoot, "artisans-portal-entry-companion-clone-native-edits.json");
    await MobyEditStore.SaveAsync(editPath, addedMobys, "Artisans portal entry companion clone smoke");

    List<Moby> loadedMobys = MobyLoader.LoadCached(mobyPath).ToList();
    MobyMetadataEnricher.Apply(workspace, "artisans", loadedMobys);
    int applied = MobyEditStore.Load(editPath, loadedMobys);
    if (applied != addedMobys.Count)
        throw new InvalidOperationException($"Artisans portal entry companion clone roundtrip reloaded {applied} edit(s), expected {addedMobys.Count}.");

    foreach (Moby clonedRoot in addedMobys.Where(moby => cases.Any(testCase => testCase.RootTrueIndex == moby.SourceCloneTrueIndex)))
    {
        HashSet<int> expectedLoadedGroup = MobyLinkTraversal.GetLinkedMoveMobys(clonedRoot, addedMobys)
            .Select(moby => moby.TrueIndex)
            .ToHashSet();
        Moby loadedRoot = loadedMobys.First(moby => moby.TrueIndex == clonedRoot.TrueIndex);
        HashSet<int> loadedMoveGroup = MobyLinkTraversal.GetLinkedMoveMobys(loadedRoot, loadedMobys)
            .Select(moby => moby.TrueIndex)
            .ToHashSet();
        if (!loadedMoveGroup.SetEquals(expectedLoadedGroup))
            throw new InvalidOperationException($"Artisans portal entry companion clone roundtrip reloaded T{clonedRoot.TrueIndex} move group as {string.Join(",", loadedMoveGroup.Order())}, expected {string.Join(",", expectedLoadedGroup.Order())}.");
    }

    string markdownPath = Path.Combine(smokeRoot, "artisans-portal-entry-companion-clone-roundtrip.md");
    string jsonPath = Path.Combine(smokeRoot, "artisans-portal-entry-companion-clone-roundtrip.json");
    File.WriteAllText(markdownPath, string.Join(Environment.NewLine, [
        "# Artisans Portal Entry Companion Clone Roundtrip",
        "",
        "Smoke proof that real Artisans portal-name objects clone their linked portal-entry trigger/control rows through the same helper used by the editor add/copy/paste path, then survive native edit save/reload as linked move groups.",
        "",
        $"- Source cache: `{mobyPath}`",
        $"- Saved edit manifest: `{editPath}`",
        $"- Reloaded edits applied: {applied}",
        $"- Tested portal rows: {string.Join(", ", cases.Select(testCase => $"T{testCase.RootTrueIndex}->" + string.Join("/", testCase.CompanionTrueIndexes.Select(trueIndex => $"T{trueIndex}"))))}",
        "",
        "## Clone Groups",
        "",
        "| Proof | Source donor | Source companions | Cloned root | Cloned companions | Reloaded move group |",
        "|---|---|---|---|---|---|",
        .. summaryRows
    ]));
    File.WriteAllText(jsonPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now,
        sourceCache = mobyPath,
        editManifest = editPath,
        applied,
        addedCount = addedMobys.Count,
        cases = summaries
    }, new JsonSerializerOptions { WriteIndented = true }));

    Console.WriteLine($"Artisans portal entry companion clone roundtrip: {cases.Length} portal donor(s), {addedMobys.Count} saved edit(s), report={markdownPath}");
}

async Task ReportReturnHomeCompanionCloneRoundTrip()
{
    string smokeRoot = Path.Combine(workspace.RootPath, "_local", "smoke", "return-home-companion-clone-roundtrip");
    string tempWorkspaceRoot = Path.Combine(smokeRoot, "workspace");
    if (Directory.Exists(tempWorkspaceRoot))
        Directory.Delete(tempWorkspaceRoot, recursive: true);

    string promotedRoot = Path.Combine(tempWorkspaceRoot, "_local", "control-role-proof-review", "promoted-behavior-links");
    Directory.CreateDirectory(promotedRoot);

    List<ControlRoleProofPromotion> promotions = new();
    foreach ((string levelKey, int helperTrueIndex) in KnownReturnHomeHelperProofPairs())
    {
        LevelDefinition? level = catalog.FindByKey(levelKey);
        string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{levelKey}-mobys.json");
        if (level == null || !File.Exists(mobyPath))
            continue;

        List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
        MobyMetadataEnricher.Apply(workspace, levelKey, sourceMobys);
        Moby helper = sourceMobys.First(moby => moby.TrueIndex == helperTrueIndex);
        Moby returnHome = FindNearestMoby(helper, sourceMobys.Where(IsReturnHomeVisibleMoby), 128)
            ?? throw new InvalidOperationException($"{level.DisplayName} Return Home helper T{helperTrueIndex} did not find a visible Return Home object within 128u.");

        promotions.Add(new ControlRoleProofPromotion(
            levelKey,
            level.DisplayName,
            helperTrueIndex,
            $"Smoke live proof: {level.DisplayName} Return Home helper pair",
            [helperTrueIndex, returnHome.TrueIndex],
            "confirmed-linked",
            "marker-only return-home helper moved without the visible Return Home object",
            $"paired Return Home behavior followed visible T{returnHome.TrueIndex} with helper T{helperTrueIndex}",
            "Smoke proof uses the mapped Return Home helper pair so confirmed results must become cloneable helper data.",
            ""));
    }

    WritePromotedControlRoleBehaviorLinks(promotedRoot, promotions);

    EditorWorkspace tempWorkspace = new(tempWorkspaceRoot);
    Directory.CreateDirectory(smokeRoot);
    List<object> summaries = new();
    List<string> summaryRows = new();

    foreach (ControlRoleProofPromotion promotion in promotions.OrderBy(promotion => promotion.LevelName, StringComparer.OrdinalIgnoreCase))
    {
        string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{promotion.LevelKey}-mobys.json");
        List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
        MobyMetadataResult metadata = MobyMetadataEnricher.Apply(tempWorkspace, promotion.LevelKey, sourceMobys);
        if (metadata.BehaviorLinkGroups != 1)
            throw new InvalidOperationException($"{promotion.LevelName} Return Home companion clone roundtrip loaded {metadata.BehaviorLinkGroups} behavior link group(s), expected 1.");

        int helperTrueIndex = promotion.TrueIndex;
        int returnHomeTrueIndex = promotion.TrueIndexes.First(index => index != helperTrueIndex);
        Moby helper = sourceMobys.First(moby => moby.TrueIndex == helperTrueIndex);
        Moby returnHome = sourceMobys.First(moby => moby.TrueIndex == returnHomeTrueIndex);
        MobyLink link = returnHome.Links.FirstOrDefault(link =>
            MobyCompanionClonePlanner.IsCompanionCloneLink(link) &&
            link.TrueIndexes.Contains(helper.TrueIndex) &&
            link.TrueIndexes.Contains(returnHome.TrueIndex))
            ?? throw new InvalidOperationException($"{promotion.LevelName} Return Home T{returnHome.TrueIndex} did not load a cloneable helper link to T{helper.TrueIndex}.");
        IReadOnlyList<Moby> companions = MobyCompanionClonePlanner.GetCompanionDonors(returnHome, sourceMobys);
        if (companions.Count != 1 || companions[0].TrueIndex != helper.TrueIndex)
            throw new InvalidOperationException($"{promotion.LevelName} Return Home T{returnHome.TrueIndex} companion donors were {string.Join(",", companions.Select(moby => moby.TrueIndex))}, expected T{helper.TrueIndex}.");

        int nextIndex = sourceMobys.Max(moby => moby.Index) + 100;
        int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 100;
        Moby clonedReturnHome = CopyAsAddedMoby(returnHome, nextIndex++, nextTrueIndex++, $"Smoke copy of {promotion.LevelName} Return Home", 8);
        clonedReturnHome.PatchStatus = "native-clone";
        clonedReturnHome.PatchLead = "Smoke app-style same-level Return Home clone with proof-linked helper companion.";
        clonedReturnHome.SourceCloneLevelKey = promotion.LevelKey;
        clonedReturnHome.SourceCloneLevelName = promotion.LevelName;
        clonedReturnHome.SourceCloneTrueIndex = returnHome.TrueIndex;
        List<Moby> addedMobys = [clonedReturnHome];

        int companionCount = MobyCompanionCloneBuilder.AddLinkedCompanionClones(
            returnHome,
            clonedReturnHome,
            sourceMobys,
            addedMobys,
            ref nextIndex,
            ref nextTrueIndex,
            promotion.LevelKey,
            promotion.LevelName);
        if (companionCount != 1)
            throw new InvalidOperationException($"{promotion.LevelName} Return Home T{returnHome.TrueIndex} cloned {companionCount} companion(s), expected 1.");

        Moby clonedHelper = addedMobys.FirstOrDefault(moby => moby.SourceCloneTrueIndex == helper.TrueIndex)
            ?? throw new InvalidOperationException($"{promotion.LevelName} return-home companion clone roundtrip did not create a cloned T{helper.TrueIndex} helper.");
        Vector3f expectedHelperPosition = new(
            clonedReturnHome.Position.X + helper.Position.X - returnHome.Position.X,
            clonedReturnHome.Position.Y + helper.Position.Y - returnHome.Position.Y,
            clonedReturnHome.Position.Z + helper.Position.Z - returnHome.Position.Z);
        if (clonedHelper.Position != expectedHelperPosition)
            throw new InvalidOperationException($"{promotion.LevelName} cloned Return Home helper position was {clonedHelper.Position}, expected {expectedHelperPosition}.");

        HashSet<int> clonedMoveGroup = MobyLinkTraversal.GetLinkedMoveMobys(clonedReturnHome, addedMobys)
            .Select(moby => moby.TrueIndex)
            .ToHashSet();
        if (!clonedMoveGroup.SetEquals(new[] { clonedReturnHome.TrueIndex, clonedHelper.TrueIndex }))
            throw new InvalidOperationException($"{promotion.LevelName} cloned Return Home move group was {string.Join(",", clonedMoveGroup.Order())}, expected T{clonedReturnHome.TrueIndex}/T{clonedHelper.TrueIndex}.");

        string editPath = Path.Combine(smokeRoot, $"{promotion.LevelKey}-return-home-companion-clone-native-edits.json");
        await MobyEditStore.SaveAsync(editPath, addedMobys, $"{promotion.LevelName} Return Home companion clone smoke");

        List<Moby> loadedMobys = MobyLoader.LoadCached(mobyPath).ToList();
        MobyMetadataEnricher.Apply(tempWorkspace, promotion.LevelKey, loadedMobys);
        int applied = MobyEditStore.Load(editPath, loadedMobys);
        Moby loadedRoot = loadedMobys.First(moby => moby.TrueIndex == clonedReturnHome.TrueIndex);
        HashSet<int> loadedMoveGroup = MobyLinkTraversal.GetLinkedMoveMobys(loadedRoot, loadedMobys)
            .Select(moby => moby.TrueIndex)
            .ToHashSet();
        if (applied != addedMobys.Count || !loadedMoveGroup.SetEquals(new[] { clonedReturnHome.TrueIndex, clonedHelper.TrueIndex }))
            throw new InvalidOperationException($"{promotion.LevelName} return-home companion clone roundtrip failed reload: applied={applied}, moved={string.Join(",", loadedMoveGroup.Order())}.");

        summaries.Add(new
        {
            promotion.LevelKey,
            promotion.LevelName,
            source = new
            {
                visible = new { returnHome.TrueIndex, returnHome.DisplayLabel, VisualKind = returnHome.VisualKind.ToString() },
                helper = new { helper.TrueIndex, helper.DisplayLabel, VisualKind = helper.VisualKind.ToString() }
            },
            generatedLinkFile = Path.Combine(promotedRoot, $"{promotion.LevelKey}-behavior-links.json"),
            editManifest = editPath,
            applied,
            link = new { link.Key, link.Name, link.Kind, link.LinkedMove, link.Confidence, link.Reason, link.TrueIndexes },
            clones = addedMobys.Select(moby => new
            {
                moby.TrueIndex,
                moby.DisplayLabel,
                moby.SourceCloneTrueIndex,
                VisualKind = moby.VisualKind.ToString()
            }).ToList(),
            loadedMoveGroup = loadedMoveGroup.Order().ToList()
        });
        summaryRows.Add($"| {EscapeMarkdown(promotion.LevelName)} | T{returnHome.TrueIndex} {EscapeMarkdown(returnHome.DisplayLabel)} | T{helper.TrueIndex} {EscapeMarkdown(helper.DisplayLabel)} | T{clonedReturnHome.TrueIndex} | T{clonedHelper.TrueIndex} from T{helper.TrueIndex} | {EscapeMarkdown(string.Join(", ", loadedMoveGroup.Order().Select(trueIndex => $"T{trueIndex}")))} |");
    }

    if (summaries.Count == 0)
    {
        Console.WriteLine("Return Home companion clone roundtrip: no cached Return Home proof pairs found; skipping.");
        return;
    }

    string markdownPath = Path.Combine(smokeRoot, "all-return-home-companion-clone-roundtrip.md");
    string jsonPath = Path.Combine(smokeRoot, "all-return-home-companion-clone-roundtrip.json");
    File.WriteAllText(markdownPath, string.Join(Environment.NewLine, [
        "# Return Home Companion Clone Roundtrip",
        "",
        "Smoke proof that confirmed Return Home helper pairs become editor clone data: copying the visible Return Home object also copies its hidden helper/control row, then the linked move group survives native edit save/reload.",
        "",
        $"- Generated behavior link folder: `{promotedRoot}`",
        $"- Tested helper pairs: {summaries.Count}",
        "",
        "## Clone Groups",
        "",
        "| Level | Source visible object | Source helper/control | Cloned visible object | Cloned helper/control | Reloaded move group |",
        "|---|---|---|---|---|---|",
        .. summaryRows
    ]));
    File.WriteAllText(jsonPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now,
        generatedBehaviorLinkFolder = promotedRoot,
        testedPairs = summaries.Count,
        rows = summaries
    }, new JsonSerializerOptions { WriteIndented = true }));

    Console.WriteLine($"Return Home companion clone roundtrip: {summaries.Count} helper pair(s), report={markdownPath}");
}

async Task ReportPortalTripletCompanionCloneRoundTrip()
{
    string smokeRoot = Path.Combine(workspace.RootPath, "_local", "smoke", "portal-triplet-companion-clone-roundtrip");
    string workspacesRoot = Path.Combine(smokeRoot, "workspaces");
    if (Directory.Exists(workspacesRoot))
        Directory.Delete(workspacesRoot, recursive: true);

    Directory.CreateDirectory(smokeRoot);
    Directory.CreateDirectory(workspacesRoot);
    List<object> summaries = new();
    List<string> summaryRows = new();
    List<string> missing = new();

    foreach ((string levelKey, int targetTrueIndex) in KnownPortalTripletProofRows())
    {
        LevelDefinition? level = catalog.FindByKey(levelKey);
        string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{levelKey}-mobys.json");
        if (level == null || !File.Exists(mobyPath))
        {
            missing.Add($"{levelKey} T{targetTrueIndex}");
            continue;
        }

        List<Moby> probeMobys = MobyLoader.LoadCached(mobyPath).ToList();
        MobyMetadataEnricher.Apply(workspace, levelKey, probeMobys);
        Moby target = probeMobys.First(moby => moby.TrueIndex == targetTrueIndex);
        List<Moby> anchors = SelectPortalTripletCloneAnchors(levelKey, target, probeMobys);
        if (anchors.Count == 0)
            throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} did not find any proof anchors.");

        List<int> linkedTrueIndexes = new[] { target.TrueIndex }
            .Concat(anchors.Select(anchor => anchor.TrueIndex))
            .Distinct()
            .OrderBy(index => index)
            .ToList();
        Moby rootProbe = SelectPortalTripletCloneRoot(target, anchors);
        if (!linkedTrueIndexes.Contains(rootProbe.TrueIndex))
            linkedTrueIndexes.Add(rootProbe.TrueIndex);

        string testWorkspaceRoot = Path.Combine(workspacesRoot, $"{levelKey}-t{targetTrueIndex}");
        string promotedRoot = Path.Combine(testWorkspaceRoot, "_local", "control-role-proof-review", "promoted-behavior-links");
        Directory.CreateDirectory(promotedRoot);
        WritePromotedControlRoleBehaviorLinks(promotedRoot, [
            new ControlRoleProofPromotion(
                levelKey,
                level.DisplayName,
                targetTrueIndex,
                $"Smoke live proof: {level.DisplayName} portal control triplet T{targetTrueIndex}",
                linkedTrueIndexes,
                "confirmed-linked",
                "marker-only portal control moved without the linked cluster behavior",
                "paired portal control behavior followed the linked cluster",
                "Smoke proof uses the mapped portal pad/destination/route cluster so confirmed results must become cloneable companion data.",
                "")
        ]);

        EditorWorkspace tempWorkspace = new(testWorkspaceRoot);
        List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
        MobyMetadataResult metadata = MobyMetadataEnricher.Apply(tempWorkspace, levelKey, sourceMobys);
        if (metadata.BehaviorLinkGroups != 1)
            throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} loaded {metadata.BehaviorLinkGroups} behavior link group(s), expected 1.");

        Moby root = sourceMobys.First(moby => moby.TrueIndex == rootProbe.TrueIndex);
        MobyLink link = root.Links.FirstOrDefault(link =>
            MobyCompanionClonePlanner.IsCompanionCloneLink(link) &&
            linkedTrueIndexes.All(link.TrueIndexes.Contains))
            ?? throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} did not attach a cloneable link to root T{root.TrueIndex}.");
        List<Moby> expectedCompanions = link.TrueIndexes
            .Where(trueIndex => trueIndex != root.TrueIndex)
            .Select(trueIndex => sourceMobys.FirstOrDefault(moby => moby.TrueIndex == trueIndex))
            .Where(moby => moby != null)
            .Select(moby => moby!)
            .Where(moby => MobyCompanionClonePlanner.IsCloneableCompanion(root, moby, link))
            .OrderBy(moby => moby.TrueIndex)
            .ToList();
        if (expectedCompanions.Count == 0)
            throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} had no cloneable companions for root T{root.TrueIndex}.");

        IReadOnlyList<Moby> companions = MobyCompanionClonePlanner.GetCompanionDonors(root, sourceMobys);
        HashSet<int> expectedCompanionIndexes = expectedCompanions.Select(moby => moby.TrueIndex).ToHashSet();
        HashSet<int> actualCompanionIndexes = companions.Select(moby => moby.TrueIndex).ToHashSet();
        if (!actualCompanionIndexes.SetEquals(expectedCompanionIndexes))
            throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} companion donors were {string.Join(",", actualCompanionIndexes.Order())}, expected {string.Join(",", expectedCompanionIndexes.Order())}.");

        int nextIndex = sourceMobys.Max(moby => moby.Index) + 100;
        int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 100;
        Moby clonedRoot = CopyAsAddedMoby(root, nextIndex++, nextTrueIndex++, $"Smoke copy of {level.DisplayName} portal triplet root", 8);
        clonedRoot.PatchStatus = "native-clone";
        clonedRoot.PatchLead = "Smoke app-style same-level portal triplet clone with proof-linked control companions.";
        clonedRoot.SourceCloneLevelKey = levelKey;
        clonedRoot.SourceCloneLevelName = level.DisplayName;
        clonedRoot.SourceCloneTrueIndex = root.TrueIndex;
        List<Moby> addedMobys = [clonedRoot];

        int companionCount = MobyCompanionCloneBuilder.AddLinkedCompanionClones(
            root,
            clonedRoot,
            sourceMobys,
            addedMobys,
            ref nextIndex,
            ref nextTrueIndex,
            levelKey,
            level.DisplayName);
        if (companionCount != expectedCompanions.Count)
            throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} cloned {companionCount} companion(s), expected {expectedCompanions.Count}.");

        foreach (Moby companion in expectedCompanions)
        {
            Moby clonedCompanion = addedMobys.FirstOrDefault(moby => moby.SourceCloneTrueIndex == companion.TrueIndex)
                ?? throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} did not clone companion T{companion.TrueIndex}.");
            Vector3f expectedPosition = new(
                clonedRoot.Position.X + companion.Position.X - root.Position.X,
                clonedRoot.Position.Y + companion.Position.Y - root.Position.Y,
                clonedRoot.Position.Z + companion.Position.Z - root.Position.Z);
            if (clonedCompanion.Position != expectedPosition)
                throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} cloned T{companion.TrueIndex} at {clonedCompanion.Position}, expected {expectedPosition}.");
        }

        HashSet<int> expectedMoveGroup = addedMobys
            .Select(moby => moby.TrueIndex)
            .ToHashSet();
        HashSet<int> clonedMoveGroup = MobyLinkTraversal.GetLinkedMoveMobys(clonedRoot, addedMobys)
            .Select(moby => moby.TrueIndex)
            .ToHashSet();
        if (!clonedMoveGroup.SetEquals(expectedMoveGroup))
            throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} cloned move group was {string.Join(",", clonedMoveGroup.Order())}, expected {string.Join(",", expectedMoveGroup.Order())}.");

        string editPath = Path.Combine(smokeRoot, $"{levelKey}-t{targetTrueIndex}-portal-triplet-companion-clone-native-edits.json");
        await MobyEditStore.SaveAsync(editPath, addedMobys, $"{level.DisplayName} portal triplet T{targetTrueIndex} companion clone smoke");

        List<Moby> loadedMobys = MobyLoader.LoadCached(mobyPath).ToList();
        MobyMetadataEnricher.Apply(tempWorkspace, levelKey, loadedMobys);
        int applied = MobyEditStore.Load(editPath, loadedMobys);
        Moby loadedRoot = loadedMobys.First(moby => moby.TrueIndex == clonedRoot.TrueIndex);
        HashSet<int> loadedMoveGroup = MobyLinkTraversal.GetLinkedMoveMobys(loadedRoot, loadedMobys)
            .Select(moby => moby.TrueIndex)
            .ToHashSet();
        if (applied != addedMobys.Count || !loadedMoveGroup.SetEquals(expectedMoveGroup))
            throw new InvalidOperationException($"{level.DisplayName} portal triplet T{targetTrueIndex} failed reload: applied={applied}, moved={string.Join(",", loadedMoveGroup.Order())}.");

        summaries.Add(new
        {
            levelKey,
            levelName = level.DisplayName,
            target = new { target.TrueIndex, target.DisplayLabel, VisualKind = target.VisualKind.ToString() },
            root = new { root.TrueIndex, root.DisplayLabel, VisualKind = root.VisualKind.ToString() },
            linkedTrueIndexes,
            cloneableCompanions = expectedCompanions.Select(moby => new { moby.TrueIndex, moby.DisplayLabel, VisualKind = moby.VisualKind.ToString() }).ToList(),
            generatedLinkFile = Path.Combine(promotedRoot, $"{levelKey}-behavior-links.json"),
            editManifest = editPath,
            applied,
            clones = addedMobys.Select(moby => new
            {
                moby.TrueIndex,
                moby.DisplayLabel,
                moby.SourceCloneTrueIndex,
                VisualKind = moby.VisualKind.ToString()
            }).ToList(),
            loadedMoveGroup = loadedMoveGroup.Order().ToList()
        });
        summaryRows.Add($"| {EscapeMarkdown(level.DisplayName)} | T{target.TrueIndex} {EscapeMarkdown(target.DisplayLabel)} | T{root.TrueIndex} {EscapeMarkdown(root.DisplayLabel)} | {EscapeMarkdown(string.Join(", ", expectedCompanions.Select(moby => $"T{moby.TrueIndex} {moby.DisplayLabel}")))} | T{clonedRoot.TrueIndex} | {EscapeMarkdown(string.Join(", ", addedMobys.Where(moby => moby.TrueIndex != clonedRoot.TrueIndex).Select(moby => $"T{moby.TrueIndex} from T{moby.SourceCloneTrueIndex}")))} | {EscapeMarkdown(string.Join(", ", loadedMoveGroup.Order().Select(trueIndex => $"T{trueIndex}")))} |");
    }

    if (missing.Count > 0)
        throw new InvalidOperationException($"Portal triplet companion clone roundtrip missed source cache for: {string.Join(", ", missing)}.");
    if (summaries.Count != KnownPortalTripletProofRows().Length)
        throw new InvalidOperationException($"Portal triplet companion clone roundtrip tested {summaries.Count} pair(s), expected {KnownPortalTripletProofRows().Length}.");

    string markdownPath = Path.Combine(smokeRoot, "all-portal-triplet-companion-clone-roundtrip.md");
    string jsonPath = Path.Combine(smokeRoot, "all-portal-triplet-companion-clone-roundtrip.json");
    File.WriteAllText(markdownPath, string.Join(Environment.NewLine, [
        "# Portal Triplet Companion Clone Roundtrip",
        "",
        "Smoke proof that confirmed portal pad/destination/route clusters become editor clone data: copying the chosen root object also copies its hidden portal control companions, then the linked move group survives native edit save/reload.",
        "",
        $"- Tested portal triplets: {summaries.Count}",
        $"- Temporary workspaces: `{workspacesRoot}`",
        "",
        "## Clone Groups",
        "",
        "| Level | Proof target | Clone root | Source companions | Cloned root | Cloned companions | Reloaded move group |",
        "|---|---|---|---|---|---|---|",
        .. summaryRows
    ]));
    File.WriteAllText(jsonPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now,
        testedTriplets = summaries.Count,
        temporaryWorkspaces = workspacesRoot,
        rows = summaries
    }, new JsonSerializerOptions { WriteIndented = true }));

    Console.WriteLine($"Portal triplet companion clone roundtrip: {summaries.Count} triplet(s), report={markdownPath}");
}

void ReportPortalControlEditLinks()
{
    List<(LevelDefinition Level, Moby Moby)> allMobys = LoadAllCachedMobysWithMetadata();
    List<PortalControlEditLinkSmokeRow> rows = allMobys
        .GroupBy(item => item.Level.Key, StringComparer.OrdinalIgnoreCase)
        .SelectMany(levelGroup =>
        {
            LevelDefinition level = levelGroup.First().Level;
            Dictionary<int, Moby> mobysByTrueIndex = levelGroup
                .Select(item => item.Moby)
                .Where(moby => !moby.IsRemoved && moby.TrueIndex >= 0)
                .GroupBy(moby => moby.TrueIndex)
                .ToDictionary(group => group.Key, group => group.First());
            return levelGroup
                .SelectMany(item => item.Moby.Links)
                .Where(IsPortalControlEditLink)
                .GroupBy(link => link.Key, StringComparer.OrdinalIgnoreCase)
                .Select(group => BuildPortalControlEditLinkSmokeRow(level, group.First(), mobysByTrueIndex));
        })
        .OrderBy(row => row.LevelName, StringComparer.OrdinalIgnoreCase)
        .ThenBy(row => row.EntryTriggerTrueIndex)
        .ToList();

    int expectedHomeworldPortalSets = HomeworldPortalControlCatalog.All.Count;
    if (rows.Count != expectedHomeworldPortalSets)
        throw new InvalidOperationException($"Portal edit links expected {expectedHomeworldPortalSets} homeworld portal set(s), got {rows.Count}.");

    PortalControlEditLinkSmokeRow? artisansStoneHill = rows.FirstOrDefault(row =>
        row.LevelKey.Equals("artisans", StringComparison.OrdinalIgnoreCase) &&
        row.EntryTriggerTrueIndex == 38);
    if (artisansStoneHill == null ||
        artisansStoneHill.LetteringTrueIndex != 144 ||
        artisansStoneHill.LocationTrueIndex != 157)
    {
        throw new InvalidOperationException("Artisans Stone Hill portal edit link should connect entry trigger T38, lettering T144, and location T157.");
    }

    List<PortalControlEditLinkSmokeRow> cloneApprovedRows = rows
        .Where(row => row.CloneApproved)
        .ToList();
    if (cloneApprovedRows.Count > 0)
    {
        string summary = string.Join("; ", cloneApprovedRows.Select(row => $"{row.LevelName} T{row.EntryTriggerTrueIndex}"));
        throw new InvalidOperationException($"Portal edit-only links must not be clone-approved yet: {summary}");
    }

    Console.WriteLine($"Portal control edit links: {rows.Count} homeworld portal set(s), Artisans T38/T144/T157 linked, clone-approved=0");
}

bool IsPortalControlEditLink(MobyLink link)
{
    return string.Equals(link.Kind, "portal controls", StringComparison.OrdinalIgnoreCase) &&
        link.LinkedMove &&
        MobyLinkTraversal.IsVisibleLink(link);
}

PortalControlEditLinkSmokeRow BuildPortalControlEditLinkSmokeRow(
    LevelDefinition level,
    MobyLink link,
    IReadOnlyDictionary<int, Moby> mobysByTrueIndex)
{
    List<Moby> members = link.TrueIndexes
        .Where(mobysByTrueIndex.ContainsKey)
        .Select(trueIndex => mobysByTrueIndex[trueIndex])
        .DistinctBy(moby => moby.TrueIndex)
        .OrderBy(moby => moby.TrueIndex)
        .ToList();
    Moby entryTrigger = members.FirstOrDefault(IsPortalEntryTriggerMoby)
        ?? throw new InvalidOperationException($"{level.DisplayName} portal edit link {link.Key} is missing a pad/entry trigger.");
    Moby? lettering = members.FirstOrDefault(IsPortalLetteringMoby);
    Moby? location = members.FirstOrDefault(IsPortalLocationMoby);
    if (members.Any(moby => !moby.IsHomeworldPortalControl || !moby.SupportsTerrainSnap))
        throw new InvalidOperationException($"{level.DisplayName} portal edit link {link.Key} contains a control that cannot snap to terrain Z.");

    return new PortalControlEditLinkSmokeRow(
        level.Key,
        level.DisplayName,
        link.Key,
        entryTrigger.TrueIndex,
        lettering?.TrueIndex ?? -1,
        location?.TrueIndex ?? -1,
        members.Select(moby => moby.TrueIndex).ToList(),
        MobyCompanionClonePlanner.IsCompanionCloneLink(link));
}

bool IsPortalLetteringMoby(Moby moby)
{
    return moby.Type == 0x00 &&
        moby.SourceByte36 == 0x01 &&
        moby.Flag4A == 0x10 &&
        moby.Flag4B == 0xFF;
}

bool IsPortalLocationMoby(Moby moby)
{
    return moby.Type == 0x00 &&
        moby.SourceByte36 == 0x1E &&
        moby.Flag4A == 0x10 &&
        moby.Flag4B == 0xFF;
}

bool IsPortalEntryTriggerMoby(Moby moby)
{
    return moby.Type == 0x00 &&
        moby.SourceByte36 == 0x8E &&
        moby.Flag4A == 0x10 &&
        moby.Flag4B == 0xFF;
}

void ReportCheckedInControlRoleCompanionLinks()
{
    string smokeRoot = Path.Combine(workspace.RootPath, "_local", "smoke", "checked-in-control-role-companion-links");
    Directory.CreateDirectory(smokeRoot);

    List<object> rows = new();
    List<string> summaryRows = new();

    foreach ((string levelKey, int helperTrueIndex) in KnownReturnHomeHelperProofPairs())
    {
        LevelDefinition level = catalog.FindByKey(levelKey)
            ?? throw new InvalidOperationException($"Known Return Home proof level is missing from catalog: {levelKey}.");
        string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{levelKey}-mobys.json");
        if (!File.Exists(mobyPath))
            throw new FileNotFoundException($"Checked-in companion link smoke needs {level.DisplayName} moby cache.", mobyPath);

        string linkKey = $"{levelKey}:control-role-proof:t{helperTrueIndex}";
        IReadOnlyList<int> checkedInIndexes = ReadCheckedInBehaviorLinkIndexes(levelKey, linkKey);
        if (!checkedInIndexes.Contains(helperTrueIndex))
            throw new InvalidOperationException($"{level.DisplayName} checked-in behavior link {linkKey} does not include helper T{helperTrueIndex}.");

        List<Moby> mobys = MobyLoader.LoadCached(mobyPath).ToList();
        MobyMetadataEnricher.Apply(workspace, levelKey, mobys);
        Moby helper = mobys.First(moby => moby.TrueIndex == helperTrueIndex);
        List<Moby> checkedInMembers = checkedInIndexes
            .Select(index => mobys.FirstOrDefault(moby => moby.TrueIndex == index))
            .Where(moby => moby != null)
            .Select(moby => moby!)
            .ToList();
        Moby returnHome = checkedInMembers
            .FirstOrDefault(moby => moby.TrueIndex != helperTrueIndex && IsReturnHomeVisibleMoby(moby))
            ?? checkedInMembers.FirstOrDefault(moby => moby.TrueIndex != helperTrueIndex)
            ?? throw new InvalidOperationException($"{level.DisplayName} checked-in Return Home link {linkKey} does not include a visible Return Home object.");

        MobyLink link = returnHome.Links.FirstOrDefault(link =>
            string.Equals(link.Key, linkKey, StringComparison.OrdinalIgnoreCase) &&
            MobyCompanionClonePlanner.IsCompanionCloneLink(link))
            ?? throw new InvalidOperationException($"{level.DisplayName} Return Home T{returnHome.TrueIndex} did not load cloneable checked-in link {linkKey}.");
        IReadOnlyList<Moby> companions = MobyCompanionClonePlanner.GetCompanionDonors(returnHome, mobys);
        if (!companions.Any(companion => companion.TrueIndex == helper.TrueIndex))
            throw new InvalidOperationException($"{level.DisplayName} Return Home T{returnHome.TrueIndex} checked-in companion donors missed helper T{helper.TrueIndex}.");

        rows.Add(new
        {
            kind = "return-home",
            levelKey,
            levelName = level.DisplayName,
            linkKey,
            checkedInIndexes,
            root = new { returnHome.TrueIndex, returnHome.DisplayLabel, VisualKind = returnHome.VisualKind.ToString() },
            expectedCompanions = new[] { helper.TrueIndex },
            plannerCompanions = companions.Select(moby => moby.TrueIndex).Order().ToList()
        });
        summaryRows.Add($"| Return Home | {EscapeMarkdown(level.DisplayName)} | `{EscapeMarkdown(linkKey)}` | T{returnHome.TrueIndex} {EscapeMarkdown(returnHome.DisplayLabel)} | T{helper.TrueIndex} {EscapeMarkdown(helper.DisplayLabel)} | {EscapeMarkdown(string.Join(", ", companions.OrderBy(moby => moby.TrueIndex).Select(moby => $"T{moby.TrueIndex}")))} |");
    }

    int proofOnlyPortalTriplets = 0;
    foreach ((string levelKey, int targetTrueIndex) in KnownPortalTripletProofRows())
    {
        LevelDefinition level = catalog.FindByKey(levelKey)
            ?? throw new InvalidOperationException($"Known portal triplet proof level is missing from catalog: {levelKey}.");

        string linkKey = $"{levelKey}:control-role-proof:t{targetTrueIndex}";
        if (CheckedInBehaviorLinkExists(levelKey, linkKey))
            throw new InvalidOperationException($"{level.DisplayName} T{targetTrueIndex} portal pad/control link must remain proof-only until live behavior is confirmed.");
        proofOnlyPortalTriplets++;
    }

    string markdownPath = Path.Combine(smokeRoot, "checked-in-control-role-companion-links.md");
    string jsonPath = Path.Combine(smokeRoot, "checked-in-control-role-companion-links.json");
    File.WriteAllText(markdownPath, string.Join(Environment.NewLine, [
        "# Checked-In Control Role Companion Links",
        "",
        "Regression proof that checked-in behavior-link JSON files are loaded by normal editor metadata and feed the same companion clone planner used by Add Object and Paste Object.",
        "",
        $"- Checked groups: {rows.Count}",
        $"- Portal/control triplets kept proof-only: {proofOnlyPortalTriplets}",
        $"- Checked-in files: `{workspace.RootPath}/*-behavior-links.json`",
        "",
        "| Role | Level | Link key | Clone root | Expected companions | Planner companions |",
        "|---|---|---|---|---|---|",
        .. summaryRows
    ]));
    File.WriteAllText(jsonPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now,
        checkedInBehaviorLinkPattern = Path.Combine(workspace.RootPath, "*-behavior-links.json"),
        checkedGroups = rows.Count,
        proofOnlyPortalTriplets,
        rows
    }, new JsonSerializerOptions { WriteIndented = true }));

    Console.WriteLine($"Checked-in control-role companion links: {rows.Count} group(s), report={markdownPath}");
}

bool CheckedInBehaviorLinkExists(string levelKey, string linkKey)
{
    string path = Path.Combine(workspace.RootPath, $"{levelKey}-behavior-links.json");
    if (!File.Exists(path))
        return false;

    using FileStream stream = File.OpenRead(path);
    using JsonDocument document = JsonDocument.Parse(stream);
    if (!document.RootElement.TryGetProperty("linkGroups", out JsonElement groups) || groups.ValueKind != JsonValueKind.Array)
        return false;

    return groups.EnumerateArray().Any(group =>
        string.Equals(ReadJsonString(group, "key"), linkKey, StringComparison.OrdinalIgnoreCase));
}

IReadOnlyList<int> ReadCheckedInBehaviorLinkIndexes(string levelKey, string linkKey)
{
    string path = Path.Combine(workspace.RootPath, $"{levelKey}-behavior-links.json");
    if (!File.Exists(path))
        throw new FileNotFoundException($"Checked-in behavior link file is missing for {levelKey}.", path);

    using FileStream stream = File.OpenRead(path);
    using JsonDocument document = JsonDocument.Parse(stream);
    if (!document.RootElement.TryGetProperty("linkGroups", out JsonElement groups) || groups.ValueKind != JsonValueKind.Array)
        throw new InvalidOperationException($"{path} does not contain a linkGroups array.");

    foreach (JsonElement group in groups.EnumerateArray())
    {
        if (!string.Equals(ReadJsonString(group, "key"), linkKey, StringComparison.OrdinalIgnoreCase))
            continue;

        if (!group.TryGetProperty("trueIndexes", out JsonElement values) || values.ValueKind != JsonValueKind.Array)
            throw new InvalidOperationException($"{path} link {linkKey} does not contain trueIndexes.");

        List<int> indexes = new();
        foreach (JsonElement value in values.EnumerateArray())
        {
            if (value.ValueKind == JsonValueKind.Number && value.TryGetInt32(out int trueIndex) && trueIndex >= 0)
                indexes.Add(trueIndex);
        }

        if (indexes.Count < 2)
            throw new InvalidOperationException($"{path} link {linkKey} must include at least two true indexes.");

        return indexes;
    }

    throw new InvalidOperationException($"{path} is missing checked-in behavior link {linkKey}.");
}

Moby SelectPortalTripletCloneRoot(Moby target, IReadOnlyList<Moby> anchors)
{
    return anchors.FirstOrDefault(IsPortalVisibleAnchorMoby) ??
        anchors.FirstOrDefault(IsReturnHomeVisibleMoby) ??
        target;
}

List<Moby> SelectPortalTripletCloneAnchors(string levelKey, Moby target, IReadOnlyList<Moby> levelMobys)
{
    HomeworldPortalControlDefinition? mappedPortal = HomeworldPortalControlCatalog
        .ForLevel(levelKey)
        .SingleOrDefault(definition => definition.TrueIndexes.Contains(target.TrueIndex));
    if (mappedPortal == null)
        return SelectPortalReturnHomeProofAnchors(target, levelMobys);

    Dictionary<int, Moby> byTrueIndex = levelMobys
        .Where(moby => !moby.IsRemoved && moby.TrueIndex >= 0)
        .ToDictionary(moby => moby.TrueIndex);
    List<Moby> anchors = mappedPortal.TrueIndexes
        .Where(trueIndex => trueIndex != target.TrueIndex)
        .Select(trueIndex => byTrueIndex.TryGetValue(trueIndex, out Moby? moby) ? moby : null)
        .Where(moby => moby != null)
        .Select(moby => moby!)
        .ToList();
    if (anchors.Count != mappedPortal.TrueIndexes.Count - 1)
    {
        throw new InvalidOperationException(
            $"{levelKey} mapped portal {mappedPortal.DestinationName} is missing one or more exact clone anchors for T{target.TrueIndex}.");
    }

    return anchors;
}

