    }

    if (!beforeRecord.SequenceEqual(sourceTargetRecord))
        throw new InvalidOperationException("The candidate T7 preimage does not match the selected original Blowhard BIN.");
    foreach (int offset in new[] { 0x0C, 0x10, 0x14 })
    {
