    string provenV3Image = Path.Combine(objectsDirectory, $"{CurrentToastyWizardCandidateSlug}.bin");
    string provenV3Cue = Path.Combine(objectsDirectory, $"{CurrentToastyWizardCandidateSlug}.cue");
