    if (!File.Exists(mobyPath))
    {
        Console.WriteLine($"{levelKey} repeated native clone guard: moby cache not found; skipping.");
        return;
    }

    List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
    MobyMetadataEnricher.Apply(workspace, level.Key, sourceMobys);
    Moby? donor = sourceMobys.FirstOrDefault(moby =>
        moby.TrueIndex >= 0 &&
        moby.TrueIndex < level.SourceRecordCount &&
        moby.Type == 0x20 &&
        moby.SourceByte36 == 0xA6 &&
        moby.Flag4A == 0x10)
        ?? sourceMobys.FirstOrDefault(moby =>
            moby.TrueIndex >= 0 &&
            moby.TrueIndex < level.SourceRecordCount &&
            moby.Type == 0x20 &&
            moby.Flag4A == 0x10);
    if (donor == null)
    {
        Console.WriteLine($"{level.DisplayName} repeated native clone guard: donor object not found; skipping.");
        return;
    }

    int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
    int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
    Moby first = CopyAsAddedMoby(donor, nextIndex, nextTrueIndex, $"Guard native clone A {donor.DisplayLabel}", 5);
    Moby second = CopyAsAddedMoby(donor, nextIndex + 1, nextTrueIndex + 1, $"Guard native clone B {donor.DisplayLabel}", 9);
    foreach (Moby added in new[] { first, second })
    {
        added.PatchStatus = "native-clone";
        added.PatchLead = $"Smoke repeated native clone guard from same-level donor T{donor.TrueIndex}.";
        added.Confidence = "same-level-native-clone";
        added.Evidence = $"Added from same-level donor T{donor.TrueIndex}.";
    }

    string path = Path.Combine(workspace.RootPath, "_local", "smoke", $"{levelKey}-repeated-native-clone-guard-native-edits.json");
    await MobyEditStore.SaveAsync(path, [first, second], $"{level.DisplayName} repeated native clone guard");
    MobySourcePatchResult exportResult = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
        SourceImagePath: sourceImage,
        SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
        OutputPrefix: Path.Combine(workspace.RootPath, "_local", "objects", $"{levelKey}-repeated-native-clone-guard"),
        Level: level,
        NativeEditsPath: path,
        WriteImage: true));
    MobySourcePatchPlan plan = exportResult.Plan;
    if (!exportResult.WroteImage)
        throw new InvalidOperationException($"{level.DisplayName} repeated native clone auto-slot route did not write a BIN.");
    VerifyPatchBytes(exportResult.OutputImagePath, plan);

    List<MobySourcePatch> appendPatches = plan.Patches
        .Where(patch => string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase))
        .ToList();
    if (appendPatches.Count != 0)
        throw new InvalidOperationException($"{level.DisplayName} repeated native clone auto-slot route wrote {appendPatches.Count} append patch(es), expected none.");
    if (plan.SkippedEdits.Count != 0)
        throw new InvalidOperationException($"{level.DisplayName} repeated native clone auto-slot route skipped edit(s): {string.Join("; ", plan.SkippedEdits)}");

    MobySourcePatch? sourceCountPatch = plan.Patches.FirstOrDefault(patch =>
        string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase));
    if (sourceCountPatch != null)
        throw new InvalidOperationException($"{level.DisplayName} repeated native clone auto-slot route unexpectedly wrote a source-count patch.");
    List<MobySourcePatch> slotPatches = plan.Patches
        .Where(patch => string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase))
        .OrderBy(patch => patch.MobyLabel)
        .ToList();
    if (slotPatches.Count != 2 || slotPatches.Select(patch => patch.TrueIndex).Distinct().Count() != 2)
        throw new InvalidOperationException($"{level.DisplayName} repeated native clone auto-slot route wrote {slotPatches.Count} unique slot clone patch(es), expected 2.");
    VerifySlotClonePatchIdentity($"{level.DisplayName} repeated native clone auto-slot route A", slotPatches[0], donor, first.Position);
    VerifySlotClonePatchIdentity($"{level.DisplayName} repeated native clone auto-slot route B", slotPatches[1], donor, second.Position);

    Console.WriteLine($"{level.DisplayName} repeated native clone auto-slot route: wrote {slotPatches.Count} slot clone(s), source count stays {level.SourceRecordCount}");
}

async Task ReportPromotedNativeCloneTrueAppend(string levelKey, int sourceByte36, string familyName)
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine($"{levelKey} promoted {familyName} append: source disc not found; skipping.");
        return;
    }

    LevelDefinition? level = catalog.FindByKey(levelKey);
    if (level == null || !level.HasSourceTable)
    {
        Console.WriteLine($"{levelKey} promoted {familyName} append: source table is not mapped; skipping.");
        return;
    }

    string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{levelKey}-mobys.json");
    if (!File.Exists(mobyPath))
    {
        Console.WriteLine($"{levelKey} promoted {familyName} append: moby cache not found; skipping.");
        return;
    }

    List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
    Moby? donor = sourceMobys.FirstOrDefault(moby => IsPromotedNativeCloneTrueAppendSmokeDonor(moby, level, sourceByte36));
    if (donor == null)
    {
        Console.WriteLine($"{level.DisplayName} promoted {familyName} append: donor object not found; skipping.");
        return;
    }

    int reusableSlotCount = sourceMobys.Count(moby => IsPromotedNativeCloneTrueAppendSmokeCandidate(moby, level, donor));
    int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
    int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
    List<Moby> addedMobys = new();
    for (int i = 0; i <= reusableSlotCount + 1; i++)
    {
        Moby added = CopyAsAddedMoby(donor, nextIndex + i, nextTrueIndex + i, $"Promoted {familyName} clone {i + 1}", 0);
        added.PatchStatus = "native-clone";
        added.PatchLead = $"Promoted true-append smoke from same-level {familyName} donor T{donor.TrueIndex}.";
        added.Confidence = "same-level-native-clone";
        added.Evidence = $"Copied from same-level {familyName} donor T{donor.TrueIndex}; live testing proved this family can true-add after reuse slots are consumed.";
        added.SourceCloneLevelKey = level.Key;
        added.SourceCloneLevelName = level.DisplayName;
        added.SourceCloneTrueIndex = donor.TrueIndex;
        addedMobys.Add(added);
    }

    string familySlug = familyName.ToLowerInvariant().Replace("/", "-").Replace(" ", "-");
    string path = Path.Combine(workspace.RootPath, "_local", "smoke", $"{levelKey}-promoted-{familySlug}-append-native-edits.json");
    await MobyEditStore.SaveAsync(path, addedMobys, $"{level.DisplayName} promoted {familyName} true-append");
    MobySourcePatchResult exportResult = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
        SourceImagePath: sourceImage,
        SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
        OutputPrefix: Path.Combine(workspace.RootPath, "_local", "objects", $"{levelKey}-promoted-{familySlug}-append"),
        Level: level,
        NativeEditsPath: path,
        WriteImage: true));
    MobySourcePatchPlan plan = exportResult.Plan;
    if (!exportResult.WroteImage)
        throw new InvalidOperationException($"{level.DisplayName} promoted {familyName} append did not write a BIN.");
    VerifyPatchBytes(exportResult.OutputImagePath, plan);
    if (plan.SkippedEdits.Count != 1 ||
        !plan.SkippedEdits[0].Contains("safety budget", StringComparison.OrdinalIgnoreCase) ||
        !plan.SkippedEdits[0].Contains("multiple active enemy/chest appends can crash", StringComparison.OrdinalIgnoreCase))
    {
        throw new InvalidOperationException(
            $"{level.DisplayName} promoted {familyName} append did not guard exactly one over-budget edit: {string.Join("; ", plan.SkippedEdits)}");
    }

    List<MobySourcePatch> slotPatches = plan.Patches
        .Where(patch => string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase))
        .ToList();
    if (slotPatches.Count != reusableSlotCount)
        throw new InvalidOperationException($"{level.DisplayName} promoted {familyName} append wrote {slotPatches.Count} slot clone patch(es), expected {reusableSlotCount} before true-append.");

    List<MobySourcePatch> appendPatches = plan.Patches
        .Where(patch => string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase))
        .ToList();
    if (appendPatches.Count != 1)
        throw new InvalidOperationException($"{level.DisplayName} promoted {familyName} append wrote {appendPatches.Count} append patch(es), expected 1.");
    if (!appendPatches[0].Description.Contains("Placement sector byte set", StringComparison.OrdinalIgnoreCase))
        throw new InvalidOperationException($"{level.DisplayName} promoted {familyName} append did not recalculate the placement sector byte.");

    byte[] appendedRecord = ParseHexPreview(appendPatches[0].AfterHexPreview);
    if (appendedRecord.Length <= 0x53 ||
        appendedRecord[0x50] != donor.Type ||
        appendedRecord[0x36] != donor.SourceByte36 ||
        appendedRecord[0x37] != donor.SourceByte37 ||
        appendedRecord[0x4F] != donor.SourceByte4F ||
        appendedRecord[0x52] != donor.Flag4A ||
        appendedRecord[0x53] != donor.Flag4B)
    {
        throw new InvalidOperationException($"{level.DisplayName} promoted {familyName} append did not preserve the donor identity bytes.");
    }

    MobySourcePatch? sourceCountPatch = plan.Patches.FirstOrDefault(patch =>
        string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase));
    if (sourceCountPatch == null || BitConverter.ToInt32(ParseHexPreview(sourceCountPatch.AfterHexPreview), 0) != level.SourceRecordCount + appendPatches.Count)
        throw new InvalidOperationException($"{level.DisplayName} promoted {familyName} append did not bump the source count by the true-append count.");

    Console.WriteLine($"{level.DisplayName} promoted {familyName} append: reused {slotPatches.Count} slot(s), true-appended T{appendPatches[0].TrueIndex}, then guarded one crash-risk excess row");
}

bool IsResidentRowCandidate(CrossLevelSwapCatalogEntry entry) =>
    !entry.SameLevel &&
    entry.Placeable &&
    string.Equals(entry.CompatibilityTier, CrossLevelSwapCatalogBuilder.ResidentActorCompatibility, StringComparison.OrdinalIgnoreCase) &&
    string.Equals(entry.RequiredExporterFeature, CrossLevelSwapCatalogBuilder.CandidateExporterFeature, StringComparison.OrdinalIgnoreCase);

async Task ReportCrossLevelSwapCatalogSmoke()
{
    if (!File.Exists(sourceImage))
        throw new FileNotFoundException("The cross-level swap catalogue smoke needs the selected source BIN.", sourceImage);

    LevelDefinition[] sourceBackedLevels = catalog.Levels
        .Where(level => level.HasSourceTable)
        .OrderBy(level => level.DisplayName, StringComparer.OrdinalIgnoreCase)
        .ToArray();
    List<CrossLevelSwapCatalog> catalogs = sourceBackedLevels
        .Select(level => CrossLevelSwapCatalogBuilder.Build(workspace, catalog, level.Key))
        .ToList();
    if (catalogs.Count == 0 || catalogs.Any(item => item.EntryCount == 0))
        throw new InvalidOperationException("The cross-level swap catalogue is empty for one or more source-backed levels.");
    if (catalogs.Any(item => !item.Entries.Any(entry => entry.Category == CrossLevelSwapCategory.Chest)))
        throw new InvalidOperationException("The cross-level swap catalogue is missing chest entries.");
    if (catalogs.Any(item => !item.Entries.Any(entry => entry.Category == CrossLevelSwapCategory.Enemy)))
        throw new InvalidOperationException("The cross-level swap catalogue is missing enemy entries.");
    if (catalogs.Sum(item => item.CandidateCount) == 0)
        throw new InvalidOperationException("The cross-level swap catalogue did not expose any guarded existing-slot candidates.");
    if (catalogs.Sum(item => item.ReadyCount) == 0)
        throw new InvalidOperationException("The cross-level swap catalogue did not expose any same-level native slot-reuse entries.");
    if (catalogs.Sum(item => item.UnmappedCount) == 0)
        throw new InvalidOperationException("The cross-level swap catalogue did not identify any missing target actor-package mappings.");

    CrossLevelSwapCatalog blowhardCatalog = catalogs.Single(item =>
        string.Equals(LevelCatalog.NormalizeKey(item.TargetLevelKey), "blowhard", StringComparison.OrdinalIgnoreCase));
    CrossLevelSwapCatalogEntry? blowhardWizard = blowhardCatalog.Entries.FirstOrDefault(entry =>
        string.Equals(entry.Id, "enemy.green_wizard.blowhard.t0", StringComparison.OrdinalIgnoreCase));
    if (blowhardWizard == null ||
        !blowhardWizard.SameLevel ||
        !blowhardWizard.Placeable ||
        !blowhardWizard.NormalCreateBinReady ||
        !string.Equals(blowhardWizard.CompatibilityTier, CrossLevelSwapCatalogBuilder.GreenWizardVerifiedCompatibility, StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(blowhardWizard.SupportStatus, "verified-green-wizard-runtime-bundle", StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(blowhardWizard.RequiredExporterFeature, CrossLevelSwapCatalogBuilder.CandidateExporterFeature, StringComparison.OrdinalIgnoreCase) ||
        !blowhardWizard.SupportNote.Contains("Verified in Blowhard", StringComparison.OrdinalIgnoreCase) ||
        !blowhardWizard.SupportNote.Contains("Normal Create BIN and Create Swap Test", StringComparison.OrdinalIgnoreCase))
    {
        throw new InvalidOperationException("The Blowhard T0 Green Wizard catalogue entry should be runtime-proven for normal Create BIN while retaining its dependency-aware existing-slot writer.");
    }

    CrossLevelSwapCatalog magicCraftersCatalog = catalogs.Single(item =>
        string.Equals(LevelCatalog.NormalizeKey(item.TargetLevelKey), "magiccrafters", StringComparison.OrdinalIgnoreCase));
    CrossLevelSwapCatalogEntry[] magicCraftersWizards = magicCraftersCatalog.Entries
        .Where(entry => entry.ActorId == GreenWizardRuntimeBundleCompatibility.ActorId && entry.Placeable)
        .ToArray();
    if (magicCraftersWizards.Length != 1 ||
        !string.Equals(magicCraftersWizards[0].Id, GreenWizardRuntimeBundleCompatibility.MagicCraftersTemplateId, StringComparison.OrdinalIgnoreCase) ||
        magicCraftersWizards[0].SourceTrueIndex != GreenWizardRuntimeBundleCompatibility.MagicCraftersSourceTrueIndex ||
        !magicCraftersWizards[0].SameLevel ||
        !magicCraftersWizards[0].NormalCreateBinReady ||
        !string.Equals(magicCraftersWizards[0].CompatibilityTier, CrossLevelSwapCatalogBuilder.GreenWizardVerifiedCompatibility, StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(magicCraftersWizards[0].SupportStatus, "verified-green-wizard-runtime-bundle", StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(magicCraftersWizards[0].PackageRecipeId, MagicCraftersGreenWizardResidentSwapExporter.RecipeId, StringComparison.OrdinalIgnoreCase) ||
        !magicCraftersWizards[0].SupportNote.Contains("Verified in Magic Crafters", StringComparison.OrdinalIgnoreCase) ||
        !magicCraftersWizards[0].SupportNote.Contains("Normal Create BIN and Create Swap Test", StringComparison.OrdinalIgnoreCase))
    {
        throw new InvalidOperationException("The Magic Crafters T107 Green Wizard catalogue entry should expose only the runtime-proven T27 replacement route to normal Create BIN.");
    }

    CrossLevelSwapCatalog wizardPeakCatalog = catalogs.Single(item =>
        string.Equals(LevelCatalog.NormalizeKey(item.TargetLevelKey), "wizardpeak", StringComparison.OrdinalIgnoreCase));
    CrossLevelSwapCatalogEntry[] wizardPeakWizards = wizardPeakCatalog.Entries
        .Where(entry => entry.ActorId == GreenWizardRuntimeBundleCompatibility.ActorId && entry.Placeable)
        .ToArray();
    if (wizardPeakWizards.Length != 1 ||
        wizardPeakWizards[0].SourceTrueIndex != GreenWizardRuntimeBundleCompatibility.SourceTrueIndex ||
        !wizardPeakWizards[0].SameLevel ||
        !wizardPeakWizards[0].NormalCreateBinReady ||
        !string.Equals(wizardPeakWizards[0].CompatibilityTier, CrossLevelSwapCatalogBuilder.GreenWizardVerifiedCompatibility, StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(wizardPeakWizards[0].SupportStatus, "verified-green-wizard-runtime-bundle", StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(wizardPeakWizards[0].PackageRecipeId, WizardPeakGreenWizardNativeSwapExporter.RecipeId, StringComparison.OrdinalIgnoreCase) ||
        !wizardPeakWizards[0].SupportNote.Contains("T6-to-Elder-Wizard-T24", StringComparison.OrdinalIgnoreCase) ||
        !wizardPeakWizards[0].SupportNote.Contains("Normal Create BIN and Create Swap Test", StringComparison.OrdinalIgnoreCase))
    {
        throw new InvalidOperationException("Wizard Peak's catalogue should expose only native T6 as the runtime-proven exact Elder Wizard T24 Green Wizard replacement.");
    }

    CrossLevelSwapCatalog toastyCatalog = catalogs.Single(item =>
        string.Equals(LevelCatalog.NormalizeKey(item.TargetLevelKey), "toasty", StringComparison.OrdinalIgnoreCase));
    CrossLevelSwapCatalogEntry? toastyWizardPackage = toastyCatalog.Entries.FirstOrDefault(entry =>
        string.Equals(entry.Id, "enemy.green_wizard.wizardpeak.t6", StringComparison.OrdinalIgnoreCase));
    if (toastyWizardPackage == null ||
        toastyWizardPackage.Placeable ||
        toastyWizardPackage.NormalCreateBinReady ||
        !string.Equals(toastyWizardPackage.CompatibilityTier, CrossLevelSwapCatalogBuilder.GreenWizardUnsupportedCompatibility, StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(toastyWizardPackage.SupportStatus, "unsupported-green-wizard-runtime-bundle", StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(toastyWizardPackage.PackageRecipeId, GreenWizardRuntimeBundleCompatibility.ToastyV11RecipeId, StringComparison.OrdinalIgnoreCase) ||
        !string.Equals(toastyWizardPackage.RequiredExporterFeature, "GreenWizardRuntimeBundleProfile", StringComparison.OrdinalIgnoreCase) ||
        !toastyWizardPackage.SupportNote.Contains("runtime-verified", StringComparison.OrdinalIgnoreCase) ||
        !toastyWizardPackage.SupportNote.Contains("do not yet compose", StringComparison.OrdinalIgnoreCase))
    {
        throw new InvalidOperationException("The Toasty Green Wizard should remain visible as runtime-proven but non-placeable until the editor composes the v11 exporter route.");
    }

    CrossLevelSwapCatalogEntry? unsafeEnemy = catalogs
        .SelectMany(item => item.Entries)
        .FirstOrDefault(entry =>
            entry.Category == CrossLevelSwapCategory.Enemy &&
            entry.Eligible &&
            (!string.Equals(entry.CandidateKind, "enemy", StringComparison.OrdinalIgnoreCase) &&
             !entry.CandidateKind.EndsWith(" enemy", StringComparison.OrdinalIgnoreCase) ||
             entry.CandidateKind.Contains("control enemy", StringComparison.OrdinalIgnoreCase) ||
             entry.CandidateKind.Contains("linked record", StringComparison.OrdinalIgnoreCase) ||
             entry.CandidateKind.Contains("scenery", StringComparison.OrdinalIgnoreCase) ||
             entry.CandidateKind.Contains("prop", StringComparison.OrdinalIgnoreCase) ||
             entry.Confidence.Contains("inferred", StringComparison.OrdinalIgnoreCase) ||
             entry.Confidence.Contains("review-family", StringComparison.OrdinalIgnoreCase)));
    if (unsafeEnemy != null)
        throw new InvalidOperationException($"Non-self-contained enemy entry remained eligible: {unsafeEnemy.DisplayName} ({unsafeEnemy.CandidateKind}, {unsafeEnemy.Confidence}).");

    string[] deferredChestTerms = ["spring chest", "firework chest", "3x flame", "super flame", "life chest", "key chest", "locked chest", "multi-gem", "multi gem", "chest link", "chest-linked"];
    CrossLevelSwapCatalogEntry? unsafeChest = catalogs
        .SelectMany(item => item.Entries)
        .FirstOrDefault(entry =>
            entry.Category == CrossLevelSwapCategory.Chest &&
            entry.Eligible &&
            deferredChestTerms.Any(term =>
                entry.DisplayName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                entry.CandidateKind.Contains(term, StringComparison.OrdinalIgnoreCase)));
    if (unsafeChest != null)
        throw new InvalidOperationException($"Special or linked chest entry remained eligible: {unsafeChest.DisplayName} ({unsafeChest.CandidateKind}).");

    CrossLevelSwapCatalog referenceCatalog = catalogs.FirstOrDefault(item =>
        item.Entries.Any(IsResidentRowCandidate) &&
        item.Entries.Any(entry => entry.SameLevel && entry.Eligible))
        ?? catalogs.First(item => item.Entries.Any(IsResidentRowCandidate));
    bool hasDeferredSpecialChest = referenceCatalog.Entries.Any(entry =>
        entry.Category == CrossLevelSwapCategory.Chest &&
        !entry.Eligible &&
        (entry.DisplayName.Contains("spring", StringComparison.OrdinalIgnoreCase) ||
         entry.DisplayName.Contains("firework", StringComparison.OrdinalIgnoreCase) ||
         entry.DisplayName.Contains("life chest", StringComparison.OrdinalIgnoreCase) ||
         entry.DisplayName.Contains("locked chest", StringComparison.OrdinalIgnoreCase) ||
         entry.DependencyRisk.Contains("Special chest family", StringComparison.OrdinalIgnoreCase)));
    if (!hasDeferredSpecialChest)
        throw new InvalidOperationException("Special linked chest families were not retained as visible deferred catalogue entries.");

    LevelDefinition targetLevel = catalog.FindByKey(referenceCatalog.TargetLevelKey)
        ?? throw new InvalidOperationException($"Catalogue smoke target {referenceCatalog.TargetLevelKey} is missing.");
    string targetCachePath = Path.Combine(workspace.RootPath, "editor-cache", $"{targetLevel.Key}-mobys.json");
    if (!File.Exists(targetCachePath))
        throw new FileNotFoundException("The cross-level swap smoke target cache is missing.", targetCachePath);
    List<Moby> targetMobys = MobyLoader.LoadCached(targetCachePath).ToList();
    MobyMetadataEnricher.Apply(workspace, targetLevel.Key, targetMobys);

    Moby? target = null;
    CrossLevelSwapCategory targetCategory = default;
    foreach (Moby candidate in targetMobys
        .Where(moby => !moby.IsRemoved && !moby.IsAdded)
        .Where(moby => moby.TrueIndex >= 0 && moby.TrueIndex < targetLevel.SourceRecordCount)
        .OrderBy(moby => moby.VisualKind == MobyVisualKind.Chest ? 0 : 1)
        .ThenBy(moby => moby.TrueIndex))
    {
        if (!CrossLevelSwapCatalogBuilder.TryGetEligibleTargetCategory(candidate, out CrossLevelSwapCategory category, out _))
            continue;
        if (!referenceCatalog.Entries.Any(entry => entry.Category == category && IsResidentRowCandidate(entry)))
            continue;
        target = candidate;
        targetCategory = category;
        break;
    }
    if (target == null)
        throw new InvalidOperationException($"{targetLevel.DisplayName} has no eligible existing chest/enemy slot for the catalogue smoke.");

    CrossLevelSwapCatalogEntry donor = referenceCatalog.Entries
        .Where(entry => entry.Category == targetCategory && IsResidentRowCandidate(entry))
        .OrderBy(entry => entry.SourceLevelName, StringComparer.OrdinalIgnoreCase)
        .ThenBy(entry => entry.SourceTrueIndex)
        .First();
    Moby edited = CloneMoby(target);
    edited.SetType(donor.Type);
    edited.State = donor.State;
    edited.SourceByte36 = donor.SourceByte36;
    edited.SourceByte37 = donor.SourceByte37;
    edited.SourceByte4F = donor.SourceByte4F;
    edited.Flag4A = donor.Flag4A;
    edited.Flag4B = donor.Flag4B;
    edited.Label = $"Swap smoke {donor.DisplayName}";
    edited.PatchStatus = donor.SupportStatus;
    edited.PatchLead = "Guarded cross-level existing-slot catalogue smoke.";
    edited.CrossLevelTemplateId = donor.Id;
    edited.CrossLevelFamily = donor.Family;
    edited.CrossLevelSourceLevelKey = donor.SourceLevelKey;
    edited.CrossLevelSourceLevelName = donor.SourceLevelName;
    edited.CrossLevelSourceTrueIndex = donor.SourceTrueIndex;
    edited.CrossLevelRequiredExporterFeature = donor.RequiredExporterFeature;
    edited.CandidateKind = donor.CandidateKind;
    edited.Confidence = "cross-level-swap-smoke";
    edited.HasLoadedNativeEdit = true;
    edited.LoadedNativeEditSummary = "Guarded existing-slot swap smoke";

    string reportRoot = Path.Combine(workspace.RootPath, "_local", "smoke", "cross-level-swap-catalog");
    Directory.CreateDirectory(reportRoot);
    (string EnemyTargetLevel, int EnemyTargetTrueIndex, string EnemyDonorLevel, int EnemyDonorTrueIndex, string EnemyPlanPath) =
        await VerifyCrossLevelEnemyExistingSlotCandidate(catalogs, reportRoot);
    string nativeEditsPath = Path.Combine(reportRoot, $"{targetLevel.Key}-swap-catalog-smoke-native-edits.json");
    string normalPlanPath = Path.Combine(reportRoot, "normal-create-bin-guard-plan.json");
    string candidatePlanPath = Path.Combine(reportRoot, "candidate-existing-slot-plan.json");
    string catalogJsonPath = Path.Combine(reportRoot, $"{targetLevel.Key}-swap-catalog.json");
    string catalogMarkdownPath = Path.Combine(reportRoot, $"{targetLevel.Key}-swap-catalog.md");
    string summaryJsonPath = Path.Combine(reportRoot, "cross-level-swap-catalog-smoke-report.json");
    string summaryMarkdownPath = Path.Combine(reportRoot, "cross-level-swap-catalog-smoke-report.md");
    try
    {
        await MobyEditStore.SaveAsync(nativeEditsPath, [edited], $"{targetLevel.DisplayName} guarded swap catalogue smoke");
        MobySourcePatchPlan normalPlan = MobySourcePatchExporter.BuildPlan(
            sourceImage,
            DiscImageLocator.FindCueForImage(sourceImage),
            Path.Combine(reportRoot, "normal-create-bin-guard.bin"),
            Path.Combine(reportRoot, "normal-create-bin-guard.cue"),
            targetLevel,
            nativeEditsPath);
        if (normalPlan.Patches.Any(patch => string.Equals(patch.Kind, "cross-level-existing-slot-candidate", StringComparison.OrdinalIgnoreCase)))
            throw new InvalidOperationException("Normal Create BIN emitted a guarded cross-level existing-slot candidate patch.");
        if (!normalPlan.SkippedEdits.Any(skip => skip.Contains("Create Swap Test", StringComparison.OrdinalIgnoreCase)))
            throw new InvalidOperationException("Normal Create BIN did not explain that the guarded swap requires Create Swap Test.");
        if (normalPlan.Patches.Any(patch => string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase)))
            throw new InvalidOperationException("Normal Create BIN changed the source count for a guarded slot swap.");

        MobySourcePatchPlan candidatePlan = MobySourcePatchExporter.BuildPlan(
            sourceImage,
            DiscImageLocator.FindCueForImage(sourceImage),
            Path.Combine(reportRoot, "candidate-existing-slot.bin"),
            Path.Combine(reportRoot, "candidate-existing-slot.cue"),
            targetLevel,
            nativeEditsPath,
            allowPlanOnlyActorPackageImports: true);
        List<MobySourcePatch> rowPatches = candidatePlan.Patches
            .Where(patch => string.Equals(patch.Kind, "cross-level-existing-slot-candidate", StringComparison.OrdinalIgnoreCase))
            .ToList();
        if (rowPatches.Count != 1)
            throw new InvalidOperationException($"Candidate mode wrote {rowPatches.Count} existing-slot row patch(es), expected exactly 1.");
        if (candidatePlan.Patches.Any(patch => string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase)))
            throw new InvalidOperationException("Candidate mode changed the source count for an existing-slot swap.");

        MobySourcePatch rowPatch = rowPatches[0];
        if (rowPatch.TrueIndex != target.TrueIndex || rowPatch.ByteLength != 0x58)
            throw new InvalidOperationException("The candidate patch did not replace exactly the selected existing 0x58-byte row.");
        if (!rowPatch.Description.Contains($"Source object count remains {targetLevel.SourceRecordCount}", StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("The candidate patch does not document its unchanged source count.");
        byte[] before = ParseHexPreview(rowPatch.BeforeHexPreview);
        byte[] after = ParseHexPreview(rowPatch.AfterHexPreview);
        foreach (int offset in new[] { 0x0C, 0x10, 0x14 })
        {
            if (BitConverter.ToInt32(before, offset) != BitConverter.ToInt32(after, offset))
                throw new InvalidOperationException($"Candidate slot swap changed placement coordinate at record offset 0x{offset:X2}.");
        }
        if (after[0x50] != donor.Type ||
            after[0x51] != donor.State ||
            after[0x36] != donor.SourceByte36 ||
            after[0x37] != donor.SourceByte37 ||
            after[0x4F] != donor.SourceByte4F ||
            after[0x52] != donor.Flag4A ||
            after[0x53] != donor.Flag4B)
        {
            throw new InvalidOperationException("Candidate slot swap did not write the selected donor identity bytes.");
        }
        if (targetCategory == CrossLevelSwapCategory.Chest &&
            (!before.AsSpan(0x00, 0x04).SequenceEqual(after.AsSpan(0x00, 0x04)) ||
             !before.AsSpan(0x38, 0x0E).SequenceEqual(after.AsSpan(0x38, 0x0E))))
        {
            throw new InvalidOperationException("Cross-level chest candidate did not preserve the target slot behavior/reward bytes.");
        }

        await File.WriteAllTextAsync(normalPlanPath, JsonSerializer.Serialize(normalPlan, new JsonSerializerOptions { WriteIndented = true }));
        await File.WriteAllTextAsync(candidatePlanPath, JsonSerializer.Serialize(candidatePlan, new JsonSerializerOptions { WriteIndented = true }));
        string candidateValidationPath = await MobyCandidateValidationReportWriter.WriteAsync(new MobySourcePatchResult(
            candidatePlan.OutputImagePath,
            candidatePlan.OutputCuePath,
            candidatePlanPath,
            candidatePlan,
            WroteImage: false));
        string candidateValidationText = await File.ReadAllTextAsync(candidateValidationPath);
        if (!candidateValidationText.Contains("Existing-Slot Swap Candidates", StringComparison.Ordinal) ||
            !candidateValidationText.Contains("remains visible from several camera angles", StringComparison.OrdinalIgnoreCase) ||
            !candidateValidationText.Contains("nearby enemies, chests, dragons, portals, and collision", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("Candidate validation report is missing the existing-slot visibility, behavior, or nearby-regression checklist.");
        }
        await CrossLevelSwapCatalogBuilder.WriteAsync(referenceCatalog, catalogJsonPath, catalogMarkdownPath);
        await File.WriteAllTextAsync(summaryJsonPath, JsonSerializer.Serialize(new
        {
            GeneratedAtUtc = DateTimeOffset.UtcNow,
            SourceBackedLevelCount = sourceBackedLevels.Length,
            CatalogueEntryRange = new
            {
                Minimum = catalogs.Min(item => item.EntryCount),
                Maximum = catalogs.Max(item => item.EntryCount)
            },
            SameLevelReadyTotal = catalogs.Sum(item => item.ReadyCount),
            CrossLevelCandidateTotal = catalogs.Sum(item => item.CandidateCount),
            ResidentActorRootCandidateTotal = catalogs.Sum(item => item.ResidentCandidateCount),
            PackageBackedCandidateTotal = catalogs.Sum(item => item.PackageCandidateCount),
            MissingActorPackageMappingTotal = catalogs.Sum(item => item.UnmappedCount),
            DeferredTotal = catalogs.Sum(item => item.DeferredCount),
            TargetLevel = targetLevel.DisplayName,
            TargetTrueIndex = target.TrueIndex,
            TargetCategory = targetCategory.ToString(),
            Donor = new { donor.DisplayName, donor.SourceLevelName, donor.SourceTrueIndex },
            EnemyCandidate = new
            {
                TargetLevel = EnemyTargetLevel,
                TargetTrueIndex = EnemyTargetTrueIndex,
                DonorLevel = EnemyDonorLevel,
                DonorTrueIndex = EnemyDonorTrueIndex,
                PlanPath = EnemyPlanPath
            },
            NormalCreateBinCandidatePatchCount = 0,
            CandidateExistingSlotPatchCount = rowPatches.Count,
            SourceCountBefore = targetLevel.SourceRecordCount,
            SourceCountAfter = targetLevel.SourceRecordCount,
            PlacementPreserved = true,
            ChestBehaviorPreserved = true,
            BinCueWritten = false,
            RuntimeBoundary = "The candidate row is structurally guarded and byte-verified. Cross-level visuals, collision, behavior, defeat, and reward still require DuckStation testing."
        }, new JsonSerializerOptions { WriteIndented = true }));
        await File.WriteAllTextAsync(summaryMarkdownPath, $"""
            # Cross-Level Chest And Enemy Swap Catalogue Smoke

            - Source-backed target levels checked: {sourceBackedLevels.Length}
            - Catalogue entries per level: {catalogs.Min(item => item.EntryCount)} to {catalogs.Max(item => item.EntryCount)}
            - Same-level ready entries across targets: {catalogs.Sum(item => item.ReadyCount)}
            - Guarded cross-level candidates across targets: {catalogs.Sum(item => item.CandidateCount)}
            - Resident actor-root candidates across targets: {catalogs.Sum(item => item.ResidentCandidateCount)}
            - Package-backed candidates across targets: {catalogs.Sum(item => item.PackageCandidateCount)}
            - Missing actor-package mappings across targets: {catalogs.Sum(item => item.UnmappedCount)}
            - Deferred linked or uncertain entries across targets: {catalogs.Sum(item => item.DeferredCount)}
            - Byte-plan test: {targetLevel.DisplayName} T{target.TrueIndex} -> {donor.DisplayName} from {donor.SourceLevelName} T{donor.SourceTrueIndex}
            - Normal Create BIN candidate rows: 0
            - Create Swap Test candidate rows: 1
            - Source object count: {targetLevel.SourceRecordCount} -> {targetLevel.SourceRecordCount}
            - Existing XYZ placement: preserved
            - Enemy-row proof: {EnemyTargetLevel} T{EnemyTargetTrueIndex} -> {EnemyDonorLevel} T{EnemyDonorTrueIndex}
            - BIN/CUE written by this smoke: no

            Structural guard and row bytes passed. The cross-level candidate remains experimental until its appearance, interaction, reward, and nearby actors are tested in DuckStation.
            """);

        Console.WriteLine($"Cross-level swap catalogue: {sourceBackedLevels.Length} target levels, {referenceCatalog.EntryCount} entries for {targetLevel.DisplayName}, {referenceCatalog.CandidateCount} guarded candidates, {referenceCatalog.DeferredCount} deferred.");
        Console.WriteLine($"Existing-slot guard: normal Create BIN wrote 0 candidate rows; candidate mode wrote T{target.TrueIndex} from {donor.SourceLevelName} T{donor.SourceTrueIndex}; source count stayed {targetLevel.SourceRecordCount}.");
        Console.WriteLine($"Enemy candidate guard: {EnemyTargetLevel} T{EnemyTargetTrueIndex} <- {EnemyDonorLevel} T{EnemyDonorTrueIndex}; source count unchanged.");
        Console.WriteLine($"JSON: {summaryJsonPath}");
        Console.WriteLine($"Markdown: {summaryMarkdownPath}");
        Console.WriteLine($"Catalogue: {catalogMarkdownPath}");
        Console.WriteLine($"Candidate checklist: {candidateValidationPath}");
    }
    finally
    {
        if (File.Exists(nativeEditsPath))
            File.Delete(nativeEditsPath);
    }
}

async Task<(string TargetLevel, int TargetTrueIndex, string DonorLevel, int DonorTrueIndex, string PlanPath)> VerifyCrossLevelEnemyExistingSlotCandidate(
    IReadOnlyList<CrossLevelSwapCatalog> catalogs,
    string reportRoot)
{
    foreach (CrossLevelSwapCatalog targetCatalog in catalogs)
    {
        LevelDefinition? level = catalog.FindByKey(targetCatalog.TargetLevelKey);
        if (level == null)
            continue;
        string cachePath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-mobys.json");
        if (!File.Exists(cachePath))
            continue;

        List<Moby> mobys = MobyLoader.LoadCached(cachePath).ToList();
        MobyMetadataEnricher.Apply(workspace, level.Key, mobys);
        Moby? target = mobys.FirstOrDefault(moby =>
            !moby.IsAdded &&
            !moby.IsRemoved &&
            moby.TrueIndex >= 0 &&
            moby.TrueIndex < level.SourceRecordCount &&
            CrossLevelSwapCatalogBuilder.TryGetEligibleTargetCategory(moby, out CrossLevelSwapCategory category, out _) &&
            category == CrossLevelSwapCategory.Enemy);
        CrossLevelSwapCatalogEntry? donor = targetCatalog.Entries
            .Where(entry => entry.Category == CrossLevelSwapCategory.Enemy && IsResidentRowCandidate(entry))
            .OrderBy(entry => entry.SourceLevelName, StringComparer.OrdinalIgnoreCase)
            .ThenBy(entry => entry.SourceTrueIndex)
            .FirstOrDefault();
        if (target == null || donor == null)
            continue;

        Moby edited = CloneMoby(target);
        edited.SetType(donor.Type);
        edited.State = donor.State;
        edited.SourceByte36 = donor.SourceByte36;
        edited.SourceByte37 = donor.SourceByte37;
        edited.SourceByte4F = donor.SourceByte4F;
        edited.Flag4A = donor.Flag4A;
        edited.Flag4B = donor.Flag4B;
        edited.Label = $"Enemy swap smoke {donor.DisplayName}";
        edited.PatchStatus = donor.SupportStatus;
        edited.PatchLead = "Guarded self-contained enemy existing-slot smoke.";
        edited.CrossLevelTemplateId = donor.Id;
        edited.CrossLevelFamily = donor.Family;
        edited.CrossLevelSourceLevelKey = donor.SourceLevelKey;
        edited.CrossLevelSourceLevelName = donor.SourceLevelName;
        edited.CrossLevelSourceTrueIndex = donor.SourceTrueIndex;
        edited.CrossLevelRequiredExporterFeature = donor.RequiredExporterFeature;
        edited.CandidateKind = donor.CandidateKind;
        edited.Confidence = "cross-level-enemy-swap-smoke";
        edited.HasLoadedNativeEdit = true;
        edited.LoadedNativeEditSummary = "Guarded enemy existing-slot swap smoke";

        string nativeEditsPath = Path.Combine(reportRoot, $"{level.Key}-enemy-swap-smoke-native-edits.json");
        string planPath = Path.Combine(reportRoot, "candidate-enemy-existing-slot-plan.json");
        try
        {
            await MobyEditStore.SaveAsync(nativeEditsPath, [edited], $"{level.DisplayName} enemy swap catalogue smoke");
            MobySourcePatchPlan normalPlan = MobySourcePatchExporter.BuildPlan(
                sourceImage,
                DiscImageLocator.FindCueForImage(sourceImage),
                Path.Combine(reportRoot, "normal-enemy-guard.bin"),
                Path.Combine(reportRoot, "normal-enemy-guard.cue"),
                level,
                nativeEditsPath);
            if (normalPlan.Patches.Any(patch => string.Equals(patch.Kind, "cross-level-existing-slot-candidate", StringComparison.OrdinalIgnoreCase)) ||
                !normalPlan.SkippedEdits.Any(skip => skip.Contains("Create Swap Test", StringComparison.OrdinalIgnoreCase)))
            {
                throw new InvalidOperationException("Normal Create BIN did not guard the self-contained enemy slot candidate.");
            }

            MobySourcePatchPlan candidatePlan = MobySourcePatchExporter.BuildPlan(
                sourceImage,
                DiscImageLocator.FindCueForImage(sourceImage),
                Path.Combine(reportRoot, "candidate-enemy-existing-slot.bin"),
                Path.Combine(reportRoot, "candidate-enemy-existing-slot.cue"),
                level,
                nativeEditsPath,
                allowPlanOnlyActorPackageImports: true);
            MobySourcePatch rowPatch = candidatePlan.Patches.Single(patch =>
                string.Equals(patch.Kind, "cross-level-existing-slot-candidate", StringComparison.OrdinalIgnoreCase));
            if (candidatePlan.Patches.Any(patch => string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase)) ||
                rowPatch.TrueIndex != target.TrueIndex ||
                rowPatch.ByteLength != 0x58)
            {
                throw new InvalidOperationException("Self-contained enemy candidate did not remain a one-row, source-count-neutral replacement.");
            }

            byte[] before = ParseHexPreview(rowPatch.BeforeHexPreview);
            byte[] after = ParseHexPreview(rowPatch.AfterHexPreview);
            foreach (int offset in new[] { 0x0C, 0x10, 0x14 })
            {
                if (BitConverter.ToInt32(before, offset) != BitConverter.ToInt32(after, offset))
                    throw new InvalidOperationException($"Enemy slot candidate changed placement coordinate at offset 0x{offset:X2}.");
            }
            if (after[0x50] != donor.Type ||
                after[0x51] != donor.State ||
                after[0x36] != donor.SourceByte36 ||
                after[0x37] != donor.SourceByte37 ||
                after[0x4F] != donor.SourceByte4F ||
                after[0x52] != donor.Flag4A ||
                after[0x53] != donor.Flag4B)
            {
                throw new InvalidOperationException("Self-contained enemy candidate did not preserve the donor identity bytes.");
            }

            await File.WriteAllTextAsync(planPath, JsonSerializer.Serialize(candidatePlan, new JsonSerializerOptions { WriteIndented = true }));
            return (level.DisplayName, target.TrueIndex, donor.SourceLevelName, donor.SourceTrueIndex, planPath);
        }
        finally
        {
            if (File.Exists(nativeEditsPath))
                File.Delete(nativeEditsPath);
        }
    }

    throw new InvalidOperationException("No source-backed level exposed both an eligible enemy target slot and a cross-level self-contained enemy donor.");
}

async Task ReportDarkHollowCrashGuardSmoke()
{
    if (!File.Exists(sourceImage))
        throw new FileNotFoundException("The Dark Hollow crash-guard smoke needs the selected source BIN.", sourceImage);

    LevelDefinition level = catalog.FindByKey("darkhollow")
        ?? throw new InvalidOperationException("Dark Hollow is missing from the level catalog.");
    LevelDefinition donorLevel = catalog.FindByKey("doctorshemp")
        ?? throw new InvalidOperationException("Doctor Shemp is missing from the level catalog.");
    string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", "darkhollow-mobys.json");
    if (!File.Exists(mobyPath))
        throw new FileNotFoundException("The Dark Hollow crash-guard smoke needs the moby cache.", mobyPath);

    List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
    MobyMetadataEnricher.Apply(workspace, level.Key, sourceMobys);
    Moby dragon = sourceMobys.FirstOrDefault(moby =>
        IsNativeDragonActorRecord(moby) &&
        moby.TrueIndex >= 0 &&
        moby.TrueIndex < level.SourceRecordCount)
        ?? throw new InvalidOperationException("Dark Hollow has no mapped native dragon actor for the crash-guard smoke.");
    List<Moby> dragonScene = MobyLinkTraversal.GetLinkedMoveMobys(dragon, sourceMobys)
        .DistinctBy(moby => moby.TrueIndex)
        .OrderBy(moby => moby.TrueIndex)
        .ToList();
    if (dragonScene.Count != 3 ||
        dragonScene.Count(IsNativeDragonActorRecord) != 1 ||
        dragonScene.Count(IsNativeDragonPedestalRecord) != 1 ||
        dragonScene.Count(IsNativeDragonRescueCameraRecord) != 1)
    {
        throw new InvalidOperationException("Dark Hollow crash-guard smoke did not resolve the dragon actor, pedestal, and rescue-camera control triplet.");
    }

    Vector3f dragonDelta = new(96, 64, 16);
    List<Moby> edits = dragonScene.Select(member =>
    {
        Moby moved = CloneMoby(member);
        moved.Position = new Vector3f(
            member.Position.X + dragonDelta.X,
            member.Position.Y + dragonDelta.Y,
            member.Position.Z + dragonDelta.Z);
        moved.PatchStatus = "smoke";
        moved.PatchLead = "Dark Hollow combined dragon/object/environment crash-guard smoke.";
        return moved;
    }).ToList();

    int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
    int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
    (int SourceByte36, string FamilyName)[] families =
    [
        (0x73, "Large Gnorc"),
        (0xC2, "Flame/Charge Chest")
    ];
    Dictionary<string, int> reusableSlots = new(StringComparer.OrdinalIgnoreCase);
    foreach ((int sourceByte36, string familyName) in families)
    {
        Moby donor = sourceMobys.FirstOrDefault(moby => IsPromotedNativeCloneTrueAppendSmokeDonor(moby, level, sourceByte36))
            ?? throw new InvalidOperationException($"Dark Hollow crash-guard smoke could not find a {familyName} donor.");
        int reusableSlotCount = sourceMobys.Count(moby => IsPromotedNativeCloneTrueAppendSmokeCandidate(moby, level, donor));
        reusableSlots[familyName] = reusableSlotCount;
        for (int copyIndex = 0; copyIndex < reusableSlotCount + 3; copyIndex++)
        {
            Moby copy = CopyAsAddedMoby(
                donor,
                nextIndex++,
                nextTrueIndex++,
                $"Crash guard {familyName} copy {copyIndex + 1}",
                copyIndex + 1);
            copy.PatchStatus = "native-clone";
            copy.PatchLead = $"Dark Hollow crash-guard copy from same-level {familyName} donor T{donor.TrueIndex}.";
            copy.Confidence = "same-level-native-clone";
            copy.SourceCloneLevelKey = level.Key;
            copy.SourceCloneLevelName = level.DisplayName;
            copy.SourceCloneTrueIndex = donor.TrueIndex;
            edits.Add(copy);
        }
    }

    string reportRoot = Path.Combine(workspace.RootPath, "_local", "smoke", "darkhollow-crash-guard");
    Directory.CreateDirectory(reportRoot);
    string nativeEditsPath = Path.Combine(reportRoot, "darkhollow-dragon-extra-objects-native-edits.json");
    await MobyEditStore.SaveAsync(nativeEditsPath, edits, "Dark Hollow dragon plus extra actor/chest crash-guard smoke");

    MobySourcePatchResult? objectResult = null;
    NativeEnvironmentGradePatchResult? gradeResult = null;
    try
    {
        objectResult = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
            SourceImagePath: sourceImage,
            SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
            OutputPrefix: Path.Combine(reportRoot, "darkhollow-object-guard-stage"),
            Level: level,
            NativeEditsPath: nativeEditsPath,
            WriteImage: true));
        if (!objectResult.WroteImage)
            throw new InvalidOperationException("Dark Hollow crash-guard object stage did not write a BIN.");
        VerifyPatchBytes(objectResult.OutputImagePath, objectResult.Plan);

        List<MobySourcePatch> autoSlotPatches = objectResult.Plan.Patches
            .Where(patch => string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase))
            .ToList();
        List<MobySourcePatch> appendPatches = objectResult.Plan.Patches
            .Where(patch => string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase))
            .ToList();
        int expectedAutoSlots = reusableSlots.Values.Sum();
        if (autoSlotPatches.Count != expectedAutoSlots || appendPatches.Count != families.Length)
        {
            throw new InvalidOperationException(
                $"Dark Hollow crash guard wrote {autoSlotPatches.Count}/{expectedAutoSlots} reuse rows and {appendPatches.Count}/{families.Length} true-appends.");
        }
        if (objectResult.Plan.SkippedEdits.Count != families.Length * 2 ||
            objectResult.Plan.SkippedEdits.Any(skip => !skip.Contains("safety budget", StringComparison.OrdinalIgnoreCase)))
        {
            throw new InvalidOperationException(
                $"Dark Hollow crash guard did not skip exactly two excess rows per family: {string.Join("; ", objectResult.Plan.SkippedEdits)}");
        }
        MobySourcePatch sourceCountPatch = objectResult.Plan.Patches.Single(patch =>
            string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase));
        int exportedSourceCount = BitConverter.ToInt32(ParseHexPreview(sourceCountPatch.AfterHexPreview), 0);
        if (exportedSourceCount != level.SourceRecordCount + families.Length)
        {
            throw new InvalidOperationException(
                $"Dark Hollow crash guard exported source count {exportedSourceCount}, expected {level.SourceRecordCount + families.Length}.");
        }
        bool movedApproachCamera = objectResult.Plan.Patches.Any(patch =>
            patch.TrueIndex == dragon.TrueIndex &&
            patch.Kind.StartsWith("dragon-rescue-camera-position-", StringComparison.OrdinalIgnoreCase));
        bool movedCinematicCamera = objectResult.Plan.Patches.Any(patch =>
            patch.TrueIndex == dragon.TrueIndex &&
            string.Equals(patch.Kind, "dragon-rescue-cutscene-camera-track", StringComparison.OrdinalIgnoreCase));
        if (!movedApproachCamera || !movedCinematicCamera)
            throw new InvalidOperationException("Dark Hollow crash guard did not retain both dragon approach and cinematic camera movement patches.");

        string analysisPath = WadAnalysisLocator.Find(workspace);
        NativeEnvironmentGradePlan grade = NativeEnvironmentGradePlan.MatchSkySource(donorLevel.Key) with
        {
            GradeActors = true,
            GradeChests = true,
            GradeScenery = true,
            GradeDragons = true
        };
        gradeResult = await NativeEnvironmentGradeExporter.ExportBatchAsync(new NativeEnvironmentGradeBatchPatchRequest(
            SourceImagePath: objectResult.OutputImagePath,
            SourceCuePath: objectResult.OutputCuePath,
            WadAnalysisPath: analysisPath,
            OutputPrefix: Path.Combine(reportRoot, "darkhollow-object-and-environment-guard-stage"),
            Catalog: catalog,
            Edits: [new NativeEnvironmentGradeBatchEdit(level, grade)],
            WriteImage: true));
        if (!gradeResult.WroteImage)
            throw new InvalidOperationException("Dark Hollow crash-guard environment stage did not write a BIN.");
        AssertNoEnvironmentPatchOverlaps(gradeResult.Plan, "Dark Hollow combined crash-guard environment stage");
        AssertObjectAndEnvironmentPatchesDoNotOverlap(objectResult.Plan, gradeResult.Plan);
        VerifyPatchBytes(gradeResult.OutputImagePath, objectResult.Plan);
        VerifyEnvironmentGradePatchHashes(gradeResult.OutputImagePath, gradeResult.Plan);
        AssertDarkHollowTreeGradePlan(
            gradeResult.Plan,
            analysisPath,
            objectResult.OutputImagePath,
            gradeResult.OutputImagePath,
            level,
            "Dark Hollow combined crash-guard environment stage");

        string jsonPath = Path.Combine(reportRoot, "darkhollow-crash-guard-report.json");
        string markdownPath = Path.Combine(reportRoot, "darkhollow-crash-guard-report.md");
        await File.WriteAllTextAsync(jsonPath, JsonSerializer.Serialize(new
        {
            GeneratedAtUtc = DateTimeOffset.UtcNow,
            Level = level.DisplayName,
            DragonTrueIndex = dragon.TrueIndex,
            DragonDelta = new { dragonDelta.X, dragonDelta.Y, dragonDelta.Z },
            ReusableSlots = reusableSlots,
            TrueAppendCount = appendPatches.Count,
            SkippedCrashRiskRows = objectResult.Plan.SkippedEdits.Count,
            ExportedSourceCount = exportedSourceCount,
            ObjectPatchCount = objectResult.Plan.PatchCount,
            EnvironmentPatchCount = gradeResult.Plan.PatchCount,
            MovedApproachCamera = movedApproachCamera,
            MovedCinematicCamera = movedCinematicCamera,
            CrossStageOverlapCount = 0,
            FinalObjectBytesVerified = true,
            FinalEnvironmentHashesVerified = true,
            DisposableBinRetained = false,
            RuntimeBoundary = "This rules out object/dragon/environment write collisions and limits normal actor/chest appends. A Windows diagnostic ZIP from a future runtime crash is still needed to identify emulator-time behavior outside the patched disc bytes."
        }, new JsonSerializerOptions { WriteIndented = true }));
        await File.WriteAllTextAsync(markdownPath, $"""
            # Dark Hollow Crash Guard

            - Moved dragon: T{dragon.TrueIndex}; approach and cinematic camera data both preserved
            - Reused actor/chest slots: {autoSlotPatches.Count}
            - Release-limited true-appends: {appendPatches.Count} total, one per tested family
            - Crash-risk excess rows skipped: {objectResult.Plan.SkippedEdits.Count}
            - Final source count: {level.SourceRecordCount} -> {exportedSourceCount}
            - Object/dragon patches: {objectResult.Plan.PatchCount}
            - Environment/object-lighting patches: {gradeResult.Plan.PatchCount}
            - Cross-stage overlaps: 0
            - Final BIN readback: all object, dragon-camera, terrain, scenery, and environment hashes verified
            - Disposable BIN/CUE: removed after verification

            This regression rules out static patch collisions and export-order corruption for the combined workflow. It cannot reproduce emulator-time actor behavior without the Windows output and diagnostic bundle from the crashing session.
            """);

        Console.WriteLine(
            $"Dark Hollow combined crash guard: {autoSlotPatches.Count} reused rows, {appendPatches.Count} release-limited append(s), {objectResult.Plan.SkippedEdits.Count} crash-risk rows skipped; dragon cameras and {gradeResult.Plan.PatchCount} environment patches survived final readback.");
        Console.WriteLine($"JSON: {jsonPath}");
        Console.WriteLine($"Markdown: {markdownPath}");
    }
    finally
    {
        if (gradeResult != null)
        {
            if (File.Exists(gradeResult.OutputImagePath))
                File.Delete(gradeResult.OutputImagePath);
            if (File.Exists(gradeResult.OutputCuePath))
                File.Delete(gradeResult.OutputCuePath);
            if (File.Exists(gradeResult.OutputPlanPath))
                File.Delete(gradeResult.OutputPlanPath);
        }
        if (objectResult != null)
        {
            if (File.Exists(objectResult.OutputImagePath))
                File.Delete(objectResult.OutputImagePath);
            if (File.Exists(objectResult.OutputCuePath))
                File.Delete(objectResult.OutputCuePath);
            if (File.Exists(objectResult.OutputPlanPath))
                File.Delete(objectResult.OutputPlanPath);
        }
    }
}

void AssertObjectAndEnvironmentPatchesDoNotOverlap(
    MobySourcePatchPlan objectPlan,
    NativeEnvironmentGradePatchPlan environmentPlan)
{
    var objectIntervals = objectPlan.Patches
        .Select(patch =>
        {
            byte[] bytes = ParseHexPreview(patch.AfterHexPreview);
            bool executable = TryParseExePatchOffset(patch.WadRelativeOffset, out long executableOffset);
            bool wad = TryParseWadPatchOffset(patch.WadRelativeOffset, out long wadOffset);
            return new
            {
                Valid = executable || wad,
                AddressSpace = executable ? "exe" : "wad",
                Start = executable ? executableOffset : wadOffset,
                End = checked((executable ? executableOffset : wadOffset) + bytes.Length),
                Label = $"{patch.MobyLabel}/{patch.Kind}"
            };
        })
        .Where(interval => interval.Valid)
        .ToArray();
    var environmentIntervals = environmentPlan.Patches
        .Select(patch =>
        {
            bool executable = patch.WadOffset.StartsWith("exe:", StringComparison.OrdinalIgnoreCase);
            long start = executable
                ? ParseFlexibleLong(patch.WadOffset[4..])
                : ParseFlexibleLong(patch.WadOffset);
            return new
            {
                AddressSpace = executable ? "exe" : "wad",
                Start = start,
                End = checked(start + patch.ByteLength),
                patch.Label
            };
        })
        .ToArray();

    foreach (var objectInterval in objectIntervals)
    {
        var overlap = environmentIntervals.FirstOrDefault(environmentInterval =>
            string.Equals(environmentInterval.AddressSpace, objectInterval.AddressSpace, StringComparison.OrdinalIgnoreCase) &&
            objectInterval.Start < environmentInterval.End &&
            environmentInterval.Start < objectInterval.End);
        if (overlap != null)
        {
            throw new InvalidOperationException(
                $"Dark Hollow combined crash guard found an {objectInterval.AddressSpace} overlap between object patch '{objectInterval.Label}' and environment patch '{overlap.Label}'.");
        }
    }
}

async Task ReportGuardedNativeCloneTrueAppend(string levelKey, int sourceByte36, int sourceByte37, int flag4B, string familyName)
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine($"{levelKey} guarded {familyName} append: source disc not found; skipping.");
        return;
    }

    LevelDefinition? level = catalog.FindByKey(levelKey);
    if (level == null || !level.HasSourceTable)
    {
        Console.WriteLine($"{levelKey} guarded {familyName} append: source table is not mapped; skipping.");
        return;
    }

    string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{levelKey}-mobys.json");
    if (!File.Exists(mobyPath))
    {
        Console.WriteLine($"{levelKey} guarded {familyName} append: moby cache not found; skipping.");
        return;
    }

    List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
    Moby? donor = sourceMobys.FirstOrDefault(moby =>
        moby.TrueIndex >= 0 &&
        moby.TrueIndex < level.SourceRecordCount &&
        moby.Type == 0x20 &&
        moby.SourceByte36 == sourceByte36 &&
        moby.SourceByte37 == sourceByte37 &&
        moby.SourceByte4F == 0x00 &&
        moby.Flag4A == 0x10 &&
        moby.Flag4B == flag4B);
    if (donor == null)
    {
        Console.WriteLine($"{level.DisplayName} guarded {familyName} append: donor object not found; skipping.");
        return;
    }

    int reusableSlotCount = sourceMobys.Count(moby => IsPromotedNativeCloneTrueAppendSmokeCandidate(moby, level, donor));
    int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
    int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
    List<Moby> addedMobys = new();
    for (int i = 0; i <= reusableSlotCount; i++)
    {
        Moby added = CopyAsAddedMoby(donor, nextIndex + i, nextTrueIndex + i, $"Guarded {familyName} clone {i + 1}", 0);
        added.PatchStatus = "native-clone";
        added.PatchLead = $"Guarded true-append smoke from same-level {familyName} donor T{donor.TrueIndex}.";
        added.Confidence = "same-level-native-clone";
        added.Evidence = $"Copied from same-level {familyName} donor T{donor.TrueIndex}; live testing has not promoted true-add appends for this family.";
        added.SourceCloneLevelKey = level.Key;
        added.SourceCloneLevelName = level.DisplayName;
        added.SourceCloneTrueIndex = donor.TrueIndex;
        addedMobys.Add(added);
    }

    string familySlug = familyName.ToLowerInvariant().Replace("/", "-").Replace(" ", "-");
    string path = Path.Combine(workspace.RootPath, "_local", "smoke", $"{levelKey}-guarded-{familySlug}-append-native-edits.json");
    await MobyEditStore.SaveAsync(path, addedMobys, $"{level.DisplayName} guarded {familyName} true-append");
    MobySourcePatchResult exportResult = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
        SourceImagePath: sourceImage,
        SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
        OutputPrefix: Path.Combine(workspace.RootPath, "_local", "objects", $"{levelKey}-guarded-{familySlug}-append"),
        Level: level,
        NativeEditsPath: path,
        WriteImage: true));
    MobySourcePatchPlan plan = exportResult.Plan;
    if (!exportResult.WroteImage)
        throw new InvalidOperationException($"{level.DisplayName} guarded {familyName} append did not write a BIN for the reusable slot clones.");
    VerifyPatchBytes(exportResult.OutputImagePath, plan);

    List<MobySourcePatch> slotPatches = plan.Patches
        .Where(patch => string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase))
        .ToList();
    if (slotPatches.Count != reusableSlotCount)
        throw new InvalidOperationException($"{level.DisplayName} guarded {familyName} append wrote {slotPatches.Count} slot clone patch(es), expected {reusableSlotCount} before guarding the true-add.");
    if (plan.Patches.Any(patch =>
        string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase) ||
        string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase)))
    {
        throw new InvalidOperationException($"{level.DisplayName} guarded {familyName} append unexpectedly wrote true-append/source-count patches.");
    }
    if (!plan.SkippedEdits.Any(skip => skip.Contains("no matching source slot", StringComparison.OrdinalIgnoreCase) ||
        skip.Contains("true-adds are kept saved", StringComparison.OrdinalIgnoreCase)))
    {
        throw new InvalidOperationException($"{level.DisplayName} guarded {familyName} append did not report the exhausted-slot guard.");
    }

    Console.WriteLine($"{level.DisplayName} guarded {familyName} append: reused {slotPatches.Count} slot(s), true-add stayed guarded");
}

void ReportLifeChestFixupScan(string imagePath)
{
    const int ArtisansRuntimeChunkOffset = 0x1C9800;
    LevelDefinition level = catalog.FindByKey("artisans")
        ?? throw new InvalidOperationException("Artisans was not found in the level catalog.");
    long tableWadOffset = ParseFlexibleLong(level.SourceTableWadOffset);
    long tableRelativeOffset = ParseFlexibleLong(level.SourceTableRelativeOffset);
    long entryWadOffset = tableWadOffset - tableRelativeOffset;
    int scanLength = checked((int)(tableRelativeOffset + ((level.SourceRecordCount + 16L) * 0x58L) + 0x4000L));

    SourceDiscLayout layout = DetectSourceDiscLayout(imagePath);
    using FileStream stream = File.OpenRead(imagePath);
    byte[] entryBytes = ReadSourceWadBytes(stream, layout, entryWadOffset, scanLength);

    Console.WriteLine($"Life Chest relocation scan: {level.DisplayName}");
    Console.WriteLine($"Entry WAD=0x{entryWadOffset:X}, table relative=0x{tableRelativeOffset:X}, rows={level.SourceRecordCount}");
    IReadOnlyList<int> sourceCountMatches = FindUInt32Offsets(entryBytes, (uint)level.SourceRecordCount);
    Console.WriteLine($"32-bit source-count matches: {FormatScanOffsets(sourceCountMatches)}");
    foreach (int match in sourceCountMatches)
    {
        int contextOffset = Math.Max(0, match - 0x20);
        int contextLength = Math.Min(0x44, entryBytes.Length - contextOffset);
        Console.WriteLine($"  count@0x{match:X}: {Convert.ToHexString(entryBytes, contextOffset, contextLength)}");
    }
    foreach (int row in new[] { 0, 1, 93, 94, 95, 172, 173, 174, 175, 176 })
    {
        int recordOffset = checked((int)(tableRelativeOffset + (row * 0x58L)));
        uint specialOffset = recordOffset + 4 <= entryBytes.Length
            ? BinaryPrimitives.ReadUInt32LittleEndian(entryBytes.AsSpan(recordOffset, 4))
            : 0;
        IReadOnlyList<int> relativeFieldRefs = FindUInt32Offsets(entryBytes, checked((uint)recordOffset));
        uint chunkFieldOffset = recordOffset >= ArtisansRuntimeChunkOffset
            ? checked((uint)(recordOffset - ArtisansRuntimeChunkOffset))
            : uint.MaxValue;
        IReadOnlyList<int> chunkFieldRefs = chunkFieldOffset != uint.MaxValue
            ? FindUInt32Offsets(entryBytes, chunkFieldOffset)
            : [];
        IReadOnlyList<int> chunkFieldRefs16 = chunkFieldOffset <= ushort.MaxValue
            ? FindUInt16Offsets(entryBytes, checked((ushort)chunkFieldOffset))
            : [];
        IReadOnlyList<int> absoluteFieldRefs = FindUInt32Offsets(entryBytes, checked((uint)(entryWadOffset + recordOffset)));
        IReadOnlyList<int> specialRefs = specialOffset > 0
            ? FindUInt32Offsets(entryBytes, specialOffset)
            : [];
        Console.WriteLine(
            $"T{row}: record+0=0x{recordOffset:X}, special=0x{specialOffset:X8}, " +
            $"record-ref={FormatScanOffsets(relativeFieldRefs)}, chunk+0=0x{chunkFieldOffset:X}, " +
            $"chunk-ref={FormatScanOffsets(chunkFieldRefs)}, chunk-ref16={FormatScanOffsets(chunkFieldRefs16)}, " +
            $"wad-ref={FormatScanOffsets(absoluteFieldRefs)}, " +
            $"special-ref={FormatScanOffsets(specialRefs)}");
    }

    Console.WriteLine("Bytes before source count/table:");
    int headerOffset = checked((int)tableRelativeOffset - 0x40);
    for (int offset = headerOffset; offset < headerOffset + 0x40; offset += 0x10)
        Console.WriteLine($"  0x{offset:X}: {Convert.ToHexString(entryBytes, offset, 0x10)}");
}

IReadOnlyList<int> FindUInt32Offsets(byte[] bytes, uint value)
{
    List<int> matches = [];
    for (int offset = 0; offset + 4 <= bytes.Length; offset += 4)
    {
        if (BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(offset, 4)) == value)
            matches.Add(offset);
    }
    return matches;
}

IReadOnlyList<int> FindUInt16Offsets(byte[] bytes, ushort value)
{
    List<int> matches = [];
    for (int offset = 0; offset + 2 <= bytes.Length; offset += 2)
    {
        if (BinaryPrimitives.ReadUInt16LittleEndian(bytes.AsSpan(offset, 2)) == value)
            matches.Add(offset);
    }
    return matches;
}

string FormatScanOffsets(IReadOnlyList<int> offsets)
{
    if (offsets.Count == 0)
        return "-";
    string shown = string.Join(",", offsets.Take(8).Select(offset => $"0x{offset:X}"));
    return offsets.Count <= 8 ? shown : $"{shown},... ({offsets.Count})";
}

async Task ReportAllNativeLifeChestMultiReleasePlans()
{
    if (!File.Exists(sourceImage))
        throw new FileNotFoundException("All-level Life Chest release regression needs the selected source BIN.", sourceImage);

    HashSet<string> supportedLevelKeys = LifeChestRuntimeLayout.SupportedLevelKeys
        .Select(LevelCatalog.NormalizeKey)
        .ToHashSet(StringComparer.OrdinalIgnoreCase);
    List<LifeChestReleaseLevelProof> proofs = new();
    SourceDiscLayout sourceLayout = DetectSourceDiscLayout(sourceImage);
    using FileStream sourceStream = File.OpenRead(sourceImage);
    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke", "all-level-life-chest-release");
    Directory.CreateDirectory(outDir);
    ReportLifeChestRuntimeBaseDerivation(sourceStream, sourceLayout, supportedLevelKeys, outDir);

    foreach (LevelDefinition level in catalog.Levels.Where(level => supportedLevelKeys.Contains(LevelCatalog.NormalizeKey(level.Key))).OrderBy(level => level.LevelId))
    {
        string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-mobys.json");
        List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
        Moby donor = sourceMobys.FirstOrDefault(moby =>
            moby.TrueIndex >= 0 &&
            moby.TrueIndex < level.SourceRecordCount &&
            moby.Type == 0x20 &&
            moby.SourceByte36 == 0xA5 &&
            moby.SourceByte37 == 0x01 &&
            moby.SourceByte4F == 0x00 &&
            moby.Flag4A == 0x10 &&
            moby.Flag4B == 0x0E) ??
            throw new InvalidOperationException($"{level.DisplayName} is promoted for Life Chest copies but has no native Life Chest donor.");

        int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
        List<Moby> copies = new();
        for (int i = 0; i < 3; i++)
        {
            Moby copy = CopyAsAddedMoby(donor, nextIndex + i, level.SourceRecordCount + i, $"{level.DisplayName} Life Chest release copy {i + 1}", 0);
            copy.Position = new Vector3f(donor.Position.X + ((i + 1) * 8f), donor.Position.Y, donor.Position.Z);
            copy.PatchStatus = "native-clone";
            copy.PatchLead = $"Pasted from same-level donor T{donor.TrueIndex}.";
            copy.Confidence = "same-level-native-clone-private-runtime";
            copy.Evidence = "All-level private Life Chest runtime allocation regression.";
            copy.SourceCloneLevelKey = level.Key;
            copy.SourceCloneLevelName = level.DisplayName;
            copy.SourceCloneTrueIndex = donor.TrueIndex;
            copies.Add(copy);
        }

        string editsPath = Path.Combine(outDir, $"{level.Key}-multi-life-chest-native-edits.json");
        await MobyEditStore.SaveAsync(editsPath, copies, $"{level.DisplayName} normal-release multi-Life-Chest regression");
        string outputPrefix = Path.Combine(outDir, $"{level.Key}-multi-life-chest");
        MobySourcePatchResult result = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
            SourceImagePath: sourceImage,
            SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
            OutputPrefix: outputPrefix,
            Level: level,
            NativeEditsPath: editsPath,
            WriteImage: true));
        VerifyAndDeleteLifeChestOutputImage(result, level);

        int[] expectedAppendRows = Enumerable.Range(level.SourceRecordCount, 3).ToArray();
        List<MobySourcePatch> appends = result.Plan.Patches
            .Where(patch => string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase))
            .OrderBy(patch => patch.TrueIndex)
            .ToList();
        List<MobySourcePatch> specialClones = result.Plan.Patches
            .Where(patch => string.Equals(patch.Kind, "moby-special-data-clone", StringComparison.OrdinalIgnoreCase))
            .OrderBy(patch => patch.TrueIndex)
            .ToList();
        int autoSlotCount = result.Plan.Patches.Count(patch =>
            string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase));
        if (result.Plan.SkippedEdits.Count != 0 ||
            autoSlotCount != 0 ||
            result.Plan.Patches.Any(patch => patch.TrueIndex == donor.TrueIndex) ||
            !appends.Select(patch => patch.TrueIndex).SequenceEqual(expectedAppendRows) ||
            !specialClones.Select(patch => patch.TrueIndex).SequenceEqual(expectedAppendRows))
        {
            throw new InvalidOperationException(
                $"{level.DisplayName} multi-Life-Chest release plan was unsafe: append={appends.Count}, special={specialClones.Count}, " +
                $"auto-slot={autoSlotCount}, donor-patches={result.Plan.Patches.Count(patch => patch.TrueIndex == donor.TrueIndex)}, " +
                $"skipped={result.Plan.SkippedEdits.Count}.");
        }

        if (!LifeChestRuntimeLayout.TryGetRuntimeBase(level.Key, out uint runtimeBase))
            throw new InvalidOperationException($"{level.DisplayName} lost its promoted Life Chest runtime base.");
        LifeChestSceneSourceProof scene = ReadLifeChestSceneSourceProof(sourceStream, sourceLayout, level);
        long tableWadOffset = ParseFlexibleLong(level.SourceTableWadOffset);
        int catalogPrefixRows = ReadLifeChestCatalogPrefixRows(sourceStream, sourceLayout, level, tableWadOffset);
        byte[] donorRecord = ReadSourceWadBytes(
            sourceStream,
            sourceLayout,
            tableWadOffset + ((long)donor.TrueIndex * MobyLoader.RuntimeRecordStride),
            MobyLoader.RuntimeRecordStride);
        uint donorSourceOffset = BinaryPrimitives.ReadUInt32LittleEndian(donorRecord.AsSpan(0, 4));

        List<uint> sourceOffsets = new();
        List<uint> pointers = new();
        for (int i = 0; i < appends.Count; i++)
        {
            MobySourcePatch append = appends[i];
            MobySourcePatch special = specialClones[i];
            long specialWadOffset = ParseFlexibleLong(special.WadRelativeOffset);
            long sourceOffsetLong = specialWadOffset - scene.WadBaseOffset;
            if (sourceOffsetLong <= 0 || sourceOffsetLong + special.ByteLength > scene.ByteLength)
                throw new InvalidOperationException($"{level.DisplayName} T{append.TrueIndex} private Life Chest block is outside the level-scene data.");

            uint sourceOffset = checked((uint)sourceOffsetLong);
            uint pointer = BinaryPrimitives.ReadUInt32LittleEndian(ParseHexPreview(append.AfterHexPreview).AsSpan(0, 4));
            uint expectedPointer = checked(runtimeBase + sourceOffset);
            if (pointer != expectedPointer)
            {
                throw new InvalidOperationException(
                    $"{level.DisplayName} T{append.TrueIndex} pointer was 0x{pointer:X8}; expected 0x{expectedPointer:X8} from base 0x{runtimeBase:X8} + 0x{sourceOffset:X}.");
            }

            byte[] expectedSpecialBytes = ReadSourceWadBytes(
                sourceStream,
                sourceLayout,
                scene.WadBaseOffset + donorSourceOffset,
                special.ByteLength);
            if (!ParseHexPreview(special.AfterHexPreview).SequenceEqual(expectedSpecialBytes))
                throw new InvalidOperationException($"{level.DisplayName} T{append.TrueIndex} did not clone the donor's actual level-scene Life Chest data.");

            sourceOffsets.Add(sourceOffset);
            pointers.Add(pointer);
        }

        if (sourceOffsets.Distinct().Count() != 3 || pointers.Distinct().Count() != 3)
            throw new InvalidOperationException($"{level.DisplayName} Life Chest copies did not receive three independent private blocks.");

        MobySourcePatch countPatch = result.Plan.Patches.Single(patch =>
            string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase));
        int patchedCount = BinaryPrimitives.ReadInt32LittleEndian(ParseHexPreview(countPatch.AfterHexPreview).AsSpan(0, 4));
        int expectedPatchedCount = level.SourceRecordCount + 3 - catalogPrefixRows;
        if (patchedCount != expectedPatchedCount)
            throw new InvalidOperationException($"{level.DisplayName} source count became {patchedCount}; expected {expectedPatchedCount}.");

        proofs.Add(new LifeChestReleaseLevelProof(
            level.Key,
            level.DisplayName,
            donor.TrueIndex,
            level.SourceRecordCount,
            catalogPrefixRows,
            runtimeBase,
            scene.WadBaseOffset,
            scene.ByteLength,
            expectedAppendRows,
            sourceOffsets,
            pointers));
    }

    HashSet<string> provenLevelKeys = proofs.Select(proof => LevelCatalog.NormalizeKey(proof.LevelKey)).ToHashSet(StringComparer.OrdinalIgnoreCase);
    if (!provenLevelKeys.SetEquals(supportedLevelKeys))
    {
        string missing = string.Join(", ", supportedLevelKeys.Except(provenLevelKeys).Order(StringComparer.OrdinalIgnoreCase));
        string extra = string.Join(", ", provenLevelKeys.Except(supportedLevelKeys).Order(StringComparer.OrdinalIgnoreCase));
        throw new InvalidOperationException($"All-level Life Chest proof coverage mismatch; missing={missing}; extra={extra}.");
    }

    string reportPath = Path.Combine(outDir, "all-level-life-chest-release-proof.json");
    File.WriteAllText(reportPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now,
        nativeLifeChestLevelCount = proofs.Count,
        copiesPerLevel = 3,
        proofs
    }, new JsonSerializerOptions { WriteIndented = true }));
    Console.WriteLine(
        $"All-level multi-Life-Chest release: {proofs.Count} native level(s), {proofs.Count * 3} independent append(s), " +
        $"all original donors preserved, all output BIN bytes verified; report={reportPath}");
}

void VerifyAndDeleteLifeChestOutputImage(MobySourcePatchResult result, LevelDefinition level)
{
    try
    {
        if (!result.WroteImage || !File.Exists(result.OutputImagePath) || !File.Exists(result.OutputCuePath))
            throw new InvalidOperationException($"{level.DisplayName} all-level Life Chest regression did not write its disposable BIN/CUE.");

        SourceDiscLayout outputLayout = DetectSourceDiscLayout(result.OutputImagePath);
        using FileStream outputStream = File.OpenRead(result.OutputImagePath);
        foreach (MobySourcePatch patch in result.Plan.Patches)
        {
            if (!patch.WadRelativeOffset.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException($"{level.DisplayName} Life Chest patch {patch.Label} did not expose a WAD-relative output offset.");

            long wadOffset = ParseFlexibleLong(patch.WadRelativeOffset);
            byte[] expected = ParseHexPreview(patch.AfterHexPreview);
            byte[] actual = ReadSourceWadBytes(outputStream, outputLayout, wadOffset, expected.Length);
            if (!actual.SequenceEqual(expected))
                throw new InvalidOperationException($"{level.DisplayName} output BIN bytes differ for Life Chest patch {patch.Label} at {patch.WadRelativeOffset}.");
        }
    }
    finally
    {
        if (File.Exists(result.OutputImagePath))
            File.Delete(result.OutputImagePath);
        if (File.Exists(result.OutputCuePath))
            File.Delete(result.OutputCuePath);
    }
}

void ReportPortalSourceLayout(string imagePath, string levelKey)
{
    LevelDefinition level = catalog.FindByKey(levelKey)
        ?? throw new InvalidOperationException($"Level {levelKey} is not present in the catalog.");
    PortalSourceLevelData data = PortalSourceDataLocator.Locate(imagePath, level);
    List<object> portalRows = data.Portals
        .Select(portal => (object)new
        {
            portal.Index,
            portal.DestinationLevelId,
            portal.PathMobyIndex,
            portal.SourcePathMobyTrueIndex,
            portal.WorldSectorIndex,
            portal.PointCount,
            normal = new { x = portal.NormalX, y = portal.NormalY, z = portal.NormalZ },
            center = new { x = portal.CenterX, y = portal.CenterY, z = portal.CenterZ },
            wadOffset = $"0x{portal.WadOffset:X}",
            path = new
            {
                propsWadOffset = $"0x{portal.Path.PropsWadOffset:X}",
                pathWadOffset = $"0x{portal.Path.PathWadOffset:X}",
                portal.Path.NodeCount,
                portal.Path.CurrentNode,
                portal.Path.Reversed,
                nodes = portal.Path.Nodes.Select(node => new
                {
                    node.Index,
                    node.X,
                    node.Y,
                    node.Z,
                    wadOffset = $"0x{node.WadOffset:X}"
                })
            },
            points = portal.Points.Select(point => new
            {
                point.X,
                point.Y,
                point.Z,
                wadOffset = $"0x{point.WadOffset:X}"
            })
        })
        .ToList();
    List<object> surfaceRows = data.SpecialSurfaces
        .Where(surface => surface.Type == 6)
        .Select(surface => (object)new
        {
            surface.Index,
            surface.Type,
            surface.DestinationLevelId,
            surface.PortalIndex,
            wadOffset = $"0x{surface.WadOffset:X}"
        })
        .ToList();
    List<object> triggerRows = data.TriggerTriangles
        .Select(triangle => (object)new
        {
            triangle.TriangleIndex,
            triangle.SurfaceIndex,
            triangle.DestinationLevelId,
            triangle.PortalIndex,
            flagByte = $"0x{triangle.FlagByte:X2}",
            wadOffset = $"0x{triangle.WadOffset:X}",
            p1 = new { triangle.P1.X, triangle.P1.Y, triangle.P1.Z },
            p2 = new { triangle.P2.X, triangle.P2.Y, triangle.P2.Z },
            p3 = new { triangle.P3.X, triangle.P3.Y, triangle.P3.Z }
        })
        .ToList();

    string reportDir = Path.Combine(workspace.RootPath, "_local", "research", "portal-source-layout");
    Directory.CreateDirectory(reportDir);
    string reportPath = Path.Combine(reportDir, $"{level.Key}-portal-source-layout.json");
    File.WriteAllText(reportPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now,
        sourceImage = imagePath,
        data.LevelKey,
        data.LevelName,
        levelDataWadOffset = $"0x{data.LevelDataWadOffset:X}",
        entryDataWadOffset = $"0x{data.EntryDataWadOffset:X}",
        data.EntryDataByteLength,
        specialSurfaceComponentWadOffset = $"0x{data.SpecialSurfaceComponentWadOffset:X}",
        collisionComponentWadOffset = $"0x{data.CollisionComponentWadOffset:X}",
        portalTableWadOffset = $"0x{data.PortalTableWadOffset:X}",
        data.SourceMobyIndexBias,
        collision = new
        {
            data.Collision.TriangleCount,
            data.Collision.FlagCount,
            blockTreeWadOffset = $"0x{data.Collision.BlockTreeWadOffset:X}",
            data.Collision.BlockTreeByteCapacity,
            blocksWadOffset = $"0x{data.Collision.BlocksWadOffset:X}",
            data.Collision.BlocksByteCapacity,
            triangleTableWadOffset = $"0x{data.Collision.TriangleTableWadOffset:X}",
            flagsWadOffset = $"0x{data.Collision.FlagsWadOffset:X}"
        },
        portals = portalRows,
        portalSurfaces = surfaceRows,
        portalTriggerTriangles = triggerRows
    }, new JsonSerializerOptions { WriteIndented = true }));

    Console.WriteLine($"Portal source layout: {level.DisplayName} has {portalRows.Count} portal record(s), {surfaceRows.Count} portal surface(s), and {triggerRows.Count} flagged collision triangle(s).");
    Console.WriteLine($"  collision: {data.Collision.TriangleCount} triangles, tree capacity=0x{data.Collision.BlockTreeByteCapacity:X}, block capacity=0x{data.Collision.BlocksByteCapacity:X}");
    foreach (PortalSourceRecord portal in data.Portals)
    {
        Console.WriteLine(
            $"  portal {portal.Index}: destination={portal.DestinationLevelId}, runtimePath={portal.PathMobyIndex}, sourcePath=T{portal.SourcePathMobyTrueIndex}, center=({portal.CenterX},{portal.CenterY},{portal.CenterZ}), points={portal.Points.Count}, transitionNodes={portal.Path.Nodes.Count}, WAD=0x{portal.WadOffset:X}");
    }
    string cachePath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-mobys.json");
    if (File.Exists(cachePath))
    {
        List<Moby> mobys = MobyLoader.LoadCached(cachePath).ToList();
        MobyMetadataEnricher.Apply(workspace, level.Key, mobys);
        foreach (PortalSourceRecord portal in data.Portals)
        {
            Moby? path = mobys.FirstOrDefault(moby => moby.TrueIndex == portal.SourcePathMobyTrueIndex);
            Vector3f portalCenter = new(portal.CenterX / 16f, portal.CenterY / 16f, portal.CenterZ / 16f);
            Moby? nearestLettering = mobys
                .Where(moby => !moby.IsRemoved && moby.Type == 0x00 && moby.SourceByte36 == 0x01 && moby.Flag4A == 0x10 && moby.Flag4B == 0xFF)
                .OrderBy(moby => DistanceSquared(moby.Position, portalCenter))
                .FirstOrDefault();
            Moby? nearestCompanion = mobys
                .Where(moby => !moby.IsRemoved && moby.Type == 0x00 && moby.SourceByte36 == 0x1E && moby.Flag4A == 0x10 && moby.Flag4B == 0xFF)
                .OrderBy(moby => DistanceSquared(moby.Position, portalCenter))
                .FirstOrDefault();
            MobyLink? editLink = path?.Links.FirstOrDefault(link =>
                string.Equals(link.Kind, "portal controls", StringComparison.OrdinalIgnoreCase) && link.LinkedMove);
            HomeworldPortalControlDefinition expected = HomeworldPortalControlCatalog.ForLevel(level.Key)
                .Single(definition => definition.DestinationLevelId == portal.DestinationLevelId);
            int[] expectedIndexes = expected.TrueIndexes.OrderBy(index => index).ToArray();
            int[] linkedIndexes = editLink?.TrueIndexes.OrderBy(index => index).ToArray() ?? [];
            if (portal.SourcePathMobyTrueIndex != expected.PathTrueIndex ||
                nearestLettering?.TrueIndex != expected.LetteringTrueIndex ||
                nearestCompanion?.TrueIndex != expected.CompanionTrueIndex ||
                !linkedIndexes.SequenceEqual(expectedIndexes))
            {
                throw new InvalidOperationException(
                    $"{level.DisplayName} destination {portal.DestinationLevelId} portal mapping differs from its native source layout.");
            }
            Console.WriteLine(
                $"    editor destination {portal.DestinationLevelId}: path=T{portal.SourcePathMobyTrueIndex}, lettering=T{nearestLettering?.TrueIndex} ({Math.Sqrt(DistanceSquared(nearestLettering?.Position ?? portalCenter, portalCenter)):0.#}u), companion=T{nearestCompanion?.TrueIndex} ({Math.Sqrt(DistanceSquared(nearestCompanion?.Position ?? portalCenter, portalCenter)):0.#}u), link={(editLink == null ? "missing" : string.Join("/", editLink.TrueIndexes.Select(index => $"T{index}")))}");
        }
    }
    foreach (IGrouping<int, PortalTriggerTriangle> group in data.TriggerTriangles.GroupBy(triangle => triangle.DestinationLevelId).OrderBy(group => group.Key))
        Console.WriteLine($"  destination {group.Key}: {group.Count()} trigger triangle(s)");
    Console.WriteLine($"Portal source report: {reportPath}");
}

void ReportNativeTerrainSurfaceSourceCatalog(string imagePath)
{
    if (!File.Exists(imagePath))
        throw new FileNotFoundException("The native terrain-surface catalog needs the selected Spyro BIN.", imagePath);

    string reportRoot = Path.Combine(workspace.RootPath, "_local", "research", "native-terrain-surfaces");
    Directory.CreateDirectory(reportRoot);
    List<NativeTerrainSurfaceLevelRow> levelRows = [];
    foreach (LevelDefinition level in catalog.Levels)
    {
        NativeTerrainSurfaceSourceData source = PortalSourceDataLocator.LocateTerrainSurfaces(imagePath, level);
        string overlayPath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-runtime-scene-editor-overlay.json");
        GeometryCandidate? geometry = File.Exists(overlayPath)
            ? GeometryOverlayLoader.LoadFirstCandidate(overlayPath)
            : null;
        if (geometry != null)
            TerrainMaterialClassifier.Apply(level.Key, workspace.RootPath, geometry);

        Dictionary<string, List<TerrainPolygon>> visualFacesByTriangle = new(StringComparer.Ordinal);
        if (geometry != null)
        {
            foreach (TerrainPolygon face in geometry.Polygons.Where(face =>
                !face.IsTerrainRemoved &&
                face.TextureId >= 0 &&
                face.Points.Count >= 3 &&
                face.ZValues.Length >= face.Points.Count))
            {
                for (int i = 1; i < face.Points.Count - 1; i++)
                {
                    string key = VisualTriangleKey(face, 0, i, i + 1);
                    if (!visualFacesByTriangle.TryGetValue(key, out List<TerrainPolygon>? faceMatches))
                    {
                        faceMatches = [];
                        visualFacesByTriangle[key] = faceMatches;
                    }
                    faceMatches.Add(face);
                }
            }
        }

        List<(NativeCollisionSurfaceTriangle Triangle, TerrainPolygon Face)> matches = [];
        foreach (NativeCollisionSurfaceTriangle triangle in source.CollisionSurfaceTriangles)
        {
            string key = string.Join("|", new[]
                {
                    CollisionPointKey(triangle.P1.X, triangle.P1.Y, triangle.P1.Z),
                    CollisionPointKey(triangle.P2.X, triangle.P2.Y, triangle.P2.Z),
                    CollisionPointKey(triangle.P3.X, triangle.P3.Y, triangle.P3.Z)
                }
                .OrderBy(value => value, StringComparer.Ordinal));
            if (!visualFacesByTriangle.TryGetValue(key, out List<TerrainPolygon>? faces))
                continue;
            foreach (TerrainPolygon face in faces)
                matches.Add((triangle, face));
        }

        NativeSpecialSurfaceUsageRow[] specialRows = source.SpecialSurfaces
            .Select(surface => new NativeSpecialSurfaceUsageRow(
                surface.Index,
                surface.Type,
                surface.Param1,
                surface.Param2,
                source.CollisionSurfaceTriangles.Count(triangle => triangle.SurfaceIndex == surface.Index),
                matches.Count(match => match.Triangle.SurfaceIndex == surface.Index),
                NativeSurfaceTypeLabel(surface.Type, surface.Param1, surface.Param2)))
            .ToArray();

        NativeTextureSurfaceRow[] textureRows = matches
            .GroupBy(match => new
            {
                match.Face.TextureId,
                HighFlags = match.Triangle.FlagByte & 0xC0,
                match.Triangle.SurfaceType,
                match.Triangle.Param1,
                match.Triangle.Param2
            })
            .Select(group =>
            {
                TerrainPolygon representative = group
                    .Select(match => match.Face)
                    .OrderByDescending(face => face.Points.Count)
                    .ThenBy(face => face.RuntimeKey, StringComparer.OrdinalIgnoreCase)
                    .First();
                int surfaceType = group.Key.SurfaceType;
                return new NativeTextureSurfaceRow(
                    group.Key.TextureId,
                    surfaceType,
                    group.Key.Param1,
                    group.Key.Param2,
                    group.Key.HighFlags,
                    group.Select(match => match.Triangle.TriangleIndex).Distinct().Count(),
                    group.Select(match => match.Face.RuntimeKey).Distinct(StringComparer.OrdinalIgnoreCase).Count(),
                    representative.RuntimeKey,
                    TerrainMaterialClassifier.NormalizeSurfaceName(representative.Surface),
                    NativeSurfaceTypeLabel(surfaceType, group.Key.Param1, group.Key.Param2));
            })
            .OrderBy(row => row.TextureId)
            .ThenBy(row => row.SurfaceType)
            .ThenBy(row => row.Param1)
            .ThenBy(row => row.Param2)
            .ToArray();

        levelRows.Add(new NativeTerrainSurfaceLevelRow(
            level.Key,
            level.DisplayName,
            source.Collision.TriangleCount,
            source.Collision.FlagCount,
            source.SpecialSurfaces.Count,
            source.CollisionSurfaceTriangles.Count(triangle => triangle.HasSpecialSurface),
            matches.Select(match => match.Triangle.TriangleIndex).Distinct().Count(),
            geometry?.Polygons.Count ?? 0,
            textureRows.Select(row => row.TextureId).Distinct().Count(),
            specialRows,
            textureRows));
    }

    string jsonPath = Path.Combine(reportRoot, "native-terrain-surface-catalog.json");
    string markdownPath = Path.Combine(reportRoot, "native-terrain-surface-catalog.md");
    File.WriteAllText(jsonPath, JsonSerializer.Serialize(new
    {
        GeneratedAtUtc = DateTimeOffset.UtcNow,
        SourceImage = imagePath,
        Levels = levelRows
    }, new JsonSerializerOptions { WriteIndented = true }));

    StringBuilder builder = new();
    builder.AppendLine("# Native Terrain Surface Catalog");
    builder.AppendLine();
    builder.AppendLine("Collision flag bytes are native gameplay data. The low six bits select a level-local special-surface record; the upper two bits are retained separately. Texture rows are exact coordinate matches between visual terrain faces and collision triangles.");
    builder.AppendLine();
    builder.AppendLine("| Level | Collision flags | Special records | Special triangles | Visual matches | Texture/property variants |");
    builder.AppendLine("|---|---:|---:|---:|---:|---:|");
    foreach (NativeTerrainSurfaceLevelRow row in levelRows)
    {
        builder.AppendLine($"| {EscapeMarkdownCell(row.LevelName)} | {row.FlagCount}/{row.TriangleCount} | {row.SpecialSurfaceCount} | {row.SpecialTriangleCount} | {row.MatchedTriangleCount} | {row.TextureRows.Count} |");
    }
    builder.AppendLine();
    builder.AppendLine("## Special-surface signatures");
    builder.AppendLine();
    builder.AppendLine("| Level | Index | Type | Parameters | Native behavior | Collision triangles | Visual matches |");
    builder.AppendLine("|---|---:|---:|---|---|---:|---:|");
    foreach (NativeTerrainSurfaceLevelRow level in levelRows)
    {
        foreach (NativeSpecialSurfaceUsageRow surface in level.SpecialSurfaces)
        {
            builder.AppendLine($"| {EscapeMarkdownCell(level.LevelName)} | {surface.Index} | {surface.Type} | {surface.Param1}, {surface.Param2} | {EscapeMarkdownCell(surface.Label)} | {surface.CollisionTriangleCount} | {surface.MatchedVisualTriangleCount} |");
        }
    }
    File.WriteAllText(markdownPath, builder.ToString());

    int textureVariants = levelRows.Sum(row => row.TextureRows.Count);
    int matchedTriangles = levelRows.Sum(row => row.MatchedTriangleCount);
    Console.WriteLine($"Native terrain surfaces: {levelRows.Count} levels, {levelRows.Sum(row => row.SpecialSurfaceCount)} special record(s), {matchedTriangles} collision triangle(s) matched to visible terrain, {textureVariants} texture/property variant(s).");
    Console.WriteLine($"Native terrain surface report: {markdownPath}");
}

string NativeSurfaceTypeLabel(int type, int param1, int param2)
{
    return type switch
    {
        -1 => "ordinary collision surface",
        0 => param1 == 0 ? $"damaging floor, effect {param2}" : $"lethal damaging floor, effect {param2}",
        1 => $"damaging surface ({param1}, {param2})",
        2 => $"level-linked trigger ({param1}, {param2})",
        4 => "supercharge surface",
        5 => "invisible wall",
        6 => $"portal to level {param1}, portal {param2}",
        7 => $"conditional electric floor {param1}",
        _ => $"native special surface type {type} ({param1}, {param2})"
    };
}

async Task ExportSavedPortalMoveTest(string imagePath, string nativeEditsPath, string outputPrefix)
{
    LevelDefinition level = catalog.FindByKey("artisans")
        ?? throw new InvalidOperationException("Artisans is missing from the level catalog.");
    if (!File.Exists(nativeEditsPath))
        throw new FileNotFoundException("Saved Artisans portal edits were not found.", nativeEditsPath);

    Directory.CreateDirectory(Path.GetDirectoryName(outputPrefix) ?? workspace.RootPath);
    MobySourcePatchResult result = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
        SourceImagePath: imagePath,
        SourceCuePath: DiscImageLocator.FindCueForImage(imagePath),
        OutputPrefix: outputPrefix,
        Level: level,
        NativeEditsPath: nativeEditsPath,
        WriteImage: true));
    if (!result.WroteImage || !File.Exists(result.OutputImagePath) || !File.Exists(result.OutputCuePath))
        throw new InvalidOperationException("Saved Artisans portal test did not produce a BIN/CUE.");

    int movedPortalCount = result.Plan.Patches
        .Where(patch => patch.Kind.StartsWith("portal-transition-path-node-", StringComparison.OrdinalIgnoreCase))
        .Select(patch => patch.TrueIndex)
        .Distinct()
        .Count();
    int pathPatchCount = result.Plan.Patches.Count(patch =>
        patch.Kind.StartsWith("portal-transition-path-node-", StringComparison.OrdinalIgnoreCase));
    int planePatchCount = result.Plan.Patches.Count(patch =>
        patch.Kind.StartsWith("portal-plane-", StringComparison.OrdinalIgnoreCase));
    int triggerPatchCount = result.Plan.Patches.Count(patch =>
        string.Equals(patch.Kind, "portal-entry-collision-triangle", StringComparison.OrdinalIgnoreCase));
    if (movedPortalCount <= 0 || pathPatchCount != movedPortalCount * 6 || planePatchCount != movedPortalCount * 15 || triggerPatchCount != movedPortalCount * 6)
    {
        throw new InvalidOperationException(
            $"Saved Artisans portal export produced {pathPatchCount} path, {planePatchCount} plane, and {triggerPatchCount} trigger patches for {movedPortalCount} moved portals.");
    }

    SourceDiscLayout outputLayout = DetectSourceDiscLayout(result.OutputImagePath);
    using FileStream outputStream = File.OpenRead(result.OutputImagePath);
    foreach (MobySourcePatch patch in result.Plan.Patches)
    {
        if (!patch.WadRelativeOffset.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException($"Portal test patch {patch.Label} does not expose a WAD-relative output offset.");

        long wadOffset = ParseFlexibleLong(patch.WadRelativeOffset);
        byte[] expected = ParseHexPreview(patch.AfterHexPreview);
        byte[] actual = ReadSourceWadBytes(outputStream, outputLayout, wadOffset, expected.Length);
        if (!actual.SequenceEqual(expected))
            throw new InvalidOperationException($"Portal test output differs from {patch.Label} at {patch.WadRelativeOffset}.");
    }

    Console.WriteLine(
        $"Saved portal test exported and byte-verified: {movedPortalCount} portal(s), {pathPatchCount} transition-path axes, " +
        $"{planePatchCount} plane axes, {triggerPatchCount} trigger triangles, {result.Plan.PatchCount} total patches.");
    Console.WriteLine($"Portal test CUE: {result.OutputCuePath}");
    Console.WriteLine($"Portal test plan: {result.OutputPlanPath}");
}

async Task ReportAllPortalSourceMovePlans(string imagePath)
{
    string smokeRoot = Path.Combine(workspace.RootPath, "_local", "smoke", "all-homeworld-portal-moves");
    Directory.CreateDirectory(smokeRoot);
    foreach (IGrouping<string, HomeworldPortalControlDefinition> group in HomeworldPortalControlCatalog.All.GroupBy(definition => definition.HomeworldKey))
    {
        LevelDefinition level = catalog.FindByKey(group.Key)
            ?? throw new InvalidOperationException($"Homeworld {group.Key} is missing from the level catalog.");
        string cachePath = Path.Combine(smokeRoot, $"{level.Key}-source-mobys.json");
        await SourceMobyCacheBuilder.BuildAsync(imagePath, level, cachePath);
        List<Moby> mobys = MobyLoader.LoadCached(cachePath).ToList();
        MobyMetadataEnricher.Apply(workspace, level.Key, mobys);

        HashSet<int> moveTrueIndexes = group.SelectMany(definition => definition.TrueIndexes).ToHashSet();
        List<Moby> moved = mobys.Where(moby => moveTrueIndexes.Contains(moby.TrueIndex)).ToList();
        int expectedMovedRows = group.Count() * 3;
        if (moved.Count != expectedMovedRows)
            throw new InvalidOperationException($"{level.DisplayName} portal move smoke found {moved.Count}/{expectedMovedRows} linked source rows.");

        foreach (Moby moby in moved)
        {
            moby.Position = new Vector3f(
                moby.OriginalPosition.X + 16,
                moby.OriginalPosition.Y + 8,
                moby.OriginalPosition.Z + 4);
        }

        string editsPath = Path.Combine(smokeRoot, $"{level.Key}-all-portals-native-edits.json");
        await MobyEditStore.SaveAsync(editsPath, moved, $"{level.DisplayName} all native portal move smoke");
        MobySourcePatchPlan plan = MobySourcePatchExporter.BuildPlan(
            imagePath,
            DiscImageLocator.FindCueForImage(imagePath),
            Path.Combine(smokeRoot, $"{level.Key}-all-portals.bin"),
            Path.Combine(smokeRoot, $"{level.Key}-all-portals.cue"),
            level,
            editsPath);
        PortalSourceLevelData source = PortalSourceDataLocator.Locate(imagePath, level);
        int expectedPlanePatches = source.Portals.Sum(portal => 3 + (portal.Points.Count * 3));
        int expectedPathPatches = source.Portals.Sum(portal => portal.Path.Nodes.Count * 3);
        int planePatches = plan.Patches.Count(patch => patch.Kind.StartsWith("portal-plane-", StringComparison.OrdinalIgnoreCase));
        int pathPatches = plan.Patches.Count(patch => patch.Kind.StartsWith("portal-transition-path-node-", StringComparison.OrdinalIgnoreCase));
        int triggerPatches = plan.Patches.Count(patch => string.Equals(patch.Kind, "portal-entry-collision-triangle", StringComparison.OrdinalIgnoreCase));
        if (source.Portals.Count != group.Count() ||
            planePatches != expectedPlanePatches ||
            pathPatches != expectedPathPatches ||
            triggerPatches != source.TriggerTriangles.Count)
        {
            throw new InvalidOperationException(
                $"{level.DisplayName} complete portal move planned {planePatches}/{expectedPlanePatches} plane fields, {pathPatches}/{expectedPathPatches} transition-path fields, and {triggerPatches}/{source.TriggerTriangles.Count} trigger triangles.");
        }
        if (!plan.Patches.Any(patch => string.Equals(patch.Kind, "portal-entry-collision-index-tree", StringComparison.OrdinalIgnoreCase)) ||
            !plan.Patches.Any(patch => string.Equals(patch.Kind, "portal-entry-collision-index-blocks", StringComparison.OrdinalIgnoreCase)))
        {
            throw new InvalidOperationException($"{level.DisplayName} complete portal move did not rebuild both collision lookup tables.");
        }

        Console.WriteLine(
            $"Portal move plan: {level.DisplayName} {source.Portals.Count} portal(s), {planePatches} plane field(s), {pathPatches} transition-path field(s), {triggerPatches} entry triangle(s), collision lookup rebuilt.");
    }
}

LifeChestSceneSourceProof ReadLifeChestSceneSourceProof(FileStream sourceStream, SourceDiscLayout sourceLayout, LevelDefinition level)
{
    byte[] entryHeader = ReadSourceWadBytes(sourceStream, sourceLayout, level.SourceWadEntry * 8L, 8);
    long entryWadOffset = BinaryPrimitives.ReadUInt32LittleEndian(entryHeader.AsSpan(0, 4));
    byte[] levelHeader = ReadSourceWadBytes(sourceStream, sourceLayout, entryWadOffset, 0x20);
    uint sceneRelativeOffset = BinaryPrimitives.ReadUInt32LittleEndian(levelHeader.AsSpan(0x18, 4));
    uint sceneByteLength = BinaryPrimitives.ReadUInt32LittleEndian(levelHeader.AsSpan(0x1C, 4));
    return new LifeChestSceneSourceProof(entryWadOffset + sceneRelativeOffset, sceneByteLength);
}

int ReadLifeChestCatalogPrefixRows(
    FileStream sourceStream,
    SourceDiscLayout sourceLayout,
    LevelDefinition level,
    long tableWadOffset)
{
    int directCount = BinaryPrimitives.ReadInt32LittleEndian(
        ReadSourceWadBytes(sourceStream, sourceLayout, tableWadOffset - 4, 4));
    if (directCount == level.SourceRecordCount)
        return 0;

    int oneRowLaterCount = BinaryPrimitives.ReadInt32LittleEndian(
        ReadSourceWadBytes(sourceStream, sourceLayout, tableWadOffset + MobyLoader.RuntimeRecordStride - 4, 4));
    if (oneRowLaterCount == level.SourceRecordCount - 1)
        return 1;

    throw new InvalidOperationException(
        $"{level.DisplayName}'s Life Chest source-count prefix is unresolved ({directCount}, {oneRowLaterCount}).");
}

void ReportLifeChestRuntimeBaseDerivation(
    FileStream sourceStream,
    SourceDiscLayout sourceLayout,
    IReadOnlySet<string> supportedLevelKeys,
    string outDir)
{
    IReadOnlyDictionary<int, uint> overlayCopyBufferAddresses = new Dictionary<int, uint>
    {
        [10] = 0x80088620,
        [11] = 0x8008A3B8,
        [12] = 0x80085594,
        [13] = 0x80089ECC,
        [20] = 0x8008CFA4,
        [21] = 0x8008D600,
        [22] = 0x8008BAF8,
        [23] = 0x80086260,
        [30] = 0x8008E608,
        [33] = 0x8008A8A0,
        [40] = 0x8008AB70,
        [41] = 0x80087944,
        [42] = 0x80087130,
        [43] = 0x80089848,
        [44] = 0x8008A69C,
        [50] = 0x8008BB38,
        [51] = 0x800880D4,
        [52] = 0x8008771C,
        [53] = 0x80089820,
        [54] = 0x80086348,
        [61] = 0x80088668,
        [62] = 0x80086004
    };

    List<LifeChestRuntimeBaseDerivationProof> proofs = new();
    foreach (LevelDefinition level in catalog.Levels.Where(level => supportedLevelKeys.Contains(LevelCatalog.NormalizeKey(level.Key))).OrderBy(level => level.LevelId))
    {
        if (!overlayCopyBufferAddresses.TryGetValue(level.LevelId, out uint copyBufferAddress))
            throw new InvalidOperationException($"{level.DisplayName} has no overlay copy-buffer address for Life Chest runtime derivation.");

        byte[] entryHeader = ReadSourceWadBytes(sourceStream, sourceLayout, level.SourceWadEntry * 8L, 8);
        long entryWadOffset = BinaryPrimitives.ReadUInt32LittleEndian(entryHeader.AsSpan(0, 4));
        byte[] levelHeader = ReadSourceWadBytes(sourceStream, sourceLayout, entryWadOffset, 0x20);
        uint dataRelativeOffset = BinaryPrimitives.ReadUInt32LittleEndian(levelHeader.AsSpan(0x08, 4));
        int dataByteLength = checked((int)BinaryPrimitives.ReadUInt32LittleEndian(levelHeader.AsSpan(0x0C, 4)));
        uint modelDataByteLength = BinaryPrimitives.ReadUInt32LittleEndian(levelHeader.AsSpan(0x14, 4));
        uint sceneRelativeOffset = BinaryPrimitives.ReadUInt32LittleEndian(levelHeader.AsSpan(0x18, 4));
        byte[] levelData = ReadSourceWadBytes(sourceStream, sourceLayout, entryWadOffset + dataRelativeOffset, dataByteLength);
        int consumedLevelDataBytes = ParseLifeChestLoaderConsumedBytes(levelData, level.DisplayName);
        uint derivedRuntimeBase = checked(copyBufferAddress + (uint)consumedLevelDataBytes + modelDataByteLength);
        if (!LifeChestRuntimeLayout.TryGetRuntimeBase(level.Key, out uint mappedRuntimeBase) || mappedRuntimeBase != derivedRuntimeBase)
        {
            throw new InvalidOperationException(
                $"{level.DisplayName} Life Chest runtime base maps to 0x{mappedRuntimeBase:X8}; loader layout derives 0x{derivedRuntimeBase:X8}.");
        }

        proofs.Add(new LifeChestRuntimeBaseDerivationProof(
            level.Key,
            level.DisplayName,
            level.LevelId,
            copyBufferAddress,
            consumedLevelDataBytes,
            modelDataByteLength,
            entryWadOffset + sceneRelativeOffset,
            derivedRuntimeBase));
    }

    string reportPath = Path.Combine(outDir, "runtime-base-derivation-proof.json");
    File.WriteAllText(reportPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now,
        method = "overlay copy buffer + LoadLevelData consumed bytes + model data size",
        proofCount = proofs.Count,
        proofs
    }, new JsonSerializerOptions { WriteIndented = true }));
    Console.WriteLine($"Life Chest runtime-base derivation: {proofs.Count} level(s) matched loader layout; report={reportPath}");
}

int ParseLifeChestLoaderConsumedBytes(byte[] levelData, string levelName)
{
    int offset = 0;
    for (int component = 0; component < 6; component++)
        offset = AdvanceLifeChestLoaderComponent(levelData, offset, levelName);

    if (offset + 4 > levelData.Length)
        throw new InvalidOperationException($"{levelName}'s level data ends before its portal count.");
    int portalCount = BinaryPrimitives.ReadInt32LittleEndian(levelData.AsSpan(offset, 4));
    offset += 4;
    if (portalCount is < 0 or > 6)
        throw new InvalidOperationException($"{levelName}'s level data has invalid portal count {portalCount}.");

    for (int portal = 0; portal < portalCount; portal++)
    {
        int portalStart = offset;
        if (portalStart + 8 > levelData.Length)
            throw new InvalidOperationException($"{levelName}'s portal {portal} header is truncated.");
        int pointCount = BinaryPrimitives.ReadInt32LittleEndian(levelData.AsSpan(portalStart + 4, 4));
        if (pointCount is < 1 or > 64)
            throw new InvalidOperationException($"{levelName}'s portal {portal} has invalid point count {pointCount}.");

        offset = checked(portalStart + 0x2C + ((pointCount - 1) * 12) + 20);
        offset = AdvanceLifeChestLoaderComponent(levelData, offset, levelName);
    }

    offset = AdvanceLifeChestLoaderComponent(levelData, offset, levelName);
    offset = AdvanceLifeChestLoaderComponent(levelData, offset, levelName);
    return offset;
}

int AdvanceLifeChestLoaderComponent(byte[] levelData, int offset, string levelName)
{
    if (offset < 0 || offset + 4 > levelData.Length)
        throw new InvalidOperationException($"{levelName}'s level-data component header at 0x{offset:X} is outside the source block.");
    int byteLength = BinaryPrimitives.ReadInt32LittleEndian(levelData.AsSpan(offset, 4));
    if (byteLength < 4 || (long)offset + byteLength > levelData.Length)
        throw new InvalidOperationException($"{levelName}'s level-data component at 0x{offset:X} has invalid length 0x{byteLength:X}.");
    return offset + byteLength;
}

async Task ReportLifeChestAppendResearch()
{
    if (!File.Exists(sourceImage))
        throw new FileNotFoundException("Life Chest append research needs the selected source BIN.", sourceImage);

    List<NativeAppendResearchFamily> representatives =
    [
        new("artisans", "Life Chest", 0xA5, 0x01, 0x00, 0x10, 0x0E, "working: private runtime blocks", "Live-proven with original T94 plus three appended copies."),
        new("stonehill", "Life Chest", 0xA5, 0x01, 0x00, 0x10, 0x0E, "working: private runtime blocks", "Single-donor destination-level case."),
        new("drycanyon", "Life Chest", 0xA5, 0x01, 0x00, 0x10, 0x0E, "working: private runtime blocks", "Two-donor shared-special-data case."),
        new("icecavern", "Life Chest", 0xA5, 0x01, 0x00, 0x10, 0x0E, "working: private runtime blocks", "Three-donor case with nearby helper-looking rows."),
        new("loftycastle", "Life Chest", 0xA5, 0x01, 0x00, 0x10, 0x0E, "working: private runtime blocks", "Two-donor late-game case."),
        new("metalhead", "Life Chest", 0xA5, 0x01, 0x00, 0x10, 0x0E, "working: private runtime blocks", "Two-donor boss-level case.")
    ];

    SourceDiscLayout sourceLayout = DetectSourceDiscLayout(sourceImage);
    using FileStream sourceStream = File.OpenRead(sourceImage);
    List<NativeAppendResearchRow> appendRows = new();
    foreach (NativeAppendResearchFamily representative in representatives)
        appendRows.Add(await BuildNativeAppendResearchRow(sourceStream, sourceLayout, representative));

    List<LifeChestSourceRow> sourceRows = new();
    foreach (LevelDefinition level in catalog.Levels.Where(level => level.HasSourceTable).OrderBy(level => level.LevelId))
    {
        long tableWadOffset = ParseFlexibleLong(level.SourceTableWadOffset);
        LifeChestSceneSourceProof scene = ReadLifeChestSceneSourceProof(sourceStream, sourceLayout, level);
        Dictionary<int, byte[]> records = new();
        for (int trueIndex = 0; trueIndex < level.SourceRecordCount; trueIndex++)
        {
            records[trueIndex] = ReadSourceWadBytes(
                sourceStream,
                sourceLayout,
                tableWadOffset + ((long)trueIndex * MobyLoader.RuntimeRecordStride),
                MobyLoader.RuntimeRecordStride);
        }

        Dictionary<uint, int> specialLengths = BuildSourceSpecialLengths(records.Values, scene.ByteLength);
        foreach ((int trueIndex, byte[] record) in records.Where(pair => IsNativeLifeChestSourceRecord(pair.Value)))
        {
            int rawX = BitConverter.ToInt32(record, 0x0C);
            int rawY = BitConverter.ToInt32(record, 0x10);
            int rawZ = BitConverter.ToInt32(record, 0x14);
            string colocated = string.Join(", ", records
                .Where(pair => pair.Key != trueIndex &&
                    BitConverter.ToInt32(pair.Value, 0x0C) == rawX &&
                    BitConverter.ToInt32(pair.Value, 0x10) == rawY &&
                    BitConverter.ToInt32(pair.Value, 0x14) == rawZ)
                .OrderBy(pair => pair.Key)
                .Select(pair => $"T{pair.Key} radius50=0x{pair.Value[0x50]:X2} class=0x{pair.Value[0x37]:X2}{pair.Value[0x36]:X2} update52/drop53=0x{pair.Value[0x52]:X2}/0x{pair.Value[0x53]:X2}")
                .Take(8));
            if (string.IsNullOrWhiteSpace(colocated))
                colocated = "none";

            sourceRows.Add(new LifeChestSourceRow(
                LevelKey: level.Key,
                LevelName: level.DisplayName,
                TrueIndex: trueIndex,
                State: record[0x51],
                RawX: rawX,
                RawY: rawY,
                RawZ: rawZ,
                SpecialData: BuildLifeChestSpecialSummary(
                    sourceStream,
                    sourceLayout,
                    scene,
                    record,
                    specialLengths),
                ColocatedRows: colocated));
        }
    }

    int lifeChestLevels = sourceRows.Select(row => row.LevelKey).Distinct(StringComparer.OrdinalIgnoreCase).Count();
    if (sourceRows.Count < 35 || lifeChestLevels < 18)
        throw new InvalidOperationException($"Life Chest source audit found only {sourceRows.Count} row(s) across {lifeChestLevels} level(s).");
    NativeAppendResearchRow artisansAppend = appendRows.Single(row => row.LevelKey.Equals("artisans", StringComparison.OrdinalIgnoreCase));
    if (artisansAppend.AppendSummary.StartsWith("none", StringComparison.OrdinalIgnoreCase) ||
        !artisansAppend.SpecialCloneSummary.Contains("len=24", StringComparison.OrdinalIgnoreCase) ||
        !artisansAppend.AppendedRecordSummary.Contains("special=0x80175018", StringComparison.OrdinalIgnoreCase))
    {
        throw new InvalidOperationException("Artisans Life Chest append did not produce the live-proven private runtime block at 0x80175018.");
    }
    if (appendRows.Any(row =>
        row.AppendSummary.StartsWith("none", StringComparison.OrdinalIgnoreCase) ||
        !row.SpecialCloneSummary.Contains("len=24", StringComparison.OrdinalIgnoreCase) ||
        !row.AppendedRecordSummary.Contains("special=0x80", StringComparison.OrdinalIgnoreCase)))
    {
        throw new InvalidOperationException("One or more promoted Life Chest representative levels did not produce a private-runtime true append.");
    }

    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke", "life-chest-append-research");
    Directory.CreateDirectory(outDir);
    string markdownPath = Path.Combine(outDir, "life-chest-append-research.md");
    string jsonPath = Path.Combine(outDir, "life-chest-append-research.json");
    StringBuilder markdown = new();
    markdown.AppendLine("# Life Chest Append Research");
    markdown.AppendLine();
    markdown.AppendLine($"Native family: `class=0x01A5 radius50=0x20 update52=0x10 drop53=0x0E spec4F=0x00`. Found {sourceRows.Count} source row(s) across {lifeChestLevels} level(s).");
    markdown.AppendLine();
    markdown.AppendLine("Artisans live-RAM validation proved that the native donor must remain untouched and each appended Life Chest needs its own pre-relocated private runtime block. The level-loader layout deterministically maps the same scene-relative allocation for every level, and all 22 native-Life-Chest levels now use independent private blocks.");
    markdown.AppendLine();
    markdown.AppendLine("## Representative Same-Level Append Plans");
    markdown.AppendLine();
    markdown.AppendLine("| Level | Donor | Reusable slots | Release true append | Runtime allocation | Nearby/runtime-only clue |");
    markdown.AppendLine("|---|---|---:|---|---|---|");
    foreach (NativeAppendResearchRow row in appendRows)
        markdown.AppendLine($"| {EscapeMarkdown(row.LevelName)} | {EscapeMarkdown(row.Donor)} | {row.ReusableSlotCount} | {EscapeMarkdown(row.AppendSummary)} | {EscapeMarkdown(row.SpecialCloneSummary)} | {EscapeMarkdown(row.NearbyRuntimeOnlyControls)} |");
    markdown.AppendLine();
    markdown.AppendLine("## Native Source Rows");
    markdown.AppendLine();
    markdown.AppendLine("| Level | Row | State | Raw XYZ | Special data | Exact colocated rows |");
    markdown.AppendLine("|---|---:|---:|---|---|---|");
    foreach (LifeChestSourceRow row in sourceRows)
        markdown.AppendLine($"| {EscapeMarkdown(row.LevelName)} | T{row.TrueIndex} | `0x{row.State:X2}` | `{row.RawX}, {row.RawY}, {row.RawZ}` | {EscapeMarkdown(row.SpecialData)} | {EscapeMarkdown(row.ColocatedRows)} |");
    File.WriteAllText(markdownPath, markdown.ToString());
    File.WriteAllText(jsonPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now,
        sourceRowCount = sourceRows.Count,
        levelCount = lifeChestLevels,
        appendRows,
        sourceRows
    }, new JsonSerializerOptions { WriteIndented = true }));

    Console.WriteLine($"Life Chest append research: {sourceRows.Count} source row(s), {lifeChestLevels} level(s), all native levels private-runtime promoted; report={markdownPath}");
}

bool IsNativeLifeChestSourceRecord(byte[] record)
{
    return record.Length > 0x53 &&
        record[0x50] == 0x20 &&
        record[0x36] == 0xA5 &&
        record[0x37] == 0x01 &&
        record[0x4F] == 0x00 &&
        record[0x52] == 0x10 &&
        record[0x53] == 0x0E;
}

async Task ExportLifeChestAppendCandidate(
    string levelKey = "artisans",
    Vector3f? preferredPosition = null,
    string? outputLabel = null,
    bool aliasSameLevelSpecialData = false)
{
    if (!File.Exists(sourceImage))
        throw new FileNotFoundException("Life Chest candidate export needs the selected source BIN.", sourceImage);

    LevelDefinition level = catalog.FindByKey(levelKey) ??
        throw new InvalidOperationException($"{levelKey} is missing from the level catalog.");
    string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-mobys.json");
    List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
    Moby donor = sourceMobys.First(moby =>
        moby.TrueIndex >= 0 &&
        moby.TrueIndex < level.SourceRecordCount &&
        moby.Type == 0x20 &&
        moby.SourceByte36 == 0xA5 &&
        moby.SourceByte37 == 0x01 &&
        moby.SourceByte4F == 0x00 &&
        moby.Flag4A == 0x10 &&
        moby.Flag4B == 0x0E);

    Vector3f candidatePosition = preferredPosition ?? default;
    if (!preferredPosition.HasValue)
    {
        try
        {
            FlyInLandingData homeworldEntry = FlyInLandingLocator.Locate(sourceImage, level);
            candidatePosition = new Vector3f(
                (homeworldEntry.RawX / 16f) + 320,
                homeworldEntry.RawY / 16f,
                homeworldEntry.RawZ / 16f);
        }
        catch (InvalidOperationException)
        {
            candidatePosition = new Vector3f(donor.Position.X + 320, donor.Position.Y, donor.Position.Z);
        }
    }

    string geometryPath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-runtime-scene-editor-overlay.json");
    if (File.Exists(geometryPath) && !preferredPosition.HasValue)
    {
        GeometryCandidate geometry = GeometryOverlayLoader.LoadFirstCandidate(geometryPath);
        float groundOffset = 0;
        if (TerrainSnapper.TryFindZAt(
                geometry.Polygons,
                donor.Position.X,
                donor.Position.Y,
                donor.Position.Z,
                out float donorGround,
                preferTopSurface: true))
        {
            groundOffset = donor.Position.Z - donorGround;
        }

        if (TerrainSnapper.TryFindZAt(
                geometry.Polygons,
                candidatePosition.X,
                candidatePosition.Y,
                candidatePosition.Z,
                out float candidateGround,
                preferTopSurface: !preferredPosition.HasValue))
        {
            candidatePosition = new Vector3f(candidatePosition.X, candidatePosition.Y, candidateGround + groundOffset);
        }
    }

    int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
    int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
    Moby candidate = CopyAsAddedMoby(donor, nextIndex, nextTrueIndex, "Life Chest append test", 0);
    candidate.Position = candidatePosition;
    candidate.PatchStatus = "native-clone";
    candidate.PatchLead = $"Guarded same-level Life Chest append candidate from {level.DisplayName} donor T{donor.TrueIndex}.";
    candidate.Confidence = "same-level-native-clone-research";
    candidate.Evidence = "Disposable candidate used to prove source-row, private special-data, visibility, and interaction behavior before release promotion.";
    candidate.SourceCloneLevelKey = level.Key;
    candidate.SourceCloneLevelName = level.DisplayName;
    candidate.SourceCloneTrueIndex = donor.TrueIndex;

    string candidateRoot = Path.Combine(workspace.RootPath, "_local", "objects", $"life-chest-append-test-{level.Key}");
    Directory.CreateDirectory(candidateRoot);
    string editsPath = Path.Combine(candidateRoot, $"{level.Key}-life-chest-append-test-native-edits.json");
    await MobyEditStore.SaveAsync(editsPath, [candidate], $"{level.DisplayName} Life Chest append test");
    if (aliasSameLevelSpecialData)
    {
        JsonObject manifest = JsonNode.Parse(await File.ReadAllTextAsync(editsPath))?.AsObject() ??
            throw new InvalidDataException("Life Chest candidate edit manifest is not valid JSON.");
        JsonArray edits = manifest["edits"]?.AsArray() ??
            throw new InvalidDataException("Life Chest candidate edit manifest has no edits array.");
        JsonObject edit = edits.Single()?.AsObject() ??
            throw new InvalidDataException("Life Chest candidate edit manifest did not contain one edit.");
        edit["aliasSameLevelSpecialData"] = true;
        await File.WriteAllTextAsync(editsPath, manifest.ToJsonString());
    }
    string outputPrefix = Path.Combine(
        candidateRoot,
        $"Spyro-Life-Chest-Append-Test-{outputLabel ?? level.DisplayName.Replace(" ", "", StringComparison.Ordinal)}");
    MobySourcePatchResult result = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
        SourceImagePath: sourceImage,
        SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
        OutputPrefix: outputPrefix,
        Level: level,
        NativeEditsPath: editsPath,
        WriteImage: true,
        AllowGuardedNativeCloneAppend: true));
    if (!result.WroteImage)
        throw new InvalidOperationException($"{level.DisplayName} Life Chest candidate did not write a disposable BIN/CUE.");
    VerifyPatchBytes(result.OutputImagePath, result.Plan);

    List<MobySourcePatch> appendPatches = result.Plan.Patches
        .Where(patch => string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase))
        .ToList();
    List<MobySourcePatch> specialPatches = result.Plan.Patches
        .Where(patch => string.Equals(patch.Kind, "moby-special-data-clone", StringComparison.OrdinalIgnoreCase))
        .ToList();
    MobySourcePatch? sourceCountPatch = result.Plan.Patches.FirstOrDefault(patch =>
        string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase));
    int expectedSpecialPatchCount = aliasSameLevelSpecialData ? 0 : 1;
    if (appendPatches.Count != 1 ||
        specialPatches.Count != expectedSpecialPatchCount ||
        !aliasSameLevelSpecialData && specialPatches[0].ByteLength != 24 ||
        sourceCountPatch == null ||
        result.Plan.SkippedEdits.Count != 0)
    {
        throw new InvalidOperationException(
            $"{level.DisplayName} Life Chest candidate wrote append={appendPatches.Count}, special={specialPatches.Count}, count={(sourceCountPatch == null ? 0 : 1)}, skipped={result.Plan.SkippedEdits.Count}.");
    }

    byte[] appendedRecord = ParseHexPreview(appendPatches.Single().AfterHexPreview);
    if (!IsNativeLifeChestSourceRecord(appendedRecord))
        throw new InvalidOperationException($"{level.DisplayName} Life Chest candidate append lost the native Life Chest identity bytes.");

    Console.WriteLine(
        $"{level.DisplayName} Life Chest candidate: donor T{donor.TrueIndex}, append T{appendPatches.Single().TrueIndex}, " +
        $"XYZ {candidatePosition.X:0.###}/{candidatePosition.Y:0.###}/{candidatePosition.Z:0.###}, " +
        $"special={(aliasSameLevelSpecialData ? "same-level donor alias" : "private 24-byte clone")}; cue={result.OutputCuePath}");
}

async Task ExportArtisansLifeChestMultiCandidate()
{
    const uint ArtisansRuntimeSpecialBase = 0x8016313C;
    LevelDefinition level = catalog.FindByKey("artisans") ??
        throw new InvalidOperationException("Artisans is missing from the level catalog.");
    string testedManifestPath = Path.Combine(
        workspace.RootPath,
        "dist",
        "release",
        "SpyroEditor-release-osx-arm64",
        "artisans-native-edits.json");
    if (!File.Exists(testedManifestPath))
        throw new FileNotFoundException("The exact Artisans Life Chest test manifest was not found.", testedManifestPath);

    JsonObject manifest = JsonNode.Parse(await File.ReadAllTextAsync(testedManifestPath))?.AsObject() ??
        throw new InvalidDataException("The Artisans Life Chest test manifest is not valid JSON.");
    JsonArray edits = manifest["edits"]?.AsArray() ??
        throw new InvalidDataException("The Artisans Life Chest test manifest has no edits array.");
    List<JsonObject> lifeChestEdits = edits
        .Select(node => node?.AsObject())
        .Where(edit => edit != null &&
            string.Equals(edit["editKind"]?.GetValue<string>(), "add", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(edit["typeHex"]?.GetValue<string>(), "0x20", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(edit["sourceByte36Hex"]?.GetValue<string>(), "0xA5", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(edit["sourceByte37Hex"]?.GetValue<string>(), "0x01", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(edit["flag4AHex"]?.GetValue<string>(), "0x10", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(edit["flag4BHex"]?.GetValue<string>(), "0x0E", StringComparison.OrdinalIgnoreCase))
        .Cast<JsonObject>()
        .ToList();
    if (lifeChestEdits.Count != 3 || edits.Count != 3)
        throw new InvalidOperationException($"Expected the tested manifest to contain exactly three Life Chest adds; found {lifeChestEdits.Count} of {edits.Count} edit(s).");

    foreach (JsonObject edit in lifeChestEdits)
    {
        edit["disableAutoSlotReuse"] = true;
        edit["lifeChestPrivateRuntimeBase"] = $"0x{ArtisansRuntimeSpecialBase:X8}";
    }
    manifest["note"] = "Disposable Artisans multi-Life-Chest private runtime-pointer candidate.";

    string candidateRoot = Path.Combine(workspace.RootPath, "_local", "objects", "artisans-life-chest-multi-private-runtime");
    Directory.CreateDirectory(candidateRoot);
    string editsPath = Path.Combine(candidateRoot, "artisans-life-chest-multi-private-runtime-native-edits.json");
    await File.WriteAllTextAsync(editsPath, manifest.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));

    string outputPrefix = Path.Combine(candidateRoot, "Spyro-Artisans-Life-Chest-Multi-Private-Runtime");
    MobySourcePatchResult result = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
        SourceImagePath: sourceImage,
        SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
        OutputPrefix: outputPrefix,
        Level: level,
        NativeEditsPath: editsPath,
        WriteImage: true));
    if (!result.WroteImage)
        throw new InvalidOperationException("Artisans multi-Life-Chest candidate did not write a disposable BIN/CUE.");
    VerifyPatchBytes(result.OutputImagePath, result.Plan);

    List<MobySourcePatch> appendPatches = result.Plan.Patches
        .Where(patch => string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase))
        .OrderBy(patch => patch.TrueIndex)
        .ToList();
    List<MobySourcePatch> specialPatches = result.Plan.Patches
        .Where(patch => string.Equals(patch.Kind, "moby-special-data-clone", StringComparison.OrdinalIgnoreCase))
        .OrderBy(patch => patch.TrueIndex)
        .ToList();
    if (appendPatches.Count != 3 || specialPatches.Count != 3 ||
        result.Plan.Patches.Any(patch => string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase)) ||
        result.Plan.SkippedEdits.Count != 0)
    {
        throw new InvalidOperationException(
            $"Artisans multi-Life-Chest candidate wrote append={appendPatches.Count}, special={specialPatches.Count}, " +
            $"auto-slot={result.Plan.Patches.Count(patch => string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase))}, " +
            $"skipped={result.Plan.SkippedEdits.Count}.");
    }

    uint[] runtimePointers = appendPatches
        .Select(patch => BinaryPrimitives.ReadUInt32LittleEndian(ParseHexPreview(patch.AfterHexPreview).AsSpan(0, 4)))
        .ToArray();
    if (runtimePointers.Distinct().Count() != 3 || runtimePointers.Any(pointer => pointer < 0x80000000u))
        throw new InvalidOperationException("Artisans multi-Life-Chest candidate did not assign three unique pre-relocated runtime pointers.");

    Console.WriteLine(
        $"Artisans multi-Life-Chest candidate: preserved original T94; appended {string.Join(", ", appendPatches.Select(patch => $"T{patch.TrueIndex}"))}; " +
        $"private pointers {string.Join(", ", runtimePointers.Select(pointer => $"0x{pointer:X8}"))}; cue={result.OutputCuePath}");
}

async Task ReportNativeActorChestAppendAllocationResearch()
{
    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke");
    Directory.CreateDirectory(outDir);
    string markdownPath = Path.Combine(outDir, "native-actor-chest-append-allocation-research.md");
    string jsonPath = Path.Combine(outDir, "native-actor-chest-append-allocation-research.json");

    List<NativeAppendResearchFamily> families =
    [
        new("darkhollow", "Large Gnorc", 0x73, 0x00, 0x00, 0x10, 0x54, "provisional: one true-add only", "One append works, but later/random Dark Hollow crashes were reported with multiple extra actors and chests. Normal Create BIN now caps this family at one true-add after slot reuse."),
        new("darkhollow", "Flame/Charge Chest", 0xC2, 0x00, 0x00, 0x10, 0x54, "provisional: one true-add only", "One append works, but later/random Dark Hollow crashes were reported with multiple extra actors and chests. Normal Create BIN now caps this family at one true-add after slot reuse."),
        new("townsquare", "Bull", 0x17, 0x00, 0x00, 0x10, 0x54, "provisional: one true-add only", "Live testing proved one true-add after safe slots were consumed; normal Create BIN now keeps later same-family appends guarded until multi-actor allocation is proven."),
        new("townsquare", "Torro Gnorc", 0x8B, 0x01, 0x00, 0x10, 0x54, "failed: inert", "User-confirmed over-limit Torros spawn but do not move or react."),
        new("townsquare", "Flame/Charge Chest", 0xC2, 0x00, 0x00, 0x10, 0x54, "failed: chest behavior/render risk", "Kept guarded until over-limit chests render and break reliably."),
        new("townsquare", "Charge Chest", 0xC3, 0x00, 0x00, 0x10, 0x54, "failed: invisible/red/broken", "User-confirmed over-limit charge chests can be invisible or render as broken red geometry."),
        new("townsquare", "3x Flame Chest", 0x86, 0x01, 0x00, 0x10, 0x56, "failed: destroys on level entry", "User-confirmed over-limit 3x Flame chests can destroy themselves as the level loads.")
    ];

    List<NativeAppendResearchRow> rows = new();
    if (!File.Exists(sourceImage))
    {
        File.WriteAllText(markdownPath, "# Native Actor/Chest Append Allocation Research\n\nSource disc was not found; no rows were generated.\n");
        File.WriteAllText(jsonPath, JsonSerializer.Serialize(new { generatedAt = DateTimeOffset.Now, rows }, new JsonSerializerOptions { WriteIndented = true }));
        Console.WriteLine("Native actor/chest append allocation research: source disc not found; wrote empty report.");
        return;
    }

    SourceDiscLayout sourceLayout = DetectSourceDiscLayout(sourceImage);
    using FileStream sourceStream = File.OpenRead(sourceImage);
    foreach (NativeAppendResearchFamily family in families)
    {
        NativeAppendResearchRow row = await BuildNativeAppendResearchRow(sourceStream, sourceLayout, family);
        rows.Add(row);
    }

    StringBuilder markdown = new();
    markdown.AppendLine("# Native Actor/Chest Append Allocation Research");
    markdown.AppendLine();
    markdown.AppendLine("This report compares same-level true-append candidates after the normal safe-slot reuse pool is exhausted. It intentionally treats the normal release path as guarded; these rows are reverse-engineering evidence, not release approval.");
    markdown.AppendLine();
    markdown.AppendLine("## Current Read");
    markdown.AppendLine();
    markdown.AppendLine("- A source-row append plus cloned special data is enough for one Dark Hollow Large Gnorc, one Dark Hollow Flame/Charge Chest, and the Town Square Bull baseline.");
    markdown.AppendLine("- Multiple active actor/chest appends still have unresolved runtime allocation pressure: Dark Hollow has produced delayed/random crashes, including near a dragon rescue. Normal Create BIN now allows one provisional true-add per promoted family and skips later rows.");
    markdown.AppendLine("- The failed Town Square families still get source rows and special-data clones, so the missing piece is likely behavior allocation beyond the shell row: hidden companion rows, runtime actor startup state, or a family-specific shared controller.");
    markdown.AppendLine("- The 3x Flame Chest has the strongest companion clue: a nearby/runtime-only fan or control row sits on the native chest but is outside the mapped source table count.");
    markdown.AppendLine();
    markdown.AppendLine("## Matrix");
    markdown.AppendLine();
    markdown.AppendLine("| Family | Donor | Donor source bytes | Safe slots | Research append | Special clone | Runtime-only / nearby controls | Live result | Current hypothesis |");
    markdown.AppendLine("|---|---|---|---:|---|---|---|---|---|");
    foreach (NativeAppendResearchRow row in rows)
    {
        markdown.AppendLine($"| {EscapeMarkdown(row.FamilyName)} | {EscapeMarkdown(row.Donor)} | `{row.Identity}` | {row.ReusableSlotCount} | {EscapeMarkdown(row.AppendSummary)} | {EscapeMarkdown(row.SpecialCloneSummary)} | {EscapeMarkdown(row.NearbyRuntimeOnlyControls)} | {EscapeMarkdown(row.LiveStatus)} | {EscapeMarkdown(row.Hypothesis)} |");
    }

    markdown.AppendLine();
    markdown.AppendLine("## Family Details");
    foreach (NativeAppendResearchRow row in rows)
    {
        markdown.AppendLine();
        markdown.AppendLine($"### {row.LevelName} - {row.FamilyName}");
        markdown.AppendLine();
        markdown.AppendLine($"- Live status: {row.LiveStatus}. {row.LiveNotes}");
        markdown.AppendLine($"- Generated native edits: `{row.NativeEditsPath}`");
        markdown.AppendLine($"- Plan-only research patch plan: `{row.PlanPath}`");
        markdown.AppendLine($"- Donor source record: `{row.DonorRecordSummary}`");
        markdown.AppendLine($"- Appended source record: `{row.AppendedRecordSummary}`");
        markdown.AppendLine($"- Same-special native rows: {EscapeMarkdown(row.SameSpecialRows)}");
        markdown.AppendLine($"- Nearby runtime-only/control rows: {EscapeMarkdown(row.NearbyRuntimeOnlyControls)}");
        markdown.AppendLine($"- Next probe: {EscapeMarkdown(row.NextProbe)}");
    }

    File.WriteAllText(markdownPath, markdown.ToString());
    File.WriteAllText(jsonPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now,
        note = "Plan-only research for same-level actor/chest true appends. These are not release-promoted unless live testing passes.",
        rows
    }, new JsonSerializerOptions { WriteIndented = true }));

    Console.WriteLine($"Native actor/chest append allocation research: rows={rows.Count}, report={markdownPath}");
}

async Task<NativeAppendResearchRow> BuildNativeAppendResearchRow(FileStream sourceStream, SourceDiscLayout sourceLayout, NativeAppendResearchFamily family)
{
    LevelDefinition? level = catalog.FindByKey(family.LevelKey);
    if (level == null || !level.HasSourceTable)
    {
        return NativeAppendResearchRow.Missing(family, "level source table is not mapped");
    }

    string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{family.LevelKey}-mobys.json");
    if (!File.Exists(mobyPath))
    {
        return NativeAppendResearchRow.Missing(family, "moby cache is missing");
    }

    List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
    Moby? donor = sourceMobys.FirstOrDefault(moby =>
        moby.TrueIndex >= 0 &&
        moby.TrueIndex < level.SourceRecordCount &&
        moby.Type == 0x20 &&
        moby.SourceByte36 == family.SourceByte36 &&
        moby.SourceByte37 == family.SourceByte37 &&
        moby.SourceByte4F == family.SourceByte4F &&
        moby.Flag4A == family.Flag4A &&
        moby.Flag4B == family.Flag4B);
    if (donor == null)
    {
        return NativeAppendResearchRow.Missing(family, "donor object not found in source cache");
    }

    int reusableSlotCount = sourceMobys.Count(moby => IsPromotedNativeCloneTrueAppendSmokeCandidate(moby, level, donor));
    int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
    int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
    List<Moby> addedMobys = new();
    for (int i = 0; i <= reusableSlotCount; i++)
    {
        Moby added = CopyAsAddedMoby(donor, nextIndex + i, nextTrueIndex + i, $"Research {family.FamilyName} clone {i + 1}", 0);
        added.PatchStatus = "native-clone";
        added.PatchLead = $"Plan-only allocation research from same-level {family.FamilyName} donor T{donor.TrueIndex}.";
        added.Confidence = "same-level-native-clone-research";
        added.Evidence = "Plan-only research candidate; normal Create BIN remains guarded unless this family is separately live-promoted.";
        added.SourceCloneLevelKey = level.Key;
        added.SourceCloneLevelName = level.DisplayName;
        added.SourceCloneTrueIndex = donor.TrueIndex;
        addedMobys.Add(added);
    }

    string familySlug = NativeAppendResearchSlug(family.FamilyName);
    string nativeEditsPath = Path.Combine(workspace.RootPath, "_local", "smoke", $"{family.LevelKey}-research-{familySlug}-append-native-edits.json");
    await MobyEditStore.SaveAsync(nativeEditsPath, addedMobys, $"{level.DisplayName} research {family.FamilyName} allocation append");

    string outputPrefix = Path.Combine(workspace.RootPath, "_local", "objects", $"{family.LevelKey}-research-{familySlug}-append");
    MobySourcePatchResult result = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
        SourceImagePath: sourceImage,
        SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
        OutputPrefix: outputPrefix,
        Level: level,
        NativeEditsPath: nativeEditsPath,
        WriteImage: false,
        AllowGuardedNativeCloneAppend: !family.FamilyName.Equals("Life Chest", StringComparison.OrdinalIgnoreCase)));

    MobySourcePatch? appendPatch = result.Plan.Patches.FirstOrDefault(patch => string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase));
    MobySourcePatch? specialClone = appendPatch == null
        ? null
        : result.Plan.Patches.FirstOrDefault(patch =>
            string.Equals(patch.Kind, "moby-special-data-clone", StringComparison.OrdinalIgnoreCase) &&
            patch.TrueIndex == appendPatch.TrueIndex);

    long tableWadOffset = ParseFlexibleLong(level.SourceTableWadOffset);
    long tableRelativeOffset = ParseFlexibleLong(level.SourceTableRelativeOffset);
    Dictionary<int, byte[]> sourceRecords = new();
    for (int trueIndex = 0; trueIndex < level.SourceRecordCount; trueIndex++)
        sourceRecords[trueIndex] = ReadSourceWadBytes(sourceStream, sourceLayout, tableWadOffset + ((long)trueIndex * MobyLoader.RuntimeRecordStride), MobyLoader.RuntimeRecordStride);
    Dictionary<uint, int> specialLengths = BuildSourceSpecialLengths(sourceRecords.Values, tableRelativeOffset);
    byte[] donorRecord = sourceRecords[donor.TrueIndex];
    byte[] appendedRecord = appendPatch == null ? [] : ParseHexPreview(appendPatch.AfterHexPreview);
    bool aliasesSameLevelDonorSpecialData = appendPatch?.Description.Contains(
        "Reused same-level donor",
        StringComparison.OrdinalIgnoreCase) == true;
    if (aliasesSameLevelDonorSpecialData &&
        appendedRecord.Length >= 4 &&
        BitConverter.ToUInt32(appendedRecord, 0) != BitConverter.ToUInt32(donorRecord, 0))
    {
        throw new InvalidOperationException($"{level.DisplayName} Life Chest append did not preserve donor T{donor.TrueIndex}'s loader-relocatable special-data offset.");
    }
    string donorSpecialSummary;
    if (family.FamilyName.Equals("Life Chest", StringComparison.OrdinalIgnoreCase))
    {
        LifeChestSceneSourceProof scene = ReadLifeChestSceneSourceProof(sourceStream, sourceLayout, level);
        Dictionary<uint, int> sceneSpecialLengths = BuildSourceSpecialLengths(sourceRecords.Values, scene.ByteLength);
        donorSpecialSummary = BuildLifeChestSpecialSummary(sourceStream, sourceLayout, scene, donorRecord, sceneSpecialLengths);
    }
    else
    {
        donorSpecialSummary = BuildNativeAppendSpecialSummary(sourceStream, sourceLayout, tableWadOffset, tableRelativeOffset, donorRecord, specialLengths);
    }
    string appendedRecordSummary = appendedRecord.Length == 0 ? "no append patch" : FormatNativeAppendRecordSummary(appendedRecord);
    string specialCloneSummary = aliasesSameLevelDonorSpecialData
        ? $"donor alias offset=0x{BitConverter.ToUInt32(donorRecord, 0):X}; no private source block"
        : specialClone == null
        ? "none"
        : $"T{specialClone.TrueIndex} len={specialClone.ByteLength}, target={specialClone.WadRelativeOffset}";
    string appendSummary = appendPatch == null
        ? $"none; skipped={string.Join("; ", result.Plan.SkippedEdits)}"
        : $"T{appendPatch.TrueIndex}, countPatch={result.Plan.Patches.Any(patch => string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase))}";

    string sameSpecialRows = BuildSameSpecialRows(sourceMobys, level, donor);
    string nearbyRuntimeOnlyControls = BuildNearbyRuntimeOnlyControlRows(sourceMobys, level, donor);
    string hypothesis = BuildNativeAppendHypothesis(family, specialClone, nearbyRuntimeOnlyControls);
    string nextProbe = BuildNativeAppendNextProbe(family, nearbyRuntimeOnlyControls);

    return new NativeAppendResearchRow(
        LevelKey: level.Key,
        LevelName: level.DisplayName,
        FamilyName: family.FamilyName,
        LiveStatus: family.LiveStatus,
        LiveNotes: family.LiveNotes,
        Donor: $"T{donor.TrueIndex} {donor.DisplayLabel}",
        Identity: $"class=0x{donorRecord[0x37]:X2}{donorRecord[0x36]:X2} radius50=0x{donorRecord[0x50]:X2} update52=0x{donorRecord[0x52]:X2} drop53=0x{donorRecord[0x53]:X2} spec4F=0x{donorRecord[0x4F]:X2}",
        ReusableSlotCount: reusableSlotCount,
        NativeEditsPath: nativeEditsPath,
        PlanPath: result.OutputPlanPath,
        AppendSummary: appendSummary,
        SpecialCloneSummary: $"{specialCloneSummary}; donor {donorSpecialSummary}",
        DonorRecordSummary: FormatNativeAppendRecordSummary(donorRecord),
        AppendedRecordSummary: appendedRecordSummary,
        SameSpecialRows: sameSpecialRows,
        NearbyRuntimeOnlyControls: nearbyRuntimeOnlyControls,
        Hypothesis: hypothesis,
        NextProbe: nextProbe);
}

string BuildNativeAppendSpecialSummary(FileStream sourceStream, SourceDiscLayout sourceLayout, long tableWadOffset, long tableRelativeOffset, byte[] recordBytes, IReadOnlyDictionary<uint, int> specialLengths)
{
    uint sourceOffset = BitConverter.ToUInt32(recordBytes, 0);
    if (!IsSourceSpecialDataOffset(tableRelativeOffset, sourceOffset))
        return $"offset=0x{sourceOffset:X8} non-source/no clone";

    int length = specialLengths.TryGetValue(sourceOffset, out int foundLength)
        ? foundLength
        : DefaultSourceSpecialLength(recordBytes[0x50]);
    byte[] specialBytes = ReadSourceWadBytes(sourceStream, sourceLayout, tableWadOffset - tableRelativeOffset + sourceOffset, length);
    string hash = Convert.ToHexString(SHA256.HashData(specialBytes).AsSpan(0, 6)).ToLowerInvariant();
    return $"offset=0x{sourceOffset:X}, len={length}, sha={hash}, prefix={FormatHex(specialBytes.AsSpan(0, Math.Min(12, specialBytes.Length)))}";
}

string BuildLifeChestSpecialSummary(
    FileStream sourceStream,
    SourceDiscLayout sourceLayout,
    LifeChestSceneSourceProof scene,
    byte[] recordBytes,
    IReadOnlyDictionary<uint, int> specialLengths)
{
    uint sourceOffset = BitConverter.ToUInt32(recordBytes, 0);
    if (sourceOffset == 0 || sourceOffset >= scene.ByteLength)
        return $"offset=0x{sourceOffset:X8} non-scene/no clone";

    int length = specialLengths.TryGetValue(sourceOffset, out int foundLength)
        ? foundLength
        : DefaultSourceSpecialLength(recordBytes[0x50]);
    byte[] specialBytes = ReadSourceWadBytes(
        sourceStream,
        sourceLayout,
        scene.WadBaseOffset + sourceOffset,
        length);
    string hash = Convert.ToHexString(SHA256.HashData(specialBytes).AsSpan(0, 6)).ToLowerInvariant();
    return $"offset=0x{sourceOffset:X}, len={length}, sha={hash}, prefix={FormatHex(specialBytes.AsSpan(0, Math.Min(12, specialBytes.Length)))}";
}

string FormatNativeAppendRecordSummary(byte[] record)
{
    if (record.Length <= 0x53)
        return "short record";

    return FormattableString.Invariant(
        $"special=0x{BitConverter.ToUInt32(record, 0):X}, raw=({BitConverter.ToInt32(record, 0x0C)},{BitConverter.ToInt32(record, 0x10)},{BitConverter.ToInt32(record, 0x14)}), behavior38=0x{record[0x39]:X2}{record[0x38]:X2}, sector4A=0x{record[0x4A]:X2}, radius50=0x{record[0x50]:X2}, wasDrawn51=0x{record[0x51]:X2}, class=0x{record[0x37]:X2}{record[0x36]:X2}, spec4F=0x{record[0x4F]:X2}, update52/drop53=0x{record[0x52]:X2}/0x{record[0x53]:X2}");
}

string BuildSameSpecialRows(IReadOnlyList<Moby> sourceMobys, LevelDefinition level, Moby donor)
{
    List<string> rows = sourceMobys
        .Where(moby =>
            moby.TrueIndex >= 0 &&
            moby.TrueIndex < level.SourceRecordCount &&
            moby.SpecialDataPointer == donor.SpecialDataPointer)
        .OrderBy(moby => moby.TrueIndex)
        .Select(moby => $"T{moby.TrueIndex}(wasDrawn51=0x{moby.State:X2},drop53=0x{moby.Flag4B:X2})")
        .ToList();
    return rows.Count == 0 ? "none" : string.Join(", ", rows);
}

string BuildNearbyRuntimeOnlyControlRows(IReadOnlyList<Moby> sourceMobys, LevelDefinition level, Moby donor)
{
    List<string> rows = sourceMobys
        .Where(moby =>
            moby.TrueIndex >= level.SourceRecordCount &&
            Distance2D(moby.Position, donor.Position) <= 384)
        .OrderBy(moby => Distance2D(moby.Position, donor.Position))
        .ThenBy(moby => moby.TrueIndex)
        .Take(8)
        .Select(moby => $"T{moby.TrueIndex} {moby.DisplayLabel} radius50=0x{moby.Type:X2} class=0x{moby.SourceByte37:X2}{moby.SourceByte36:X2} dist={Distance2D(moby.Position, donor.Position):0}")
        .ToList();
    return rows.Count == 0 ? "none within 384u" : string.Join("; ", rows);
}

double Distance2D(Vector3f a, Vector3f b)
{
    double dx = a.X - b.X;
    double dy = a.Y - b.Y;
    return Math.Sqrt((dx * dx) + (dy * dy));
}

string BuildNativeAppendHypothesis(NativeAppendResearchFamily family, MobySourcePatch? specialClone, string nearbyRuntimeOnlyControls)
{
    if (family.FamilyName.Equals("Life Chest", StringComparison.OrdinalIgnoreCase))
        return "Pre-relocated, scene-relative private runtime blocks preserve the native Life Chest and independently initialize every appended copy.";
    if (family.LiveStatus.Contains("working", StringComparison.OrdinalIgnoreCase))
        return "Source row plus special-data clone appears sufficient for this simpler actor baseline.";
    if (family.SourceByte36 == 0x86 && nearbyRuntimeOnlyControls.Contains("T108", StringComparison.OrdinalIgnoreCase))
        return "Shell append is missing the colocated 3x chest fan/control row; solve companion allocation before promoting.";
    if (nearbyRuntimeOnlyControls.StartsWith("T", StringComparison.OrdinalIgnoreCase))
        return "Likely missing a runtime-only companion/control row in addition to the shell special-data clone.";
    if (specialClone != null)
        return "Special data is cloned, so the failure likely sits in actor startup/root allocation or family-specific runtime state.";
    return "No special-data clone was produced; first solve source special-data allocation.";
}

string BuildNativeAppendNextProbe(NativeAppendResearchFamily family, string nearbyRuntimeOnlyControls)
{
    if (family.FamilyName.Equals("Life Chest", StringComparison.OrdinalIgnoreCase))
        return "Keep cross-level Life Chest imports guarded; same-level copy/add is promoted in every level with a native Life Chest.";
    if (family.LiveStatus.Contains("working", StringComparison.OrdinalIgnoreCase))
        return "Keep as baseline; compare appended record and special-data shape against failed families.";
    if (family.SourceByte36 == 0x86)
        return "Create a disposable paired-shell-plus-fan candidate for T69/T108, then live-test load, visibility, hit response, and reward count.";
    if (family.SourceByte36 == 0x8B)
        return "Compare Torro runtime rows before/after level load against the appended row; look for actor root/startup state that native source-count append does not allocate.";
    return "Create a one-family candidate that also moves/copies nearest container control rows, then verify visibility from all camera angles and hit/reward behavior.";
}

string NativeAppendResearchSlug(string value)
{
    StringBuilder builder = new();
    foreach (char ch in value.ToLowerInvariant())
    {
        if (char.IsLetterOrDigit(ch))
            builder.Append(ch);
        else if (builder.Length == 0 || builder[^1] != '-')
            builder.Append('-');
    }

    return builder.ToString().Trim('-');
}

async Task ReportBehaviorLinkedNativeCloneAppendState(string levelKey)
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine($"{levelKey} behavior-linked native clone append state: source disc not found; skipping.");
        return;
    }

    LevelDefinition? level = catalog.FindByKey(levelKey);
    if (level == null || !level.HasSourceTable)
    {
        Console.WriteLine($"{levelKey} behavior-linked native clone append state: source table is not mapped; skipping.");
        return;
    }

    string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{levelKey}-mobys.json");
    if (!File.Exists(mobyPath))
    {
        Console.WriteLine($"{levelKey} behavior-linked native clone append state: moby cache not found; skipping.");
        return;
    }

    List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
    Moby? donor = sourceMobys.FirstOrDefault(moby => moby.TrueIndex == 37)
        ?? sourceMobys.FirstOrDefault(moby =>
        moby.TrueIndex >= 0 &&
        moby.TrueIndex < level.SourceRecordCount &&
        moby.Type == 0x20 &&
        moby.SourceByte36 == 0xA5 &&
        moby.SourceByte37 == 0x00 &&
        moby.SourceByte4F != 0x00 &&
        moby.Flag4A == 0x10);
    if (donor == null)
    {
        Console.WriteLine($"{level.DisplayName} behavior-linked native clone append state: Small Gnorc donor object not found; skipping.");
        return;
    }

    int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
    int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
    Moby added = CopyAsAddedMoby(donor, nextIndex, nextTrueIndex, $"Behavior-linked Small Gnorc append {donor.TrueIndex}", 8);
    added.PatchStatus = "native-clone";
    added.PatchLead = $"Experimental Small Gnorc true-append smoke from same-level donor T{donor.TrueIndex}.";
    added.Confidence = "same-level-native-clone";
    added.Evidence = $"Copied from behavior-linked same-level Small Gnorc donor T{donor.TrueIndex}; source startup state must come from the disc row, not the live editor cache.";
    added.SourceCloneLevelKey = level.Key;
    added.SourceCloneLevelName = level.DisplayName;
    added.SourceCloneTrueIndex = donor.TrueIndex;

    string path = Path.Combine(workspace.RootPath, "_local", "smoke", $"{levelKey}-behavior-linked-small-gnorc-append-native-edits.json");
    await MobyEditStore.SaveAsync(path, [added], $"{level.DisplayName} behavior-linked Small Gnorc append");
    MobySourcePatchResult exportResult = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
        SourceImagePath: sourceImage,
        SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
        OutputPrefix: Path.Combine(workspace.RootPath, "_local", "objects", $"{levelKey}-behavior-linked-small-gnorc-append"),
        Level: level,
        NativeEditsPath: path,
        WriteImage: true,
        AllowGuardedNativeCloneAppend: true));
    MobySourcePatchPlan plan = exportResult.Plan;
    if (!exportResult.WroteImage)
        throw new InvalidOperationException($"{level.DisplayName} behavior-linked Small Gnorc append did not write a BIN.");
    VerifyPatchBytes(exportResult.OutputImagePath, plan);
    if (plan.SkippedEdits.Count != 0)
        throw new InvalidOperationException($"{level.DisplayName} behavior-linked Small Gnorc append skipped edit(s): {string.Join("; ", plan.SkippedEdits)}");

    MobySourcePatch appendPatch = plan.Patches.SingleOrDefault(patch => string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase))
        ?? throw new InvalidOperationException($"{level.DisplayName} behavior-linked Small Gnorc append did not write an append patch.");
    byte[] appendedRecord = ParseHexPreview(appendPatch.AfterHexPreview);
    long tableWadOffset = ParseFlexibleLong(level.SourceTableWadOffset);
    SourceDiscLayout sourceLayout = DetectSourceDiscLayout(sourceImage);
    using FileStream sourceStream = File.OpenRead(sourceImage);
    byte[] donorSourceRecord = ReadSourceWadBytes(sourceStream, sourceLayout, tableWadOffset + ((long)donor.TrueIndex * MobyLoader.RuntimeRecordStride), MobyLoader.RuntimeRecordStride);
    if (appendedRecord.Length <= 0x53 ||
        donorSourceRecord.Length <= 0x53 ||
        appendedRecord[0x50] != donorSourceRecord[0x50] ||
        appendedRecord[0x36] != donorSourceRecord[0x36] ||
        appendedRecord[0x37] != donorSourceRecord[0x37] ||
        appendedRecord[0x38] != donorSourceRecord[0x38] ||
        appendedRecord[0x39] != donorSourceRecord[0x39] ||
        appendedRecord[0x4F] != donorSourceRecord[0x4F] ||
        appendedRecord[0x51] != donorSourceRecord[0x51] ||
        appendedRecord[0x52] != donorSourceRecord[0x52] ||
        appendedRecord[0x53] != donorSourceRecord[0x53])
    {
        throw new InvalidOperationException($"{level.DisplayName} behavior-linked Small Gnorc append did not preserve the donor source identity/startup bytes.");
    }

    if (!appendPatch.Description.Contains("Source startup state preserved", StringComparison.OrdinalIgnoreCase))
        throw new InvalidOperationException($"{level.DisplayName} behavior-linked Small Gnorc append did not describe source startup-state preservation.");

    MobySourcePatch? specialClone = plan.Patches.FirstOrDefault(patch =>
        string.Equals(patch.Kind, "moby-special-data-clone", StringComparison.OrdinalIgnoreCase) &&
        patch.TrueIndex == appendPatch.TrueIndex);
    if (specialClone == null)
        throw new InvalidOperationException($"{level.DisplayName} behavior-linked Small Gnorc append did not clone donor special data.");
    if (!appendPatch.Description.Contains("Behavior donor upgraded", StringComparison.OrdinalIgnoreCase))
        throw new InvalidOperationException($"{level.DisplayName} behavior-linked Small Gnorc append did not upgrade the blank copied donor: {appendPatch.Description}");
    if (ParseHexPreview(specialClone.AfterHexPreview).All(value => value == 0))
        throw new InvalidOperationException($"{level.DisplayName} behavior-linked Small Gnorc append cloned blank special data for the over-limit copy.");

    Console.WriteLine($"{level.DisplayName} behavior-linked Small Gnorc append: true-appended T{appendPatch.TrueIndex} with donor source state 0x{appendedRecord[0x51]:X2} and behavior marker 0x{appendedRecord[0x39]:X2}{appendedRecord[0x38]:X2}");
}

bool IsPromotedNativeCloneTrueAppendSmokeDonor(Moby moby, LevelDefinition level, int sourceByte36)
{
    return moby.TrueIndex >= 0 &&
        moby.TrueIndex < level.SourceRecordCount &&
        moby.Type == 0x20 &&
        moby.SourceByte36 == sourceByte36 &&
        moby.SourceByte37 == 0x00 &&
        moby.SourceByte4F == 0x00 &&
        moby.Flag4A == 0x10 &&
        moby.Flag4B == 0x54;
}

bool IsPromotedNativeCloneTrueAppendSmokeCandidate(Moby candidate, LevelDefinition level, Moby donor)
{
    if (candidate.TrueIndex < 0 ||
        candidate.TrueIndex >= level.SourceRecordCount ||
        candidate.Type != donor.Type)
    {
        return false;
    }

    bool exactFamily =
        candidate.SourceByte36 == donor.SourceByte36 &&
        candidate.SourceByte37 == donor.SourceByte37 &&
        candidate.SourceByte4F == donor.SourceByte4F &&
        candidate.Flag4A == donor.Flag4A &&
        candidate.Flag4B == donor.Flag4B;
    if (exactFamily)
        return true;

    return candidate.SourceByte36 == donor.SourceByte36 &&
        candidate.SourceByte37 == donor.SourceByte37 &&
        candidate.Flag4A == donor.Flag4A;
}

async Task ReportPastedNativeCloneAppendPatch(string levelKey)
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine($"{levelKey} pasted native clone append patch: source disc not found; skipping.");
        return;
    }

    LevelDefinition? level = catalog.FindByKey(levelKey);
    if (level == null || !level.HasSourceTable)
    {
        Console.WriteLine($"{levelKey} pasted native clone append patch: source table is not mapped; skipping.");
        return;
    }

    string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{levelKey}-mobys.json");
    if (!File.Exists(mobyPath))
    {
        Console.WriteLine($"{levelKey} pasted native clone append patch: moby cache not found; skipping.");
        return;
    }

    List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
    IGrouping<string, Moby>? duplicateGroup = sourceMobys
        .Where(moby =>
            moby.TrueIndex >= 0 &&
            moby.TrueIndex < level.SourceRecordCount &&
            moby.Type == 0x20 &&
            moby.Flag4A == 0x10)
        .GroupBy(moby => $"{moby.Type:X2}:{moby.State:X2}:{moby.SourceByte36:X2}:{moby.SourceByte37:X2}:{moby.SourceByte4F:X2}:{moby.Flag4A:X2}:{moby.Flag4B:X2}", StringComparer.OrdinalIgnoreCase)
        .Where(group => group.Count() > 1)
        .OrderByDescending(group => group.Count())
        .FirstOrDefault();
    Moby? donor = duplicateGroup?.OrderBy(moby => moby.TrueIndex).Last()
        ?? sourceMobys.FirstOrDefault(moby =>
            moby.TrueIndex >= 0 &&
            moby.TrueIndex < level.SourceRecordCount &&
            moby.Type == 0x20 &&
            moby.SourceByte36 == 0xA6 &&
            moby.Flag4A == 0x10);
    if (donor == null)
    {
        Console.WriteLine($"{level.DisplayName} pasted native clone append patch: donor object not found; skipping.");
        return;
    }

    int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
    int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
    Moby pasted = CopyAsAddedMoby(donor, nextIndex, nextTrueIndex, $"Copy of {donor.DisplayLabel}", 6);
    pasted.PatchStatus = "native-clone";
    pasted.PatchLead = $"Pasted from same-level donor T{donor.TrueIndex}; saved in the editor, but Create BIN skips new enemy/chest true-adds until their behavior data is fully solved.";
    pasted.Confidence = "same-level-native-clone";
    pasted.Evidence = $"Copied from same-level donor T{donor.TrueIndex}.";
    pasted.SourceCloneLevelKey = level.Key;
    pasted.SourceCloneLevelName = level.DisplayName;
    pasted.SourceCloneTrueIndex = donor.TrueIndex;

    string path = Path.Combine(workspace.RootPath, "_local", "smoke", $"{levelKey}-pasted-native-clone-append-native-edits.json");
    await MobyEditStore.SaveAsync(path, [pasted], $"{level.DisplayName} pasted native clone append");

    using (FileStream editStream = File.OpenRead(path))
    using (JsonDocument editDocument = JsonDocument.Parse(editStream))
    {
        JsonElement edit = editDocument.RootElement.GetProperty("edits")[0];
        string mode = edit.GetProperty("recordMutation").GetProperty("mode").GetString() ?? "";
        int sourceTrueIndex = edit.GetProperty("recordMutation").GetProperty("sourceTrueIndex").GetInt32();
        if (!string.Equals(mode, "appendSourceRecordClone", StringComparison.OrdinalIgnoreCase) || sourceTrueIndex != donor.TrueIndex)
            throw new InvalidOperationException($"{level.DisplayName} pasted native clone append did not persist append donor metadata.");
    }

    MobySourcePatchResult exportResult = await MobySourcePatchExporter.ExportAsync(new MobySourcePatchRequest(
        SourceImagePath: sourceImage,
        SourceCuePath: DiscImageLocator.FindCueForImage(sourceImage),
        OutputPrefix: Path.Combine(workspace.RootPath, "_local", "objects", $"{levelKey}-pasted-native-clone-append"),
        Level: level,
        NativeEditsPath: path,
        WriteImage: true));
    MobySourcePatchPlan plan = exportResult.Plan;
    if (!exportResult.WroteImage)
        throw new InvalidOperationException($"{level.DisplayName} pasted native clone auto-slot route did not write a BIN.");
    VerifyPatchBytes(exportResult.OutputImagePath, plan);
    if (plan.Patches.Any(patch =>
        string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase) ||
        string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase)))
    {
        throw new InvalidOperationException($"{level.DisplayName} pasted native clone auto-slot route wrote append/count patch(es).");
    }
    if (plan.SkippedEdits.Count != 0)
        throw new InvalidOperationException($"{level.DisplayName} pasted native clone auto-slot route skipped edit(s): {string.Join("; ", plan.SkippedEdits)}");
    MobySourcePatch slotPatch = plan.Patches.Single(patch => string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase));
    VerifySlotClonePatchIdentity($"{level.DisplayName} pasted native clone auto-slot route", slotPatch, donor, pasted.Position);

    Console.WriteLine($"{level.DisplayName} pasted native clone auto-slot route: preserved donor T{donor.TrueIndex} metadata and reused slot T{slotPatch.TrueIndex}");
}

int ToSmokeRawCoordinate(float value) => (int)Math.Round(value * 16f);

void VerifySlotClonePatchIdentity(string context, MobySourcePatch patch, Moby donor, Vector3f placedPosition)
{
    byte[] after = ParseHexPreview(patch.AfterHexPreview);
    const int xOffset = 0x0C;
    const int yOffset = 0x10;
    const int zOffset = 0x14;
    const int typeOffset = 0x50;
    if (after.Length < 0x58 ||
        after[typeOffset] != donor.Type ||
        after[0x36] != donor.SourceByte36 ||
        after[0x37] != donor.SourceByte37 ||
        after[0x4F] != donor.SourceByte4F ||
        after[0x52] != donor.Flag4A ||
        after[0x53] != donor.Flag4B ||
        donor.YawByte >= 0 && after[0x46] != donor.YawByte ||
        BitConverter.ToInt32(after, xOffset) != ToSmokeRawCoordinate(placedPosition.X) ||
        BitConverter.ToInt32(after, yOffset) != ToSmokeRawCoordinate(placedPosition.Y) ||
        BitConverter.ToInt32(after, zOffset) != ToSmokeRawCoordinate(placedPosition.Z))
    {
        throw new InvalidOperationException($"{context} did not clone donor identity while preserving the placed position.");
    }
    if (donor.YawByte >= 0)
        VerifyYawMatrixBytes(context, after.AsSpan(0x20, 18).ToArray(), donor.YawByte);
}

void VerifyYawMatrixBytes(string context, byte[] matrixBytes, int yawByte)
{
    byte[] expected = Moby.YawByteToMatrixBytes(yawByte);
    if (matrixBytes.Length != expected.Length || !matrixBytes.SequenceEqual(expected))
    {
        string actualHex = string.Join(" ", matrixBytes.Select(value => $"{value:X2}"));
        string expectedHex = string.Join(" ", expected.Select(value => $"{value:X2}"));
        throw new InvalidOperationException($"{context} wrote yaw matrix {actualHex}, expected {expectedHex} for 0x{yawByte:X2} ({Moby.YawByteToDegrees(yawByte):0.#} deg).");
    }
}

Moby CopyAsAddedMoby(Moby donor, int index, int trueIndex, string label, int offsetStep)
{
    Vector3f position = new(donor.Position.X + (offsetStep * 24), donor.Position.Y, donor.Position.Z);
    return new Moby
    {
        Index = index,
        TrueIndex = trueIndex,
        LegacyIndex = MobyLoader.GetLegacyAliasIndex(trueIndex),
        Position = position,
        OriginalPosition = position,
        Type = donor.Type,
        OriginalType = donor.Type,
        State = donor.State,
        OriginalState = donor.State,
        YawByte = donor.YawByte,
        OriginalYawByte = donor.YawByte,
        SourceByte36 = donor.SourceByte36,
        OriginalSourceByte36 = donor.SourceByte36,
        SourceByte37 = donor.SourceByte37,
        OriginalSourceByte37 = donor.SourceByte37,
        SourceByte4F = donor.SourceByte4F,
        OriginalSourceByte4F = donor.SourceByte4F,
        Flag4A = donor.Flag4A,
        OriginalFlag4A = donor.Flag4A,
        Flag4B = donor.Flag4B,
        OriginalFlag4B = donor.Flag4B,
        Color = donor.Color,
        Label = label,
        OriginalLabel = label,
        PatchStatus = "smoke-copy-paste",
        PatchLead = $"Pasted from copied {donor.DisplayLabel}.",
        IsAdded = true
    };
}

async Task ReportAllLevelNativeCloneAutoSlotReuse()
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine("All-level native clone auto-slot reuse: source disc not found; skipping.");
        return;
    }

    int tested = 0;
    int skipped = 0;
    int sectorVerified = 0;
    int sectorFallbackVerified = 0;
    SourceDiscLayout sourceLayout = DetectSourceDiscLayout(sourceImage);
    using FileStream sourceStream = File.OpenRead(sourceImage);
    foreach (LevelDefinition level in catalog.Levels.Where(level => level.HasSourceTable))
    {
        string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-mobys.json");
        if (!File.Exists(mobyPath))
        {
            skipped++;
            continue;
        }

        List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
        MobyMetadataEnricher.Apply(workspace, level.Key, sourceMobys);
        IGrouping<string, Moby>? duplicateGroup = sourceMobys
            .Where(moby =>
                moby.TrueIndex >= 0 &&
                moby.TrueIndex < level.SourceRecordCount &&
                moby.Type is 0x18 or 0x20 &&
                !moby.IsGemLike &&
                !moby.IsKey &&
                moby.VisualKind is MobyVisualKind.Actor or MobyVisualKind.Chest)
            .GroupBy(moby => $"{moby.Type:X2}:{moby.State:X2}:{moby.SourceByte36:X2}:{moby.SourceByte37:X2}:{moby.SourceByte4F:X2}:{moby.Flag4A:X2}:{moby.Flag4B:X2}", StringComparer.OrdinalIgnoreCase)
            .Where(group => group.Count() > 1)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .FirstOrDefault();
        if (duplicateGroup == null)
        {
            skipped++;
            continue;
        }

        Moby donor = duplicateGroup.OrderBy(moby => moby.TrueIndex).Last();
        int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
        int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
        Moby added = CopyAsAddedMoby(donor, nextIndex, nextTrueIndex, $"All-level copy of {donor.DisplayLabel}", 3);
        added.PatchStatus = "native-clone";
        added.PatchLead = $"All-level auto-slot smoke from same-level donor T{donor.TrueIndex}.";
        added.Confidence = "same-level-native-clone";
        added.Evidence = $"Copied from same-level donor T{donor.TrueIndex}.";
        added.SourceCloneLevelKey = level.Key;
        added.SourceCloneLevelName = level.DisplayName;
        added.SourceCloneTrueIndex = donor.TrueIndex;

        string path = Path.Combine(workspace.RootPath, "_local", "smoke", "all-level-native-auto-slot", $"{level.Key}-native-edits.json");
        Directory.CreateDirectory(Path.GetDirectoryName(path) ?? workspace.RootPath);
        await MobyEditStore.SaveAsync(path, [added], $"{level.DisplayName} all-level native auto-slot");
        string outputPrefix = Path.Combine(workspace.RootPath, "_local", "smoke", "all-level-native-auto-slot", $"{level.Key}-native-auto-slot");
        MobySourcePatchPlan plan = MobySourcePatchExporter.BuildPlan(
            sourceImage,
            DiscImageLocator.FindCueForImage(sourceImage),
            $"{outputPrefix}.bin",
            $"{outputPrefix}.cue",
            level,
            path);
        if (plan.SkippedEdits.Count != 0)
            throw new InvalidOperationException($"{level.DisplayName} all-level native auto-slot skipped edit(s): {string.Join("; ", plan.SkippedEdits)}");
        if (plan.Patches.Any(patch =>
            string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(patch.Kind, "moby-source-count", StringComparison.OrdinalIgnoreCase)))
        {
            throw new InvalidOperationException($"{level.DisplayName} all-level native auto-slot wrote append/count patch(es).");
        }

        MobySourcePatch slotPatch = plan.Patches.SingleOrDefault(patch =>
            string.Equals(patch.Kind, "moby-record-auto-slot-clone", StringComparison.OrdinalIgnoreCase))
            ?? throw new InvalidOperationException($"{level.DisplayName} all-level native auto-slot did not write an auto slot clone patch.");
        if (slotPatch.TrueIndex == donor.TrueIndex && duplicateGroup.Count() > 1)
            throw new InvalidOperationException($"{level.DisplayName} all-level native auto-slot reused donor T{donor.TrueIndex} even though another same-family slot was available.");
        VerifySlotClonePatchIdentity($"{level.DisplayName} all-level native auto-slot", slotPatch, donor, added.Position);

        byte[] after = ParseHexPreview(slotPatch.AfterHexPreview);
        if (after.Length <= 0x4A)
            throw new InvalidOperationException($"{level.DisplayName} all-level native auto-slot patch is too short to verify the placement sector byte.");

        string geometryPath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-runtime-scene-editor-overlay.json");
        if (File.Exists(geometryPath))
        {
            GeometryCandidate geometry = GeometryOverlayLoader.LoadFirstCandidate(geometryPath);
            if (TryFindPlacementSector(geometry, added.Position, out int expectedSector))
            {
                if (after[0x4A] != expectedSector)
                    throw new InvalidOperationException($"{level.DisplayName} all-level native auto-slot wrote sector byte 0x{after[0x4A]:X2}, expected 0x{expectedSector:X2} for the placed enemy/chest.");
                if (!slotPatch.Description.Contains($"Placement sector byte set to 0x{expectedSector:X2}", StringComparison.OrdinalIgnoreCase))
                    throw new InvalidOperationException($"{level.DisplayName} all-level native auto-slot did not report sector 0x{expectedSector:X2}: {slotPatch.Description}");
                sectorVerified++;
            }
        }
        else
        {
            long tableWadOffset = ParseFlexibleLong(level.SourceTableWadOffset);
            byte[] targetRecord = ReadSourceWadBytes(sourceStream, sourceLayout, tableWadOffset + ((long)slotPatch.TrueIndex * MobyLoader.RuntimeRecordStride), MobyLoader.RuntimeRecordStride);
            if (targetRecord.Length <= 0x4A || after[0x4A] != targetRecord[0x4A])
                throw new InvalidOperationException($"{level.DisplayName} all-level native auto-slot did not preserve reused slot sector byte when geometry was unavailable.");
            sectorFallbackVerified++;
        }

        tested++;
    }

    Console.WriteLine($"All-level native clone auto-slot reuse: {tested} level(s) verified, {sectorVerified} placement sector(s), {sectorFallbackVerified} fallback sector(s), {skipped} skipped without duplicate actor/chest source families");
}

async Task ReportAllLevelLooseGemPlacementSectors()
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine("All-level loose gem placement sectors: source disc not found; skipping.");
        return;
    }

    int tested = 0;
    int skipped = 0;
    foreach (LevelDefinition level in catalog.Levels.Where(level => level.HasSourceTable))
    {
        string mobyPath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-mobys.json");
        string geometryPath = Path.Combine(workspace.RootPath, "editor-cache", $"{level.Key}-runtime-scene-editor-overlay.json");
        if (!File.Exists(mobyPath) || !File.Exists(geometryPath))
        {
            skipped++;
            continue;
        }

        List<Moby> sourceMobys = MobyLoader.LoadCached(mobyPath).ToList();
        Moby? donor = sourceMobys.FirstOrDefault(moby =>
            moby.TrueIndex >= 0 &&
            moby.TrueIndex < level.SourceRecordCount &&
            moby.Type == 0x18 &&
            moby.SourceByte37 == 0x00 &&
            moby.Flag4A == 0x40 &&
            moby.Flag4B == 0xFF &&
            GemValue.TryFromEncoding(moby.SourceByte36, moby.SourceByte4F, out _));
        if (donor == null || !GemValue.TryFromEncoding(donor.SourceByte36, donor.SourceByte4F, out GemValue copiedGem))
        {
            skipped++;
            continue;
        }

        GeometryCandidate geometry = GeometryOverlayLoader.LoadFirstCandidate(geometryPath);
        TerrainPolygon? placement = geometry.Polygons
            .Where(polygon => !polygon.IsTerrainRemoved && polygon.SectorIndex is >= 0 and <= 255)
            .FirstOrDefault(polygon => polygon.TryGetZ(polygon.Center.X, polygon.Center.Y, out _));
        if (placement == null || !placement.TryGetZ(placement.Center.X, placement.Center.Y, out float placementZ))
        {
            skipped++;
            continue;
        }

        Vector3f position = new(placement.Center.X, placement.Center.Y, placementZ);
        if (!TryFindPlacementSector(geometry, position, out int expectedSector))
        {
            skipped++;
            continue;
        }

        int nextIndex = sourceMobys.Max(moby => moby.Index) + 1;
        int nextTrueIndex = sourceMobys.Max(moby => moby.TrueIndex) + 1;
        Moby addedGem = new()
        {
            Index = nextIndex,
            TrueIndex = nextTrueIndex,
            LegacyIndex = MobyLoader.GetLegacyAliasIndex(nextTrueIndex),
            Position = position,
            OriginalPosition = position,
            Type = donor.Type,
            OriginalType = donor.Type,
            State = donor.State,
            OriginalState = donor.State,
            SourceByte36 = copiedGem.IdByte,
            OriginalSourceByte36 = copiedGem.IdByte,
            SourceByte37 = donor.SourceByte37,
            OriginalSourceByte37 = donor.SourceByte37,
            SourceByte4F = copiedGem.ValueByte,
            OriginalSourceByte4F = copiedGem.ValueByte,
            Flag4A = donor.Flag4A,
            OriginalFlag4A = donor.Flag4A,
            Flag4B = donor.Flag4B,
            OriginalFlag4B = donor.Flag4B,
            Color = copiedGem.Color,
            Label = $"Smoke all-level {copiedGem.Name}",
            OriginalLabel = $"Smoke all-level {copiedGem.Name}",
            PatchStatus = "smoke-all-level-placement-sector",
            PatchLead = $"Pasted from copied {donor.DisplayLabel}; verifies loose gem render sector export.",
            IsAdded = true
        };

        string path = Path.Combine(workspace.RootPath, "_local", "smoke", "all-level-gem-sector", $"{level.Key}-native-edits.json");
        Directory.CreateDirectory(Path.GetDirectoryName(path) ?? workspace.RootPath);
        await MobyEditStore.SaveAsync(path, [addedGem], $"{level.DisplayName} all-level loose gem sector");
        string outputPrefix = Path.Combine(workspace.RootPath, "_local", "smoke", "all-level-gem-sector", $"{level.Key}-sector-gem");
        MobySourcePatchPlan plan = MobySourcePatchExporter.BuildPlan(
            sourceImage,
            DiscImageLocator.FindCueForImage(sourceImage),
            $"{outputPrefix}.bin",
            $"{outputPrefix}.cue",
            level,
            path);
        MobySourcePatch appendPatch = plan.Patches
            .Where(patch => string.Equals(patch.Kind, "moby-record-append", StringComparison.OrdinalIgnoreCase))
            .OrderBy(patch => patch.TrueIndex)
            .FirstOrDefault()
            ?? throw new InvalidOperationException($"{level.DisplayName} all-level loose gem sector check did not append a gem.");
        byte[] after = ParseHexPreview(appendPatch.AfterHexPreview);
        if (appendPatch.TrueIndex != level.SourceRecordCount)
            throw new InvalidOperationException($"{level.DisplayName} all-level loose gem sector appended T{appendPatch.TrueIndex}, expected T{level.SourceRecordCount}.");
        if (after.Length <= 0x4A || after[0x4A] != expectedSector)
            throw new InvalidOperationException($"{level.DisplayName} all-level loose gem sector wrote byte 0x{(after.Length <= 0x4A ? -1 : after[0x4A]):X2}, expected 0x{expectedSector:X2}.");
        if (!appendPatch.Description.Contains($"Placement sector byte set to 0x{expectedSector:X2}", StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException($"{level.DisplayName} all-level loose gem sector did not report sector 0x{expectedSector:X2}: {appendPatch.Description}");

        tested++;
    }

    Console.WriteLine($"All-level loose gem placement sectors: {tested} level(s) verified, {skipped} skipped without loose-gem/source geometry coverage");
}

bool TryFindPlacementSector(GeometryCandidate geometry, Vector3f position, out int sectorIndex)
{
    sectorIndex = -1;
    SmokeTerrainSectorCandidate? best = null;
    foreach (TerrainPolygon polygon in geometry.Polygons)
    {
        if (polygon.IsTerrainRemoved || polygon.SectorIndex is < 0 or > 255)
            continue;
        if (!polygon.TryGetZ(position.X, position.Y, out float terrainZ))
            continue;

        SmokeTerrainSectorCandidate candidate = new(polygon.SectorIndex, terrainZ, Math.Abs(terrainZ - position.Z));
        if (best == null ||
            candidate.DistanceToReference < best.Value.DistanceToReference - 0.001f ||
            Math.Abs(candidate.DistanceToReference - best.Value.DistanceToReference) <= 0.001f && candidate.Z > best.Value.Z)
        {
            best = candidate;
        }
    }

    if (best == null)
        return false;

    sectorIndex = best.Value.SectorIndex;
    return true;
}

void ReportTerrainColorFidelity()
{
    string cacheDir = Path.Combine(workspace.RootPath, "editor-cache");
    if (!Directory.Exists(cacheDir))
        throw new DirectoryNotFoundException($"Terrain color fidelity requires the complete editor cache: {cacheDir}");

    int checkedLevels = 0;
    int checkedFaces = 0;
    int lowestUniqueColorCount = int.MaxValue;
    string lowestUniqueColorLevel = "";
    double lowestSpreadRetention = double.MaxValue;
    double lowestBucketRetention = double.MaxValue;
    string lowestSpreadLevel = "";
    string lowestBucketLevel = "";
    foreach (LevelDefinition level in catalog.Levels)
    {
        string levelKey = level.Key;
        string path = Path.Combine(cacheDir, $"{levelKey}-runtime-scene-editor-overlay.json");
        if (!File.Exists(path))
            throw new FileNotFoundException($"Terrain color fidelity is missing the {level.DisplayName} overlay.", path);

        GeometryCacheHealthIssue? healthIssue = GeometryCacheHealth.InspectOverlay(levelKey, path);
        if (healthIssue?.BlocksLoading == true)
            throw new InvalidOperationException($"{level.DisplayName} terrain overlay failed cache health: {healthIssue.Message}");

        GeometryCandidate geometry = GeometryOverlayLoader.LoadFirstCandidate(path);
        TerrainMaterialClassifier.Apply(levelKey, workspace.RootPath, geometry);
        int mismatchedColors = geometry.Polygons.Count(face => face.SurfaceColor != face.FaceColor);
        if (mismatchedColors != 0)
            throw new InvalidOperationException($"{levelKey} terrain preview replaced {mismatchedColors} captured face color(s) with generic material colors.");

        int uniqueColors = geometry.Polygons.Select(face => face.SurfaceColor).Distinct().Count();
        if (geometry.Polygons.Count >= 1000 && uniqueColors < 256)
            throw new InvalidOperationException($"{levelKey} terrain preview only has {uniqueColors} unique colors for {geometry.Polygons.Count} faces; this looks like a generic material fallback.");

        ColorRgba[] capturedColors = geometry.Polygons
            .Select(face => face.SurfaceColor)
            .ToArray();
        ColorRgba[] previewColors = geometry.Polygons
            .Select(face => TerrainPreviewColor.ApplyHeightTint(
                face.SurfaceColor,
                Math.Clamp((face.AvgZ - geometry.MinZ) / Math.Max(1, geometry.MaxZ - geometry.MinZ), 0, 1)))
            .ToArray();
        double capturedSpread = TerrainColorRmsSpread(capturedColors);
        double previewSpread = TerrainColorRmsSpread(previewColors);
        double spreadRetention = capturedSpread <= 0.001 ? 1 : previewSpread / capturedSpread;
        int capturedBuckets = TerrainRgb16BucketCount(capturedColors);
        int previewBuckets = TerrainRgb16BucketCount(previewColors);
        double bucketRetention = capturedBuckets == 0 ? 1 : (double)previewBuckets / capturedBuckets;
        if (geometry.Polygons.Count >= 1000 && spreadRetention < 0.90)
            throw new InvalidOperationException($"{levelKey} display preview retains only {spreadRetention:P1} of captured RGB spread; expected at least 90%.");
        if (geometry.Polygons.Count >= 1000 && bucketRetention < 0.85)
            throw new InvalidOperationException($"{levelKey} display preview retains only {bucketRetention:P1} of captured RGB16 buckets; expected at least 85%.");

        checkedLevels++;
        checkedFaces += geometry.Polygons.Count;
        if (uniqueColors < lowestUniqueColorCount)
        {
            lowestUniqueColorCount = uniqueColors;
            lowestUniqueColorLevel = levelKey;
        }
        if (spreadRetention < lowestSpreadRetention)
        {
            lowestSpreadRetention = spreadRetention;
            lowestSpreadLevel = levelKey;
        }
        if (bucketRetention < lowestBucketRetention)
        {
            lowestBucketRetention = bucketRetention;
            lowestBucketLevel = levelKey;
        }
    }

    if (checkedLevels != catalog.Levels.Count || checkedLevels != 35)
        throw new InvalidOperationException($"Terrain color fidelity checked {checkedLevels}/{catalog.Levels.Count} levels; expected the complete 35-level catalog.");

    Console.WriteLine($"Terrain color fidelity: captured face colors preserved for {checkedLevels} level(s), {checkedFaces} face(s); lowest variety {lowestUniqueColorLevel}={lowestUniqueColorCount} color(s); preview spread {lowestSpreadLevel}={lowestSpreadRetention:P1}; RGB16 buckets {lowestBucketLevel}={lowestBucketRetention:P1}");
}

double TerrainColorRmsSpread(IReadOnlyList<ColorRgba> colors)
{
    if (colors.Count == 0)
        return 0;

    double meanR = colors.Average(color => color.R);
    double meanG = colors.Average(color => color.G);
    double meanB = colors.Average(color => color.B);
    double variance = colors.Average(color =>
        Math.Pow(color.R - meanR, 2) +
        Math.Pow(color.G - meanG, 2) +
        Math.Pow(color.B - meanB, 2));
    return Math.Sqrt(variance);
}

int TerrainRgb16BucketCount(IEnumerable<ColorRgba> colors)
{
    return colors
        .Select(color => (color.R >> 4, color.G >> 4, color.B >> 4))
        .Distinct()
        .Count();
}

async Task ReportTerrainMaterialBehaviorAudit()
{
    string cacheDir = Path.Combine(workspace.RootPath, "editor-cache");
    if (!Directory.Exists(cacheDir))
    {
        Console.WriteLine("Terrain audit: editor cache not present; skipping.");
        return;
    }

    List<TerrainLevelAudit> levels = new();
    List<GeometryCacheHealthIssue> skipped = new();
    foreach (string path in Directory.EnumerateFiles(cacheDir, "*-runtime-scene-editor-overlay.json").OrderBy(item => item, StringComparer.OrdinalIgnoreCase))
    {
        string fileName = Path.GetFileName(path);
        string levelKey = fileName.Replace("-runtime-scene-editor-overlay.json", "", StringComparison.OrdinalIgnoreCase);
        GeometryCacheHealthIssue? healthIssue = GeometryCacheHealth.InspectOverlay(levelKey, path);
        if (healthIssue?.BlocksLoading == true)
        {
            skipped.Add(healthIssue);
            continue;
        }

        GeometryCandidate geometry = GeometryOverlayLoader.LoadFirstCandidate(path);
        TerrainMaterialClassifier.Apply(levelKey, workspace.RootPath, geometry);
        LevelDefinition? level = catalog.FindByKey(levelKey);
        List<TerrainTextureAudit> textures = geometry.Polygons
            .GroupBy(polygon => polygon.TextureId)
            .Select(group => BuildTerrainTextureAudit(group))
            .OrderByDescending(group => group.FaceCount)
            .ThenBy(group => group.TextureId)
            .ToList();

        IReadOnlyDictionary<string, int> surfaces = TerrainMaterialClassifier.CountSurfaces(geometry);
        IReadOnlyDictionary<string, int> behaviors = TerrainBehaviorClassifier.CountBehaviors(geometry);
        levels.Add(new TerrainLevelAudit
        {
            LevelKey = levelKey,
            DisplayName = level?.DisplayName ?? levelKey,
            FaceCount = geometry.Polygons.Count,
            TextureCount = textures.Count,
            SurfaceCounts = surfaces,
            BehaviorCounts = behaviors,
            HazardCandidateFaces = behaviors.TryGetValue("hazard-candidate", out int hazards) ? hazards : 0,
            TextureGroups = textures
        });
    }

    if (levels.Count == 0)
    {
        Console.WriteLine("Terrain audit: no runtime scene overlays found.");
        return;
    }

    List<TerrainLevelAudit> unknownSurfaceLevels = levels
        .Where(level => level.SurfaceCounts.ContainsKey("unknown"))
        .ToList();
    if (unknownSurfaceLevels.Count > 0)
    {
        string summary = string.Join("; ", unknownSurfaceLevels.Select(level => $"{level.DisplayName}={level.SurfaceCounts["unknown"]}"));
        throw new InvalidOperationException($"Terrain audit found unknown surface types: {summary}");
    }

    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke");
    Directory.CreateDirectory(outDir);
    string jsonPath = Path.Combine(outDir, "terrain-material-behavior-audit.json");
    string markdownPath = Path.Combine(outDir, "terrain-material-behavior-audit.md");
    var report = new
    {
        generatedAt = DateTimeOffset.Now.ToString("s", CultureInfo.InvariantCulture),
        note = "Visual terrain materials and behavior candidates from portable runtime scene overlays. Hazard labels are candidates until the collision response/surface flag is decoded.",
        skipped,
        levels
    };
    JsonSerializerOptions options = new() { WriteIndented = true };
    await File.WriteAllTextAsync(jsonPath, JsonSerializer.Serialize(report, options));
    await File.WriteAllTextAsync(markdownPath, BuildTerrainAuditMarkdown(levels, skipped));
    string skippedSummary = skipped.Count == 0 ? "" : $", skipped {skipped.Count} unhealthy overlay(s)";
    Console.WriteLine($"Terrain audit: {levels.Count} levels, {levels.Sum(level => level.FaceCount)} faces, {levels.Sum(level => level.HazardCandidateFaces)} hazard candidate face(s){skippedSummary}");
    Console.WriteLine($"Terrain audit report: {markdownPath}");
}

async Task ReportGeometryCacheHealth()
{
    string cacheDir = Path.Combine(workspace.RootPath, "editor-cache");
    if (!Directory.Exists(cacheDir))
    {
        Console.WriteLine("Geometry cache health: editor-cache not found; skipping.");
        return;
    }

    List<GeometryCacheHealthIssue> issues = new();
    foreach (string path in Directory.EnumerateFiles(cacheDir, "*-runtime-scene-editor-overlay.json").OrderBy(item => item, StringComparer.OrdinalIgnoreCase))
    {
        string fileName = Path.GetFileName(path);
        string levelKey = fileName.Replace("-runtime-scene-editor-overlay.json", "", StringComparison.OrdinalIgnoreCase);
        GeometryCacheHealthIssue? issue = GeometryCacheHealth.InspectOverlay(levelKey, path);
        if (issue != null)
            issues.Add(issue);
    }

    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke");
    Directory.CreateDirectory(outDir);
    string jsonPath = Path.Combine(outDir, "geometry-cache-health.json");
    string markdownPath = Path.Combine(outDir, "geometry-cache-health.md");
    JsonSerializerOptions options = new() { WriteIndented = true };
    await File.WriteAllTextAsync(jsonPath, JsonSerializer.Serialize(new
    {
        generatedAt = DateTimeOffset.Now.ToString("s", CultureInfo.InvariantCulture),
        issues
    }, options));

    StringBuilder builder = new();
    builder.AppendLine("# Geometry Cache Health");
    builder.AppendLine();
    if (issues.Count == 0)
    {
        builder.AppendLine("No cache health issues detected.");
    }
    else
    {
        builder.AppendLine("| Level | Severity | Blocks loading | Message |");
        builder.AppendLine("|---|---|---|---|");
        foreach (GeometryCacheHealthIssue issue in issues)
            builder.AppendLine($"| {issue.LevelKey} | {issue.Severity} | {issue.BlocksLoading} | {issue.Message} |");
    }

    await File.WriteAllTextAsync(markdownPath, builder.ToString());
    Console.WriteLine(issues.Count == 0
        ? "Geometry cache health: no issues detected."
        : $"Geometry cache health: {issues.Count} issue(s), report {markdownPath}");
}

async Task ReportSourceSceneOverlayRecovery(bool repairCache)
{
    if (!File.Exists(sourceImage) || !File.Exists(wadAnalysis))
    {
        Console.WriteLine("Source scene recovery: source disc or WAD analysis not found; skipping.");
        return;
    }

    LevelDefinition? gnastyLoot = catalog.FindByKey("gnastysloot");
    if (gnastyLoot == null)
    {
        Console.WriteLine("Source scene recovery: Gnasty's Loot is missing from the level catalog.");
        return;
    }

    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke");
    Directory.CreateDirectory(outDir);
    string stoneHillSourcePath = Path.Combine(outDir, "stonehill-source-scene-overlay.json");
    SourceSceneOverlayResult stoneHillResult = await SourceSceneOverlayExporter.ExportAsync(sourceImage, wadAnalysis, stoneHill, stoneHillSourcePath);
    GeometryCandidate stoneHillSourceGeometry = GeometryOverlayLoader.LoadFirstCandidate(stoneHillSourcePath);
    if (stoneHillSourceGeometry.Polygons.Count != 6659)
        throw new InvalidOperationException($"Stone Hill source recovery produced {stoneHillSourceGeometry.Polygons.Count} faces, expected 6659.");

    string gnastyOutput = repairCache
        ? Path.Combine(workspace.RootPath, "editor-cache", "gnastysloot-runtime-scene-editor-overlay.json")
        : Path.Combine(outDir, "gnastysloot-source-scene-overlay.json");
    SourceSceneOverlayResult gnastyResult = await SourceSceneOverlayExporter.ExportAsync(sourceImage, wadAnalysis, gnastyLoot, gnastyOutput);
    GeometryCacheHealthIssue? healthIssue = GeometryCacheHealth.InspectOverlay("gnastysloot", gnastyOutput);
    if (healthIssue?.BlocksLoading == true)
        throw new InvalidOperationException("Gnasty's Loot source recovery still matches the bad homeworld capture.");

    GeometryCandidate gnastyGeometry = GeometryOverlayLoader.LoadFirstCandidate(gnastyOutput);
    TerrainMaterialClassifier.Apply("gnastysloot", workspace.RootPath, gnastyGeometry);
    IReadOnlyDictionary<string, int> surfaces = TerrainMaterialClassifier.CountSurfaces(gnastyGeometry);
    Console.WriteLine(
        $"Source scene recovery: Stone Hill {stoneHillResult.SectorCount} sectors/{stoneHillSourceGeometry.Polygons.Count} faces; " +
        $"Gnasty's Loot {gnastyResult.SectorCount} sectors/{gnastyGeometry.Polygons.Count} faces" +
        (repairCache ? ", cache repaired" : ", cache preview only"));
    Console.WriteLine("Gnasty's Loot source surfaces: " + string.Join(", ", surfaces.Take(5).Select(pair => $"{pair.Key}={pair.Value}")));
    await ReportSourceDerivedTerrainPatchPlan(gnastyLoot, gnastyGeometry, outDir);
}

async Task ReportSourceDerivedTerrainPatchPlan(LevelDefinition level, GeometryCandidate geometry, string outDir)
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine($"{level.DisplayName} source-derived terrain patch: source disc not found; skipping.");
        return;
    }

    string sourceSearchPath = Path.Combine(outDir, $"{level.Key}-source-derived-terrain-source-search-native.json");
    TerrainSourceSearchResult sourceSearch = await TerrainSourceSearchBuilder.BuildSourceDerivedAsync(new SourceDerivedTerrainSourceSearchRequest(
        SourceImagePath: sourceImage,
        OutputPath: sourceSearchPath,
        Level: level,
        Geometry: geometry));
    HashSet<string> sourceMappedKeys = ReadTerrainSourceKeys(sourceSearchPath).ToHashSet(StringComparer.OrdinalIgnoreCase);
    TerrainPolygon[] sourceMappedCandidates = geometry.Polygons
        .Where(face =>
            face.SectorOffset >= 0 &&
            face.VertexIndexes.Count > 0 &&
            sourceMappedKeys.Contains(face.RuntimeKey))
        .ToArray();
    SourceDerivedCollisionProbeReport? collisionProbe = await ReportSourceDerivedCollisionProbe(level, geometry, outDir, sourceSearchPath, sourceSearch);
    HashSet<string> sourceDerivedCollisionKeys = (collisionProbe?.HitRuntimeKeys ?? Array.Empty<string>())
        .ToHashSet(StringComparer.OrdinalIgnoreCase);
    TerrainPolygon[] candidates = sourceMappedCandidates
        .OrderByDescending(face => sourceDerivedCollisionKeys.Contains(face.RuntimeKey))
        .ThenBy(face => face.SectorIndex)
        .ThenBy(face => face.FaceIndex)
        .Take(48)
        .ToArray();
    if (candidates.Length == 0)
    {
        Console.WriteLine($"{level.DisplayName} source-derived terrain patch: no source-mapped face found; skipping.");
        return;
    }

    string editsPath = Path.Combine(outDir, $"{level.Key}-source-derived-terrain-edits.json");
    float[] deltas = [4f, -4f, 8f, -8f];
    string lastFailure = "";
    bool movementProved = false;
    foreach (TerrainPolygon face in candidates)
    {
        foreach (float delta in deltas)
        {
            try
            {
                face.ApplyTerrainDeltaZ(delta);
                int editCount = await TerrainEditStore.SaveAsync(editsPath, [face], $"{level.DisplayName} source-derived terrain smoke");
                face.ResetTerrainEdit();
                TerrainPatchPlan plan = TerrainPatchExporter.BuildPlan(
                    sourceImage,
                    DiscImageLocator.FindCueForImage(sourceImage),
                    Path.Combine(outDir, $"{level.Key}-source-derived-terrain-smoke.bin"),
                    Path.Combine(outDir, $"{level.Key}-source-derived-terrain-smoke.cue"),
                    level,
                    "",
                    sourceSearchPath,
                    editsPath,
                    "");
                bool hasVisualPatch = plan.Patches.Any(patch =>
                    patch.RuntimeKey.Equals(face.RuntimeKey, StringComparison.OrdinalIgnoreCase) &&
                    patch.Kind.StartsWith("visual-", StringComparison.OrdinalIgnoreCase));
                bool hasCollisionPatch = plan.Patches.Any(patch => patch.Kind.StartsWith("collision-", StringComparison.OrdinalIgnoreCase));
                bool hasSourceDerivedNote = plan.Notes.Any(note => note.Contains("source-derived", StringComparison.OrdinalIgnoreCase));
                if (editCount == 1 && hasVisualPatch && hasCollisionPatch && hasSourceDerivedNote)
                {
                    Console.WriteLine($"{level.DisplayName} source-derived terrain patch: face {face.RuntimeKey}, dz={delta:+0;-0;0}, visual=True, collision=True, patches={plan.PatchCount}, sectors={sourceSearch.Report.MatchedSectorCount}/{sourceSearch.Report.SectorCount}");
                    movementProved = true;
                    break;
                }

                lastFailure = $"face={face.RuntimeKey}, dz={delta}, edits={editCount}, visual={hasVisualPatch}, collision={hasCollisionPatch}, sourceNote={hasSourceDerivedNote}, patches={plan.PatchCount}";
            }
            catch (Exception ex)
            {
                face.ResetTerrainEdit();
                lastFailure = $"face={face.RuntimeKey}, dz={delta}, {ex.Message}";
            }
        }

        if (movementProved)
            break;
    }

    if (!movementProved)
        throw new InvalidOperationException($"{level.DisplayName} source-derived terrain patch did not produce a visual+collision terrain patch. Last failure: {lastFailure}");

    Dictionary<int, int> sectorAppendSlack = BuildTerrainSectorAppendSlack(sourceSearch.Report);
    TerrainPolygon[] addCandidates = sourceMappedCandidates
        .Where(face =>
            string.Equals(face.Detail, "hp", StringComparison.OrdinalIgnoreCase) &&
            face.OriginalPoints.Count >= 3 &&
            face.VertexIndexes.Count <= face.OriginalPoints.Count &&
            sectorAppendSlack.ContainsKey(face.SectorOffset))
        .OrderByDescending(face => sourceDerivedCollisionKeys.Contains(face.RuntimeKey))
        .ThenByDescending(face => sectorAppendSlack[face.SectorOffset] >= RequiredIndependentAddCopySlack(face))
        .ThenByDescending(face => sectorAppendSlack[face.SectorOffset])
        .ThenBy(face => face.SectorIndex)
        .ThenBy(face => face.FaceIndex)
        .Take(32)
        .ToArray();
    if (addCandidates.Length == 0)
    {
        Console.WriteLine($"{level.DisplayName} source-derived add-copy terrain patch: no source-mapped high-detail sector was available for independent visible vertices.");
        return;
    }

    string addPath = Path.Combine(outDir, $"{level.Key}-source-derived-add-copy-terrain-edits.json");
    string addFailure = "";
    foreach (TerrainPolygon addFace in addCandidates)
    {
        float[] addCopyDeltas = addFace.OriginalZValues.Select((_, index) => 10f + (index * 3f)).ToArray();
        Vector2f[] addCopyXYDeltas = addFace.OriginalPoints.Select(_ => new Vector2f(64f, 24f)).ToArray();
        addFace.ApplyTerrainVertexDeltas(addCopyDeltas);
        addFace.ApplyTerrainVertexXYDeltas(addCopyXYDeltas);
        addFace.StageTerrainAddClone();
        int addEditCount = await TerrainEditStore.SaveAsync(addPath, [addFace], $"{level.DisplayName} source-derived add-copy terrain smoke");
        addFace.ResetTerrainEdit();
        TerrainPatchPlan addPlan = TerrainPatchExporter.BuildPlan(
            sourceImage,
            DiscImageLocator.FindCueForImage(sourceImage),
            Path.Combine(outDir, $"{level.Key}-source-derived-add-copy-terrain-smoke.bin"),
            Path.Combine(outDir, $"{level.Key}-source-derived-add-copy-terrain-smoke.cue"),
            level,
            "",
            sourceSearchPath,
            addPath,
            "");
        bool hasVertexCountPatch = addPlan.Patches.Any(patch => string.Equals(patch.Kind, "terrain-vertex-count-hp", StringComparison.OrdinalIgnoreCase));
        bool hasFaceCountPatch = addPlan.Patches.Any(patch => string.Equals(patch.Kind, "terrain-face-count-hp", StringComparison.OrdinalIgnoreCase));
        bool hasRepackPatch = addPlan.Patches.Any(patch => string.Equals(patch.Kind, "terrain-sector-repack-hp-add-copy", StringComparison.OrdinalIgnoreCase));
        bool hasCollisionAdd = addPlan.Patches.Any(patch => string.Equals(patch.Kind, "collision-triangle-add-copy", StringComparison.OrdinalIgnoreCase));
        bool hasLookupAdd = addPlan.Patches.Any(patch => string.Equals(patch.Kind, "collision-lookup-add-copy", StringComparison.OrdinalIgnoreCase));
        if (addEditCount == 1 && hasVertexCountPatch && hasFaceCountPatch && hasRepackPatch && hasCollisionAdd)
        {
            int addSlack = sectorAppendSlack[addFace.SectorOffset];
            int addRequired = RequiredIndependentAddCopySlack(addFace);
            Console.WriteLine($"{level.DisplayName} source-derived add-copy terrain patch: face {addFace.RuntimeKey}, slack={addSlack}/{addRequired}, independentVisual=True, collision=True, lookup={hasLookupAdd}, patches={addPlan.PatchCount}");
            return;
        }

        addFailure = $"face={addFace.RuntimeKey}, edits={addEditCount}, vertexCount={hasVertexCountPatch}, faceCount={hasFaceCountPatch}, repack={hasRepackPatch}, collision={hasCollisionAdd}, patches={addPlan.PatchCount}, skipped={string.Join(" | ", addPlan.SkippedEdits)}";
    }

    throw new InvalidOperationException($"{level.DisplayName} source-derived add-copy terrain patch failed to find a collision-backed candidate. Last failure: {addFailure}");
}

async Task<SourceDerivedCollisionProbeReport?> ReportSourceDerivedCollisionProbe(
    LevelDefinition level,
    GeometryCandidate geometry,
    string outDir,
    string sourceSearchPath,
    TerrainSourceSearchResult sourceSearch)
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine($"{level.DisplayName} source-derived collision probe: source disc not found; skipping.");
        return null;
    }

    HashSet<string> sourceMappedKeys = ReadTerrainSourceKeys(sourceSearchPath).ToHashSet(StringComparer.OrdinalIgnoreCase);
    TerrainPolygon[] candidates = geometry.Polygons
        .Where(face =>
            string.Equals(face.Detail, "hp", StringComparison.OrdinalIgnoreCase) &&
            face.Points.Count >= 3 &&
            face.ZValues.Length >= face.Points.Count &&
            sourceMappedKeys.Contains(face.RuntimeKey))
        .ToArray();

    Dictionary<CollisionWordTriple, SourceDerivedCollisionPattern> patterns = new();
    int encodedTriangleVariants = 0;
    foreach (TerrainPolygon polygon in candidates)
    {
        for (int i = 1; i < polygon.Points.Count - 1; i++)
        {
            foreach ((CollisionWordTriple triple, string pointKey) in EnumerateSourceDerivedCollisionPatterns(polygon, 0, i, i + 1))
            {
                encodedTriangleVariants++;
                if (patterns.TryGetValue(triple, out SourceDerivedCollisionPattern? existing))
                {
                    existing.DuplicateCount++;
                    continue;
                }

                patterns[triple] = new SourceDerivedCollisionPattern(polygon.RuntimeKey, i - 1, pointKey);
            }
        }
    }

    if (patterns.Count == 0)
    {
        Console.WriteLine($"{level.DisplayName} source-derived collision probe: no encodable source-derived visual triangles.");
        return null;
    }

    byte[] wad = ReadLogicalWadForSmoke(sourceImage);
    long scanStart = 0;
    long scanEnd = wad.Length;
    string scanScope = "full logical WAD";
    if (TryGetSmokeArchiveEntry(wadAnalysis, level, out SmokeArchiveEntry? archiveEntry) && archiveEntry != null)
    {
        scanStart = Math.Clamp(archiveEntry.Offset, 0, wad.Length);
        scanEnd = Math.Clamp(archiveEntry.Offset + archiveEntry.Size, scanStart, wad.Length);
        scanScope = $"WAD entry {archiveEntry.Index} 0x{scanStart:X}-0x{scanEnd:X}";
    }

    HashSet<CollisionWordTriple> hitPatterns = new();
    HashSet<int> hitOffsets = new();
    Dictionary<string, int> hitRuntimeKeys = new(StringComparer.OrdinalIgnoreCase);
    List<SourceDerivedCollisionHit> hitSamples = new();
    int totalHits = 0;
    for (int offset = (int)scanStart; offset + 12 <= scanEnd; offset += 4)
    {
        CollisionWordTriple triple = new(
            BinaryPrimitives.ReadUInt32LittleEndian(wad.AsSpan(offset, 4)),
            BinaryPrimitives.ReadUInt32LittleEndian(wad.AsSpan(offset + 4, 4)),
            BinaryPrimitives.ReadUInt32LittleEndian(wad.AsSpan(offset + 8, 4)));
        if (!patterns.TryGetValue(triple, out SourceDerivedCollisionPattern? pattern))
            continue;

        totalHits++;
        hitPatterns.Add(triple);
        hitOffsets.Add(offset);
        hitRuntimeKeys[pattern.RuntimeKey] = hitRuntimeKeys.TryGetValue(pattern.RuntimeKey, out int count) ? count + 1 : 1;
        if (hitSamples.Count < 40)
        {
            hitSamples.Add(new SourceDerivedCollisionHit(
                WadOffset: offset,
                RuntimeKey: pattern.RuntimeKey,
                TriangleIndex: pattern.TriangleIndex,
                PointKey: pattern.PointKey,
                DuplicatePatternCount: pattern.DuplicateCount));
        }
    }

    SourceDerivedCollisionBounds bounds = BuildSourceDerivedCollisionBounds(candidates);
    IReadOnlyList<SourceDerivedCollisionTableCandidate> tableCandidates = totalHits > 0
        ? BuildSourceDerivedCollisionTableCandidates(wad, (int)scanStart, (int)scanEnd, hitOffsets, bounds)
        : [];
    string[] lookupReferencedRuntimeKeys = BuildSourceDerivedLookupReferencedRuntimeKeys(wad, tableCandidates, patterns);
    string conclusion = totalHits > 0 && tableCandidates.Count > 0
        ? "Exact collision-shaped records were found for source-derived visual triangles, and plausible table spans were found around those hits. The best span/lookup candidates are now reported so exporter-side source collision index support can be targeted instead of guessed."
        : totalHits > 0
        ? "Exact collision-shaped records were found for source-derived visual triangles, but no strong contiguous table span was found yet. The offset samples still prove top-face collision patching, while side-wall/add-copy collision needs more table-boundary decoding."
        : "No exact collision-shaped records were found inside the level asset. Source-derived collision probably needs a table locator or another coordinate transform instead of a direct visual-triangle scan.";
    SourceDerivedCollisionProbeReport report = new()
    {
        LevelKey = level.Key,
        LevelName = level.DisplayName,
        ScanScope = scanScope,
        SourceSectors = sourceSearch.Report.SectorCount,
        MatchedSourceSectors = sourceSearch.Report.MatchedSectorCount,
        SourceMappedFaces = candidates.Length,
        EncodedTriangleVariants = encodedTriangleVariants,
        UniquePatternCount = patterns.Count,
        TotalHits = totalHits,
        UniquePatternHits = hitPatterns.Count,
        MatchedRuntimeKeys = hitRuntimeKeys.Count,
        LookupReferencedRuntimeKeys = lookupReferencedRuntimeKeys,
        Bounds = bounds,
        TableCandidates = tableCandidates,
        HitRuntimeKeys = hitRuntimeKeys.Keys
            .Order(StringComparer.OrdinalIgnoreCase)
            .ToArray(),
        Conclusion = conclusion,
        Hits = hitSamples
    };

    string jsonPath = Path.Combine(outDir, $"{level.Key}-source-derived-collision-probe.json");
    string markdownPath = Path.Combine(outDir, $"{level.Key}-source-derived-collision-probe.md");
    await File.WriteAllTextAsync(jsonPath, JsonSerializer.Serialize(report, new JsonSerializerOptions { WriteIndented = true }));
    await File.WriteAllTextAsync(markdownPath, BuildSourceDerivedCollisionProbeMarkdown(report));
    string bestTable = tableCandidates.Count > 0
        ? $", bestTable=0x{tableCandidates[0].StartWadOffset:X}-0x{tableCandidates[0].EndWadOffset:X} hits={tableCandidates[0].HitCount}/{tableCandidates[0].TriangleCount} lookupWords={tableCandidates[0].LookupWordCount}"
        : "";
    Console.WriteLine($"{level.DisplayName} source-derived collision probe: hits={totalHits}, unique={hitPatterns.Count}/{patterns.Count}, faces={candidates.Length}{bestTable}, report={markdownPath}");
    return report;
}

async Task ReportSourceMobyRecovery(bool repairCache)
{
    if (!File.Exists(sourceImage))
    {
        Console.WriteLine("Source moby recovery: source disc not found; skipping.");
        return;
    }

    LevelDefinition? gnastyLoot = catalog.FindByKey("gnastysloot");
    if (gnastyLoot == null)
    {
        Console.WriteLine("Source moby recovery: Gnasty's Loot is missing from the level catalog.");
        return;
    }

    string outDir = Path.Combine(workspace.RootPath, "_local", "smoke");
    Directory.CreateDirectory(outDir);
    string outputPath = repairCache
        ? Path.Combine(workspace.RootPath, "editor-cache", "gnastysloot-mobys.json")
        : Path.Combine(outDir, "gnastysloot-source-mobys.json");

    SourceMobyCacheResult result = await SourceMobyCacheBuilder.BuildAsync(sourceImage, gnastyLoot, outputPath);
    if (result.MobyCount != gnastyLoot.SourceRecordCount)
        throw new InvalidOperationException($"Gnasty's Loot source moby recovery produced {result.MobyCount} records, expected {gnastyLoot.SourceRecordCount}.");
    if (result.TreasureValue != 2000)
        throw new InvalidOperationException($"Gnasty's Loot source moby recovery found {result.TreasureValue} treasure value, expected 2000.");

    List<Moby> mobys = MobyLoader.LoadCached(outputPath).ToList();
    MobyMetadataEnricher.Apply(workspace, "gnastysloot", mobys);
    if (!mobys.Any(moby => moby.DisplayLabel.Contains("thief", StringComparison.OrdinalIgnoreCase)))
        throw new InvalidOperationException("Gnasty's Loot source moby recovery did not promote any thief records.");

    Console.WriteLine(
        $"Source moby recovery: Gnasty's Loot {result.MobyCount} source mobys, treasure value {result.TreasureValue}" +
        (repairCache ? ", cache repaired" : ", cache preview only"));
    ReportIdentityCoverage("gnastysloot source", mobys);
}

void ReportBuiltInTerrainMaterialOverrides()
{
    List<(string LevelKey, int[] TextureIds, string Surface)> checks =
    [
        ("stonehill", [30], "sand"),
        ("stonehill", [32], "water"),
        ("artisans", [39, 64], "grass"),
        ("peacekeepers", [0, 1, 2], "water"),
        ("peacekeepers", [30, 31, 32, 33, 34, 35, 36], "cliff"),
        ("beastmakers", [41], "ooze"),
        ("icecavern", [3, 4, 11, 12, 14, 15, 16, 17, 18, 21, 23, 26, 32, 33, 34, 35, 36, 39, 40, 41, 42, 47, 50, 51, 52, 53, 54], "ice"),
        ("clifftown", [35, 36, 38], "lava"),
        ("jacques", [52, 53], "lava"),
        ("toasty", [50, 51, 52], "lava"),
        ("gnastysloot", [64, 14, 47, 3, 11], "water"),
        ("gnastysloot", [24], "lava"),
        ("gnastysloot", [68, 72, 127, 28, 27, 10, 61, 8, 26, 25], "grass"),
        ("gnastysloot", [38, 53, 45, 46, 41, 42, 43, 44, 39, 40, 30, 32, 33, 29, 34, 35, 36, 48, 50], "brick")
    ];

    List<string> summaries = new();
    foreach ((string levelKey, int[] textureIds, string surface) in checks)
    {
        string overlayPath = Path.Combine(workspace.RootPath, "editor-cache", $"{levelKey}-runtime-scene-editor-overlay.json");
        if (!File.Exists(overlayPath))
            continue;

        GeometryCandidate geometry = GeometryOverlayLoader.LoadFirstCandidate(overlayPath);
        TerrainMaterialClassifier.Apply(levelKey, workspace.RootPath, geometry);
        foreach (int textureId in textureIds)
        {
            List<TerrainPolygon> faces = geometry.Polygons.Where(face => face.TextureId == textureId).ToList();
            if (faces.Count == 0)
                throw new InvalidOperationException($"{levelKey} terrain texture {textureId} was not present for built-in material override smoke.");

            bool allMatch = faces.All(face =>
                string.Equals(TerrainMaterialClassifier.NormalizeSurfaceName(face.Surface), surface, StringComparison.OrdinalIgnoreCase) &&
                string.Equals(face.SurfaceSource, "override", StringComparison.OrdinalIgnoreCase));
            if (!allMatch)
                throw new InvalidOperationException($"{levelKey} terrain texture {textureId} was not classified as built-in {surface} override.");
        }

        summaries.Add($"{levelKey}:{surface} textures {string.Join(",", textureIds)}");
    }

    Console.WriteLine($"Built-in terrain material overrides: {string.Join("; ", summaries)}");
}

void ReportTerrainPalettePresetCoverage()
{
    string[] matchableSurfaces =
    [
        "grass",
        "water",
        "sand",
        "stone",
        "ground",
        "cliff",
        "brick",
        "ice",
        "lava",
        "ooze"
    ];

    List<string> failures = [];
    HashSet<string> presetIds = new(StringComparer.OrdinalIgnoreCase);
    foreach (TerrainPalettePreset preset in TerrainPalettePresetCatalog.Presets)
    {
        if (!presetIds.Add(preset.Id))
            failures.Add($"duplicate preset id {preset.Id}");

        string normalizedSurface = TerrainMaterialClassifier.NormalizeSurfaceName(preset.Surface);
        if (!matchableSurfaces.Contains(normalizedSurface, StringComparer.OrdinalIgnoreCase))
            failures.Add($"{preset.DisplayName} uses unsupported surface {preset.Surface}");
    }

    foreach (string surface in matchableSurfaces)
    {
        TerrainPalettePreset preset = TerrainPalettePresetCatalog.DefaultForSurface(surface);
        string presetSurface = TerrainMaterialClassifier.NormalizeSurfaceName(preset.Surface);
        if (!string.Equals(presetSurface, surface, StringComparison.OrdinalIgnoreCase))
            failures.Add($"{surface} resolves to {preset.DisplayName}/{preset.Surface}");
    }

    if (failures.Count > 0)
        throw new InvalidOperationException($"Terrain palette preset coverage failed: {string.Join("; ", failures)}");

    Console.WriteLine($"Terrain palette preset coverage: {matchableSurfaces.Length} matchable surface(s), {TerrainPalettePresetCatalog.Presets.Count} preset(s), all resolve directly");
}

